use std::collections::HashMap;

type Ull = u64;

fn binomial(m: Ull, mut n: Ull) -> Ull {
    let mut r = 1;
    let mut d = m - n;
    if d > n {
        n = d;
        d = m - n;
    }

    let mut m = m;
    while m > n {
        r *= m;
        m -= 1;
        while d > 1 && r % d == 0 {
            r /= d;
            d -= 1;
        }
    }

    r
}

fn catalan1(n: usize) -> Ull {
    binomial(2 * n as Ull, n as Ull) / (1 + n as Ull)
}

fn catalan2(n: usize, memo: &mut HashMap<usize, Ull>) -> Ull {
    if n == 0 {
        return 1;
    }
    if let Some(&value) = memo.get(&n) {
        return value;
    }
    let result: Ull = (0..n).map(|i| catalan2(i, memo) * catalan2(n - 1 - i, memo)).sum();
    memo.insert(n, result);
    result
}

fn catalan3(n: usize) -> Ull {
    if n == 0 {
        1
    } else {
        2 * (2 * n as Ull - 1) * catalan3(n - 1) / (1 + n as Ull)
    }
}

fn main() {
    println!("\tdirect\tsumming\tfrac");
    let mut memo = HashMap::new();
    for i in 0..16 {
        println!(
            "{}\t{}\t{}\t{}",
            i,
            catalan1(i),
            catalan2(i, &mut memo),
            catalan3(i)
        );
    }
}

