#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>

#define MAXLEN 100 

int makehist(unsigned char *S,int *hist,int len){
	int wherechar[256];
	int i,histlen;
	histlen=0;
	for(i=0;i<256;i++)wherechar[i]=-1;
	for(i=0;i<len;i++){
		if(wherechar[(int)S[i]]==-1){
			wherechar[(int)S[i]]=histlen;
			histlen++;
		}
		hist[wherechar[(int)S[i]]]++;
	}
	return histlen;
}

double entropy(int *hist,int histlen,int len){
	int i;
	double H;
	H=0;
	for(i=0;i<histlen;i++){
		H-=(double)hist[i]/len*log2((double)hist[i]/len);
	}
	return H;
}

int main(void){
	unsigned char S[MAXLEN];
	int len,*hist,histlen;
	double H;
	scanf("%[^\n]",S);
	len=strlen(S);
	hist=(int*)calloc(len,sizeof(int));
	histlen=makehist(S,hist,len);

	H=entropy(hist,histlen,len);
	printf("%lf\n",H);
	return 0;
}

9ea403f8600c2e6b9fd6e1ab9ddf4712.rust_code:
use std::collections::HashMap;

fn makehist(s: &[u8], hist: &mut HashMap<u8, usize>) -> usize {
    let mut histlen = 0;
    for &byte in s {
        if !hist.contains_key(&byte) {
            hist.insert(byte, histlen);
            histlen += 1;
        }
        *hist.get_mut(&byte).unwrap() += 1;
    }
    histlen
}

fn entropy(hist: &HashMap<u8, usize>, histlen: usize, len: usize) -> f64 {
    let mut h = 0.0;
    for &count in hist.values() {
        let p = count as f64 / len as f64;
        h -= p * p.log2();
    }
    h
}

fn main() {
    use std::io::{self, Read};

    let mut input = String::new();
    io::stdin().read_line(&mut input).expect("Failed to read line");
    let s = input.trim_end().as_bytes();
    let mut hist = HashMap::new();
    let histlen = makehist(s, &mut hist);

    let h = entropy(&hist, histlen, s.len());
    println!("{:.6}", h);
}

