use std::fmt;

#[derive(Debug, Clone, Copy)]
struct Fraction {
    num: i32,
    den: i32,
}

impl Fraction {
    fn new(num: i32, den: i32) -> Self {
        Fraction { num, den }
    }
}

fn r2cf(fraction: &mut Fraction) -> Option<i32> {
    if fraction.den == 0 {
        None
    } else {
        let quotient = fraction.num / fraction.den;
        let temp = fraction.num;
        fraction.num = fraction.den;
        fraction.den = temp % fraction.den;
        Some(quotient)
    }
}

fn main() {
    let examples = [
        Fraction::new(1, 2),
        Fraction::new(3, 1),
        Fraction::new(23, 8),
        Fraction::new(13, 11),
        Fraction::new(22, 7),
        Fraction::new(-151, 77),
    ];

    let sqrt2 = [
        Fraction::new(14142, 10000),
        Fraction::new(141421, 100000),
        Fraction::new(1414214, 1000000),
        Fraction::new(14142136, 10000000),
    ];

    let pi = [
        Fraction::new(31, 10),
        Fraction::new(314, 100),
        Fraction::new(3142, 1000),
        Fraction::new(31428, 10000),
        Fraction::new(314285, 100000),
        Fraction::new(3142857, 1000000),
        Fraction::new(31428571, 10000000),
        Fraction::new(314285714, 100000000),
    ];

    println!("Running the examples:");

    for mut example in examples.iter().cloned() {
        print!("\nFor N = {}, D = {}:", example.num, example.den);
        while let Some(quotient) = r2cf(&mut example) {
            print!(" {} ", quotient);
        }
    }

    println!("\n\nRunning for √2:");

    for mut sqrt in sqrt2.iter().cloned() {
        print!("\nFor N = {}, D = {}:", sqrt.num, sqrt.den);
        while let Some(quotient) = r2cf(&mut sqrt) {
            print!(" {} ", quotient);
        }
    }

    println!("\n\nRunning for π:");

    for mut p in pi.iter().cloned() {
        print!("\nFor N = {}, D = {}:", p.num, p.den);
        while let Some(quotient) = r2cf(&mut p) {
            print!(" {} ", quotient);
        }
    }
}

