    if n % 2 == 0 {
        return false;
    }
    let mut i = 3;
    while i * i <= n {
        if n % i == 0 {
            return false;
        }
        i += 2;
    }
    true
}

fn main() {
    let mut n = 600851475143;
    let mut j = 3;

    while !is_prime(n) {
        if n % j == 0 {
            n /= j;
        }
        j += 2;
    }
    println!("{}", n);
}

