#define ANIMATE_VT100_POSIX
#include <stdio.h>
#include <string.h>
#ifdef ANIMATE_VT100_POSIX
#include <time.h>
#endif

char world_7x14[2][512] = {
  {
    "+-----------+\n"
    "|tH.........|\n"
    "|.   .      |\n"
    "|   ...     |\n"
    "|.   .      |\n"
    "|Ht.. ......|\n"
    "+-----------+\n"
  }
};

void next_world(const char *in, char *out, int w, int h)
{
  int i;

  for (i = 0; i < w*h; i++) {
    switch (in[i]) {
    case ' ': out[i] = ' '; break;
    case 't': out[i] = '.'; break;
    case 'H': out[i] = 't'; break;
    case '.': {
      int hc = (in[i-w-1] == 'H') + (in[i-w] == 'H') + (in[i-w+1] == 'H') +
               (in[i-1]   == 'H')                    + (in[i+1]   == 'H') +
               (in[i+w-1] == 'H') + (in[i+w] == 'H') + (in[i+w+1] == 'H');
      out[i] = (hc == 1 || hc == 2) ? 'H' : '.';
      break;
    }
    default:
      out[i] = in[i];
    }
  }
  out[i] = in[i];
}

int main()
{
  int f;

  for (f = 0; ; f = 1 - f) {
    puts(world_7x14[f]);
    next_world(world_7x14[f], world_7x14[1-f], 14, 7);
#ifdef ANIMATE_VT100_POSIX
    printf("\x1b[%dA", 8);
    printf("\x1b[%dD", 14);
    {
      static const struct timespec ts = { 0, 100000000 };
      nanosleep(&ts, 0);
    }
#endif
  }

  return 0;
}

6f6ef344b65f7a5ca998fecc703a7438.rust_code:
use std::thread;
use std::time::Duration;

const WORLD_7X14: [&str; 2] = [
    "+-----------+\n\
     |tH.........|\n\
     |.   .      |\n\
     |   ...     |\n\
     |.   .      |\n\
     |Ht.. ......|\n\
     +-----------+\n",
    "+-----------+\n\
     |.......... |\n\
     |           |\n\
     |           |\n\
     |           |\n\
     |           |\n\
     +-----------+\n",
];

fn next_world(in_world: &str, out_world: &mut [u8], width: usize, height: usize) {
    let bytes = in_world.as_bytes();
    for (i, byte) in bytes.iter().enumerate() {
        if i >= width * height {
            break;
        }
        out_world[i] = match byte {
            b' ' => b' ',
            b't' => b'.',
            b'H' => b't',
            b'.' => {
                let mut hc = 0;
                if i >= width + 1 && bytes[i - width - 1] == b'H' { hc += 1; }
                if i >= width && bytes[i - width] == b'H' { hc += 1; }
                if i >= width - 1 && bytes[i - width + 1] == b'H' { hc += 1; }
                if i >= 1 && bytes[i - 1] == b'H' { hc += 1; }
                if i < width * height - 1 && bytes[i + 1] == b'H' { hc += 1; }
                if i < width * height - width - 1 && bytes[i + width - 1] == b'H' { hc += 1; }
                if i < width * height - width && bytes[i + width] == b'H' { hc += 1; }
                if i < width * height - width + 1 && bytes[i + width + 1] == b'H' { hc += 1; }
                if hc == 1 || hc == 2 { b'H' } else { b'.' }
            }
            _ => *byte,
        };
    }
}

fn main() {
    let mut worlds = [vec![0; 512], vec![0; 512]];
    worlds[0].copy_from_slice(WORLD_7X14[0].as_bytes());

    let mut frame = 0;
    loop {
        print!("{}", std::str::from_utf8(&worlds[frame]).unwrap());
        next_world(&WORLD_7X14[frame], &mut worlds[1 - frame], 14, 7);
        print!("\x1b[8A\x1b[14D");
        thread::sleep(Duration::from_millis(100));
        frame = 1 - frame;
    }
}

