use std::thread;
use std::time::Duration;

const WORLD_7X14: [&str; 2] = [
    "+-----------+\n\
     |tH.........|\n\
     |.   .      |\n\
     |   ...     |\n\
     |.   .      |\n\
     |Ht.. ......|\n\
     +-----------+\n",
    "+-----------+\n\
     |.......... |\n\
     |           |\n\
     |           |\n\
     |           |\n\
     |           |\n\
     +-----------+\n",
];

fn next_world(in_world: &str, out_world: &mut [u8], width: usize, height: usize) {
    let bytes = in_world.as_bytes();
    for (i, byte) in bytes.iter().enumerate() {
        if i >= width * height {
            break;
        }
        out_world[i] = match byte {
            b' ' => b' ',
            b't' => b'.',
            b'H' => b't',
            b'.' => {
                let mut hc = 0;
                if i >= width + 1 && bytes[i - width - 1] == b'H' { hc += 1; }
                if i >= width && bytes[i - width] == b'H' { hc += 1; }
                if i >= width - 1 && bytes[i - width + 1] == b'H' { hc += 1; }
                if i >= 1 && bytes[i - 1] == b'H' { hc += 1; }
                if i < width * height - 1 && bytes[i + 1] == b'H' { hc += 1; }
                if i < width * height - width - 1 && bytes[i + width - 1] == b'H' { hc += 1; }
                if i < width * height - width && bytes[i + width] == b'H' { hc += 1; }
                if i < width * height - width + 1 && bytes[i + width + 1] == b'H' { hc += 1; }
                if hc == 1 || hc == 2 { b'H' } else { b'.' }
            }
            _ => *byte,
        };
    }
}

fn main() {
    let mut worlds = [vec![0; 512], vec![0; 512]];
    worlds[0].copy_from_slice(WORLD_7X14[0].as_bytes());

    let mut frame = 0;
    loop {
        print!("{}", std::str::from_utf8(&worlds[frame]).unwrap());
        next_world(&WORLD_7X14[frame], &mut worlds[1 - frame], 14, 7);
        print!("\x1b[8A\x1b[14D");
        thread::sleep(Duration::from_millis(100));
        frame = 1 - frame;
    }
}

