use std::fmt;
use std::str::FromStr;

#[derive(Debug)]
struct Cidr {
    address: u32,
    mask_length: u8,
}

impl Cidr {
    fn parse(s: &str) -> Result<Self, &'static str> {
        let parts: Vec<&str> = s.split('/').collect();
        if parts.len() != 2 {
            return Err("Invalid format");
        }

        let ip_parts: Vec<&str> = parts[0].split('.').collect();
        if ip_parts.len() != 4 {
            return Err("Invalid IP address");
        }

        let mut address = 0;
        for (i, part) in ip_parts.iter().enumerate() {
            let byte = u8::from_str(part).map_err(|_| "Invalid IP byte")?;
            address |= (byte as u32) << (24 - i * 8);
        }

        let mask_length = u8::from_str(parts[1]).map_err(|_| "Invalid mask length")?;
        if mask_length > 32 {
            return Err("Mask length too large");
        }

        let mask = !((1 << (32 - mask_length)) - 1);
        address &= mask;

        Ok(Cidr { address, mask_length })
    }

    fn format(&self) -> String {
        let a = (self.address >> 24) & 0xFF;
        let b = (self.address >> 16) & 0xFF;
        let c = (self.address >> 8) & 0xFF;
        let d = self.address & 0xFF;
        format!("{}.{}.{}.{}/{}", a, b, c, d, self.mask_length)
    }
}

fn main() {
    let tests = [
        "87.70.141.1/22",
        "36.18.154.103/12",
        "62.62.197.11/29",
        "67.137.119.181/4",
        "161.214.74.21/24",
        "184.232.176.184/18",
    ];

    for test in tests.iter() {
        match Cidr::parse(test) {
            Ok(cidr) => println!("{:<18} -> {}", test, cidr.format()),
            Err(e) => eprintln!("{}: {}", test, e),
        }
    }
}

