fn gcd(mut a: i32, mut b: i32) -> i32 {
    if a < b {
        std::mem::swap(&mut a, &mut b);
    }
    loop {
        let r = a % b;
        if r == 0 {
            break;
        } else {
            a = b;
            b = r;
        }
    }
    b
}

fn not_in_list(num: i32, triplets_list: &[i32]) -> bool {
    !triplets_list.contains(&num)
}

fn main() {
    let mut coprime = vec![1, 2];
    let mut ntrip = 2;
    let mut n = 3;

    while n < 50 {
        let gcd1 = gcd(n, coprime[ntrip - 1]);
        let gcd2 = gcd(n, coprime[ntrip - 2]);

        if gcd1 == 1 && gcd2 == 1 && not_in_list(n, &coprime) {
            coprime.push(n);
            ntrip += 1;
            n = 3;
        } else {
            n += 1;
        }
    }

    for (i, &value) in coprime.iter().enumerate() {
        print!("{:2} ", value);
        if (i + 1) % 10 == 0 {
            println!();
        }
    }

    println!("\n\nNumber of elements in coprime triplets: {}\n\n", ntrip);
}

