use std::io::{self, Write};

#[derive(Debug)]
struct Cell {
    data: i32,
    next: Option<Box<Cell>>,
}

type List = Option<Box<Cell>>;

fn add_to_list(mut list: List, num: i32) -> List {
    match list {
        None => Some(Box::new(Cell { data: num, next: None })),
        Some(ref mut head) => {
            let mut current = head;
            while let Some(ref mut next) = current.next {
                current = next;
            }
            current.next = Some(Box::new(Cell { data: num, next: None }));
            list
        }
    }
}

fn delete_from_list(mut list: List, pos: usize) -> List {
    if pos == 0 {
        return list;
    }

    match list {
        None => list,
        Some(ref mut head) if pos == 1 => head.next.take(),
        Some(ref mut head) => {
            let mut current = head;
            for _ in 1..pos - 1 {
                if let Some(ref mut next) = current.next {
                    current = next;
                } else {
                    break;
                }
            }
            current.next = current.next.take().and_then(|mut node| {
                node.next.take();
                Some(node)
            });
            list
        }
    }
}

fn print_list(list: &List) {
    print!("List contains following elements: ");
    let mut current = list;
    while let Some(ref cell) = current {
        print!("{} ", cell.data);
        current = &cell.next;
    }
    println!();
}

