    let args: Vec<String> = std::env::args().collect();
    if args.len() == 1 {
        println!("Usage: {} <list of integers to be inserted into the list>", args[0]);
        return;
    }

    let mut list: List = None;
    for arg in &args[1..] {
        if let Ok(num) = arg.parse::<i32>() {
            list = add_to_list(list, num);
        }
