    let mut try_max = 0;
    let mut count_list = [1, 0, 0];

    for i in 2..=20000 {
        try_max = i / 2;
        sum = 1;

        for j in 2..try_max {
            if i % j != 0 {
                continue;
            }

            try_max = i / j;

            sum += j;
            if j != try_max {
                sum += try_max;
            }
