    let a = vec![-1, -2, 3, 5, 6, -2, -1, 4, -4, 2, -1];
    let r = max_subseq(&a);
    println!("Max sum = {}", r.sum);
    for &value in &a[r.start..r.end] {
        print!("{} ", value);
    }
    println!();
}

