    let mut end = 0;
    let mut i = 0;

    for (j, &value) in sequence.iter().enumerate() {
        this_sum += value;
        if this_sum < 0 {
            i = j + 1;
            this_sum = 0;
        } else if this_sum > max_sum {
            max_sum = this_sum;
            start = i;
            end = j + 1;
        }
    }

    if start < end {
        Range { start, end, sum: max_sum }
    } else {
        Range { start: 0, end: 0, sum: 0 }
    }
}

fn main() {
    let a = vec![-1, -2, 3, 5, 6, -2, -1, 4, -4, 2, -1];
    let r = max_subseq(&a);
    println!("Max sum = {}", r.sum);
    for &value in &a[r.start..r.end] {
        print!("{} ", value);
    }
    println!();
}

