#include <stdio.h>
#include <ctype.h>

static int 
owp(int odd)
{
        int ch, ret;
        ch = getc(stdin);
        if (!odd) {
                putc(ch, stdout);
                if (ch == EOF || ch == '.')
                        return EOF;
                if (ispunct(ch))
                        return 0;
                owp(odd);
                return 0;
        } else {
                if (ispunct(ch))
                        return ch; 
                ret = owp(odd);
                putc(ch, stdout);
                return ret;
        }
}

int
main(int argc, char **argv)
{
        int ch = 1;
        while ((ch = owp(!ch)) != EOF) {
                if (ch)
                        putc(ch, stdout);
                if (ch == '.')
                        break;
        }
        return 0;
}

e3592f9f7591a75e26a37b29cb4adfa9.rust_code:
use std::io::{self, Read, Write};

fn owp(odd: bool) -> Option<char> {
    let mut stdin = io::stdin().lock();
    let mut buffer = [0; 1];
    if stdin.read_exact(&mut buffer).is_err() {
        return None;
    }
    let ch = buffer[0] as char;

    if !odd {
        print!("{}", ch);
        if ch == '.' || ch == '\x04' { // '\x04' represents EOF on some systems
            return None;
        }
        if ch.is_ascii_punctuation() {
            return Some(ch);
        }
        owp(odd);
        Some(ch)
    } else {
        if ch.is_ascii_punctuation() {
            return Some(ch);
        }
        let ret = owp(odd);
        print!("{}", ch);
        ret
    }
}

fn main() {
    let mut ch = Some('1');
    while let Some(c) = ch {
        ch = owp(c != '1');
        if let Some(c) = ch {
            print!("{}", c);
            if c == '.' {
                break;
            }
        }
    }
}

