#include <stdio.h>
#include <time.h>

int identity(int x) { return x; }

int sum(int s)
{
  int i;
  for(i=0; i < 1000000; i++) s += i;
  return s;
}

#ifdef CLOCK_PROCESS_CPUTIME_ID

#define CLOCKTYPE  CLOCK_PROCESS_CPUTIME_ID
#else

#define CLOCKTYPE  CLOCK_MONOTONIC
#endif

double time_it(int (*action)(int), int arg)
{
  struct timespec tsi, tsf;

  clock_gettime(CLOCKTYPE, &tsi);
  action(arg);
  clock_gettime(CLOCKTYPE, &tsf);

  double elaps_s = difftime(tsf.tv_sec, tsi.tv_sec);
  long elaps_ns = tsf.tv_nsec - tsi.tv_nsec;
  return elaps_s + ((double)elaps_ns) / 1.0e9;
}

int main()
{
  printf("identity (4) takes %lf s\n", time_it(identity, 4));
  printf("sum      (4) takes %lf s\n", time_it(sum, 4));
  return 0;
}

79b867a31f20ad184ae21ba1e0f61a50.rust_code:
use std::time::{Instant, Duration};

fn identity(x: i32) -> i32 {
    x
}

fn sum(mut s: i32) -> i32 {
    for i in 0..1_000_000 {
        s += i;
    }
    s
}

fn time_it<F>(action: F, arg: i32) -> f64
where
    F: Fn(i32) -> i32,
{
    let start = Instant::now();
    action(arg);
    let duration = start.elapsed();
    duration.as_secs() as f64 + duration.subsec_nanos() as f64 * 1e-9
}

fn main() {
    println!("identity (4) takes {} s", time_it(identity, 4));
    println!("sum      (4) takes {} s", time_it(sum, 4));
}

