#include<string.h>
#include<stdlib.h>
#include<locale.h>
#include<stdio.h>
#include<wchar.h>
#include<math.h>

int main(int argC,char* argV[])
{
	double* arr,min,max;
	char* str;
	int i,len;
	if(argC == 1)
		printf("Usage : %s <data points separated by spaces or commas>",argV[0]);
	else{
		arr = (double*)malloc((argC-1)*sizeof(double));
		for(i=1;i<argC;i++){
			len = strlen(argV[i]);

			if(argV[i][len-1]==','){
				str = (char*)malloc(len*sizeof(char));
				strncpy(str,argV[i],len-1);
				arr[i-1] = atof(str);
				free(str);
			}
			else
				arr[i-1] = atof(argV[i]);
			if(i==1){
				min = arr[i-1];
				max = arr[i-1];
			}
			else{
				min=(min<arr[i-1]?min:arr[i-1]);
				max=(max>arr[i-1]?max:arr[i-1]);
			}
		}

		printf("\n%Max : %lf,Min : %lf,Range : %lf\n",max,min,max-min);

		setlocale(LC_ALL, "");

		for(i=1;i<argC;i++){
			printf("%lc", (wint_t)(9601 + (int)ceil((arr[i-1]-min)/(max-min)*7)));
		}
	}
	return 0;
}

d7d327afc9b6847a2a2e1b72abf31e4d.rust_code:
use std::env;
use std::str::FromStr;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() == 1 {
        println!("Usage: {} <data points separated by spaces or commas>", args[0]);
    } else {
        let mut arr = Vec::with_capacity(args.len() - 1);
        let mut min = f64::INFINITY;
        let mut max = f64::NEG_INFINITY;

        for arg in &args[1..] {
            let trimmed_arg = if arg.ends_with(',') {
                &arg[..arg.len() - 1]
            } else {
                arg
            };
            match f64::from_str(trimmed_arg) {
                Ok(num) => {
                    arr.push(num);
                    if num < min { min = num; }
                    if num > max { max = num; }
                },
                Err(_) => {
                    eprintln!("Invalid number: {}", trimmed_arg);
                    return;
                }
            }
        }

        println!("\nMax: {}, Min: {}, Range: {}", max, min, max - min);

        for &num in &arr {
            let bar_char = 9601 + ((num - min) / (max - min) * 7.0).ceil() as u32;
            print!("{}", char::from_u32(bar_char).unwrap_or(' '));
        }
        println!();
    }
}

