use std::io::{self, BufRead};

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let num: usize = input.trim().parse().expect("Please enter a valid number");

    let mut list = Vec::with_capacity(num);

    for _ in 0..num {
        input.clear();
        io::stdin().read_line(&mut input)?;
        list.push(input.clone());
    }

    for line in &list {
        print!("{}", line);
    }

    Ok(())
}

