#include <stdbool.h>
#include <stdio.h>

bool isPrime(int n) {
    if (n < 0) {
        n = -n;
    }
    return n == 2 || n == 3 || n == 5 || n == 7;
}

int main() {
    int count = 0;
    int i, j;
    int d[3];
    int dptr;

    printf("Strange numbers in the open interval (100, 500) are:\n");
    for (i = 101; i < 500; i++) {
        dptr = 0;
        j = i;
        while (j > 0) {
            d[dptr++] = j % 10;
            j /= 10;
        }
        if (isPrime(d[0] - d[1]) && isPrime(d[1] - d[2])) {
            printf("%d ", i);
            count++;
            if (count % 10 == 0) {
                printf("\n");
            }
        }
    }
    if (count % 10 != 0) {
        printf("\n");
    }
    printf("\n%d strange numbers in all.\n", count);

    return 0;
}

e88596309bc2c230651e180d7367a691.rust_code:
fn is_prime(n: i32) -> bool {
    let n = n.abs();
    n == 2 || n == 3 || n == 5 || n == 7
}

fn main() {
    let mut count = 0;
    println!("Strange numbers in the open interval (100, 500) are:");
    for i in 101..500 {
        let mut digits = Vec::new();
        let mut j = i;
        while j > 0 {
            digits.push(j % 10);
            j /= 10;
        }
        if let [_, d1, d2] = &digits[..] {
            if is_prime(d1 - d2) && is_prime(d2 - &digits[0]) {
                print!("{} ", i);
                count += 1;
                if count % 10 == 0 {
                    println!();
                }
            }
        }
    }
    if count % 10 != 0 {
        println!();
    }
    println!("\n{} strange numbers in all.", count);
}

