#include<stdio.h>
#include<stdlib.h>

#define min(a, b) (a<=b?a:b)

void minab( unsigned int n ) {
    int i, j;
    for(i=0;i<n;i++) {
        for(j=0;j<n;j++) {
            printf( "%2d  ", min( min(i, n-1-i), min(j, n-1-j) ));
        }
        printf( "\n" );
    }
    return;
}

int main(void) {
    minab(10);
    return 0;
}

5f5a7bc7500dbb882d4261cbce3a0bd1.rust_code:
fn min_ab(n: usize) {
    for i in 0..n {
        for j in 0..n {
            let value = std::cmp::min(std::cmp::min(i, n - 1 - i), std::cmp::min(j, n - 1 - j));
            print!("{:2}  ", value);
        }
        println!();
    }
}

fn main() {
    min_ab(10);
}

