#include <stdio.h>
#include <stdlib.h>

int isprime( long int n ) {
    int i=3;
    if(!(n%2)) return 0;
    while( i*i < n ) {
        if(!(n%i)) return 0;
        i+=2;
    }
    return 1;
}

int main(void) {
    long int n=600851475143, j=3;

    while(!isprime(n)) {
        if(!(n%j)) n/=j;
        j+=2;
    }
    printf( "%ld\n", n );
    return 0;
}

6a4098cbddaba26d310410ec70a86a30.rust_code:
fn is_prime(n: u64) -> bool {
    if n % 2 == 0 {
        return false;
    }
    let mut i = 3;
    while i * i <= n {
        if n % i == 0 {
            return false;
        }
        i += 2;
    }
    true
}

fn main() {
    let mut n = 600851475143;
    let mut j = 3;

    while !is_prime(n) {
        if n % j == 0 {
            n /= j;
        }
        j += 2;
    }
    println!("{}", n);
}

