#include <stdlib.h>  
#include <string.h>  
#include <strings.h> 

int mycmp(const void *s1, const void *s2)
{
    const char *l = *(const char **)s1, *r = *(const char **)s2;
    size_t ll = strlen(l), lr = strlen(r);

    if (ll > lr) return -1;
    if (ll < lr) return 1;
    return strcasecmp(l, r);
}

int main()
{
    const char *strings[] = {
      "Here", "are", "some", "sample", "strings", "to", "be", "sorted" };

    qsort(strings, sizeof(strings)/sizeof(*strings), sizeof(*strings), mycmp);
    return 0;
}

3ae37746ff8d461928f69b5cddea72e2.rust_code:
use std::cmp::Ordering;

fn mycmp(s1: &&str, s2: &&str) -> Ordering {
    let ll = s1.len();
    let lr = s2.len();

    match ll.cmp(&lr) {
        Ordering::Equal => s1.to_ascii_lowercase().cmp(&s2.to_ascii_lowercase()),
        other => other.reverse(),
    }
}

fn main() {
    let mut strings = vec![
        "Here", "are", "some", "sample", "strings", "to", "be", "sorted",
    ];

    strings.sort_by(mycmp);

    for s in &strings {
        println!("{}", s);
    }
}

