fn insertion_sort(arr: &mut [i32]) {
    for i in 1..arr.len() {
        let key = arr[i];
        let mut j = i;
        while j > 0 && key < arr[j - 1] {
            arr[j] = arr[j - 1];
            j -= 1;
        }
        arr[j] = key;
    }
}

fn main() {
    let mut a = vec![4, 65, 2, -31, 0, 99, 2, 83, 782, 1];

    for (i, &value) in a.iter().enumerate() {
        print!("{}{}", value, if i == a.len() - 1 { "\n" } else { " " });
    }

    insertion_sort(&mut a);

    for (i, &value) in a.iter().enumerate() {
        print!("{}{}", value, if i == a.len() - 1 { "\n" } else { " " });
    }
}

