#include<stdio.h>
#include<stdlib.h>

int isprime( int p ) {
    int i;
    if(p==2) return 1;
    if(!(p%2)) return 0;
    for(i=3; i*i<=p; i+=2) {
       if(!(p%i)) return 0;
    }
    return 1;
}

int nextprime( int p ) {
    int i=0;
    if(p==0) return 2;
    if(p<3) return p+1;
    while(!isprime(++i + p));
    return i+p;
}

int issquare( int p ) {
    int i;
    for(i=0;i*i<p;i++);
    return i*i==p;
}

int main(void) {
    int i=3, j=2;
    for(i=3;j<=1000000;i=j) {
        j=nextprime(i);
        if(j-i>36&&issquare(j-i)) printf( "%d %d %d\n", i, j, j-i );
    }
    return 0;
}

7db7dd7189c90f2ffd0717f3d4de3896.rust_code:
fn is_prime(p: i32) -> bool {
    if p == 2 {
        return true;
    }
    if p % 2 == 0 {
        return false;
    }
    (3..=((p as f64).sqrt() as i32)).step_by(2).all(|i| p % i != 0)
}

fn next_prime(mut p: i32) -> i32 {
    if p == 0 {
        return 2;
    }
    if p < 3 {
        return p + 1;
    }
    loop {
        p += 1;
        if is_prime(p) {
            return p;
        }
    }
}

fn is_square(p: i32) -> bool {
    let root = (p as f64).sqrt() as i32;
    root * root == p
}

fn main() {
    let mut i = 3;
    let mut j = 2;
    while j <= 1_000_000 {
        i = j;
        j = next_prime(i);
        if j - i > 36 && is_square(j - i) {
            println!("{} {} {}", i, j, j - i);
        }
    }
}

