use std::vec::Vec;

struct Factors {
    list: Vec<i32>,
    count: usize,
}

impl Factors {
    fn new() -> Self {
        Factors {
            list: Vec::new(),
            count: 0,
        }
    }

    fn xfer_factors(&mut self, flist: &[i32]) {
        self.list.extend_from_slice(flist);
        self.count = self.list.len();
    }
}

fn factor(num: i32, fctrs: &mut Factors) {
    let mut flist = [0; 301];
    let mut flix = 0;
    fctrs.list.clear();
    fctrs.count = 0;

    for dvsr in 1..=((num as f64).sqrt() as i32) {
        if num % dvsr != 0 {
            continue;
        }
        if flix == 300 {
            fctrs.xfer_factors(&flist[..flix]);
            flix = 0;
        }
        flist[flix] = dvsr;
        flix += 1;
        if dvsr != num / dvsr {
            flist[flix] = num / dvsr;
            flix += 1;
        }
    }
    if flix > 0 {
        fctrs.xfer_factors(&flist[..flix]);
    }
}

fn main() {
    let nums2factor = [2059, 223092870, 3135, 45];
    let mut ftors = Factors::new();
    let mut sep;

    for &num in &nums2factor {
        factor(num, &mut ftors);
        print!("\nfactors of {} are:\n  ", num);
        sep = ' ';
        for &factor in &ftors.list {
            print!("{} {}", sep, factor);
            sep = ',';
        }
        println!();
    }
}

