use std::cmp;

#[derive(Debug)]
struct Image {
    pixels: Vec<u32>,
    width: usize,
    height: usize,
}

impl Image {
    fn new(width: usize, height: usize) -> Self {
        Image {
            pixels: vec![0; width * height],
            width,
            height,
        }
    }

    fn get_pixel(&self, x: usize, y: usize) -> u32 {
        self.pixels[y * self.width + x]
    }

    fn put_pixel(&mut self, x: usize, y: usize, color: u32) {
        self.pixels[y * self.width + x] = color;
    }
}

fn get_byte(value: u32, n: usize) -> u8 {
    ((value >> (n * 8)) & 0xFF) as u8
}

fn max(a: f32, b: f32) -> f32 {
    if a < b { a } else { b }
}

fn lerp(s: f32, e: f32, t: f32) -> f32 {
    s + (e - s) * t
}

fn blerp(c00: f32, c10: f32, c01: f32, c11: f32, tx: f32, ty: f32) -> f32 {
    lerp(lerp(c00, c10, tx), lerp(c01, c11, tx), ty)
}

fn scale(src: &Image, dst: &mut Image, scalex: f32, scaley: f32) {
    let new_width = (src.width as f32 * scalex) as usize;
    let new_height = (src.height as f32 * scaley) as usize;

    for y in 0..new_height {
        for x in 0..new_width {
            let gx = max((x as f32 / new_width as f32) * src.width as f32 - 0.5, src.width as f32 - 1.0);
            let gy = max((y as f32 / new_height as f32) * src.height as f32 - 0.5, src.height as f32 - 1.0);
            let gxi = gx as usize;
            let gyi = gy as usize;

            let c00 = src.get_pixel(gxi, gyi);
            let c10 = src.get_pixel(cmp::min(gxi + 1, src.width - 1), gyi);
            let c01 = src.get_pixel(gxi, cmp::min(gyi + 1, src.height - 1));
            let c11 = src.get_pixel(cmp::min(gxi + 1, src.width - 1), cmp::min(gyi + 1, src.height - 1));

            let mut result = 0;
            for i in 0..3 {
                let byte = blerp(
                    get_byte(c00, i) as f32,
                    get_byte(c10, i) as f32,
                    get_byte(c01, i) as f32,
                    get_byte(c11, i) as f32,
                    gx - gxi as f32,
                    gy - gyi as f32,
                ) as u8;
                result |= (byte as u32) << (8 * i);
            }

            dst.put_pixel(x, y, result);
        }
    }
}

