use std::str;

fn elq(s: &str, sep: char, esc: char) -> usize {
    let mut q = 1;
    let mut e = false;

    for c in s.chars() {
        if c == esc {
            e = !e;
        } else if c == sep {
            if !e {
                q += 1;
            }
        } else {
            e = false;
        }
    }

    q
}

fn tokenize(s: &mut str, sep: char, esc: char) -> Vec<&str> {
    let q = elq(s, sep, esc);
    let mut list = Vec::with_capacity(q);
    let mut e = false;

    let mut start = 0;
    for (i, c) in s.char_indices() {
        if c == esc {
            e = !e;
        } else if c == sep {
            if !e {
                list.push(&s[start..i]);
                start = i + 1;
            }
        } else {
            e = false;
        }
    }
    list.push(&s[start..]);

    list
}

