use std::collections::HashMap;

fn makehist(s: &[u8], hist: &mut HashMap<u8, usize>) -> usize {
    let mut histlen = 0;
    for &byte in s {
        if !hist.contains_key(&byte) {
            hist.insert(byte, histlen);
            histlen += 1;
        }
        *hist.get_mut(&byte).unwrap() += 1;
    }
    histlen
}

fn entropy(hist: &HashMap<u8, usize>, histlen: usize, len: usize) -> f64 {
    let mut h = 0.0;
    for &count in hist.values() {
        let p = count as f64 / len as f64;
        h -= p * p.log2();
    }
    h
}

fn main() {
    use std::io::{self, Read};

    let mut input = String::new();
    io::stdin().read_line(&mut input).expect("Failed to read line");
    let s = input.trim_end().as_bytes();
    let mut hist = HashMap::new();
    let histlen = makehist(s, &mut hist);

    let h = entropy(&hist, histlen, s.len());
    println!("{:.6}", h);
}

