use std::f64;

fn factorial(n: u32) -> u64 {
    let mut result = 1;
    for i in 1..=n {
        result *= i as u64;
    }
    result
}

fn inverse_factorial(f: u64) -> Option<u32> {
    if f == 1 {
        return Some(0);
    }

    let mut p = 1;
    let mut i = 1;
    while p < f {
        p *= i as u64;
        i += 1;
    }

    if p == f {
        Some(i - 1)
    } else {
        None
    }
}

fn super_factorial(n: u32) -> u64 {
    let mut result = 1;
    for i in 1..=n {
        result *= factorial(i);
    }
    result
}

fn hyper_factorial(n: u32) -> u64 {
    let mut result = 1;
    for i in 1..=n {
        result *= (i as f64).powi(i as i32) as u64;
    }
    result
}

fn alternating_factorial(n: u32) -> i64 {
    let mut result = 0;
    for i in 1..=n {
        if (n - i) % 2 == 0 {
            result += factorial(i) as i64;
        } else {
            result -= factorial(i) as i64;
        }
    }
    result
}

fn exponential_factorial(n: u32) -> u64 {
    let mut result = 0;
    for i in 1..=n {
        result = (i as f64).powf(result as f64) as u64;
    }
    result
}

fn test_factorial(count: usize, func: fn(u32) -> u64, name: &str) {
    print!("First {} {}: ", count, name);
    for i in 0..count {
        print!("{} ", func(i as u32));
    }
    println!();
}

fn test_inverse(f: u64) {
    match inverse_factorial(f) {
        Some(n) => println!("rf({}) = {}", f, n),
        None => println!("rf({}) = No Solution", f),
    }
}

fn main() {
    test_factorial(9, super_factorial, "super factorials");
    println!();

    test_factorial(8, hyper_factorial, "hyper factorials");
    println!();

    test_factorial(10, |n| alternating_factorial(n) as u64, "alternating factorials");
    println!();

    test_factorial(5, exponential_factorial, "exponential factorials");
    println!();

    test_inverse(1);
    test_inverse(2);
    test_inverse(6);
    test_inverse(24);
    test_inverse(120);
    test_inverse(720);
    test_inverse(5040);
    test_inverse(40320);
    test_inverse(362880);
    test_inverse(3628800);
    test_inverse(119);
}

