fn pascal_low(mat: &mut Vec<Vec<i32>>, n: usize) {
    for i in 0..n {
        for j in 0..n {
            mat[i][j] = if i < j {
                0
            } else if i == j || j == 0 {
                1
            } else {
                mat[i - 1][j - 1] + mat[i - 1][j]
            };
        }
    }
}

fn pascal_upp(mat: &mut Vec<Vec<i32>>, n: usize) {
    for i in 0..n {
        for j in 0..n {
            mat[i][j] = if i > j {
                0
            } else if i == j || i == 0 {
                1
            } else {
                mat[i - 1][j - 1] + mat[i][j - 1]
            };
        }
    }
}

fn pascal_sym(mat: &mut Vec<Vec<i32>>, n: usize) {
    for i in 0..n {
        for j in 0..n {
            mat[i][j] = if i == 0 || j == 0 {
                1
            } else {
                mat[i - 1][j] + mat[i][j - 1]
            };
        }
    }
}

fn main() {
    let n = 5;
    let mut mat = vec![vec![0; n]; n];

    println!("=== Pascal upper matrix ===");
    pascal_upp(&mut mat, n);
    for row in &mat {
        for &val in row {
            print!("{:4}", val);
        }
        println!();
    }

    println!("=== Pascal lower matrix ===");
    pascal_low(&mut mat, n);
    for row in &mat {
        for &val in row {
            print!("{:4}", val);
        }
        println!();
    }

    println!("=== Pascal symmetric matrix ===");
    pascal_sym(&mut mat, n);
    for row in &mat {
        for &val in row {
            print!("{:4}", val);
        }
        println!();
    }
}

