use std::env;
use std::process;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        process::exit(1);
    }

    let y: i32 = match args[1].parse() {
        Ok(year) if year > 1752 => year,
        _ => process::exit(1),
    };

    let mut days = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    days[1] -= if y % 4 == 0 && (y % 100 != 0 || y % 400 == 0) { 0 } else { 1 };
    let mut w = y * 365 + 97 * (y - 1) / 400 + 4;

    for (m, &day_count) in days.iter().enumerate() {
        w = (w + day_count) % 7;
        println!("{}-{:02}-{}", y, m + 1, day_count - w);
    }
}

