fn quicksort(arr: &mut [i32]) {
    if arr.len() < 2 {
        return;
    }

    let pivot_index = arr.len() / 2;
    let pivot = arr[pivot_index];

    let mut i = 0;
    let mut j = arr.len() - 1;

    loop {
        while arr[i] < pivot {
            i += 1;
        }
        while arr[j] > pivot {
            j -= 1;
        }

        if i >= j {
            break;
        }

        arr.swap(i, j);
    }

    quicksort(&mut arr[..i]);
    quicksort(&mut arr[i..]);
}

fn main() {
