fn list_cmp(a: &[i32], b: &[i32]) -> i32 {
    let l = a.len().min(b.len());
    for (&ai, &bi) in a.iter().zip(b.iter()).take(l) {
        if ai == bi {
            continue;
        }
        return if ai > bi { 1 } else { -1 };
    }
    if a.len() == b.len() {
        0
    } else if a.len() > b.len() {
        1
    } else {
        -1
    }
}

