fn time_it<F>(action: F, arg: i32) -> f64
where
    F: Fn(i32) -> i32,
{
    let start = Instant::now();
    action(arg);
    let duration = start.elapsed();
    duration.as_secs() as f64 + duration.subsec_nanos() as f64 * 1e-9
}

