use std::cmp::Ordering;

fn mycmp(s1: &&str, s2: &&str) -> Ordering {
    let ll = s1.len();
    let lr = s2.len();

    match ll.cmp(&lr) {
        Ordering::Equal => s1.to_ascii_lowercase().cmp(&s2.to_ascii_lowercase()),
        other => other.reverse(),
    }
}

fn main() {
    let mut strings = vec![
        "Here", "are", "some", "sample", "strings", "to", "be", "sorted",
    ];

    strings.sort_by(mycmp);

    for s in &strings {
        println!("{}", s);
    }
}

