fn is_prime(p: u32) -> bool {
    if p == 2 {
        return true;
    }
    if p % 2 == 0 {
        return false;
    }
    (3..=((p as f64).sqrt() as u32))
        .step_by(2)
        .all(|i| p % i != 0)
}

fn main() {
    let mut s = 0;
    let mut i = 1;
    for p in (2..=999).filter(|&x| is_prime(x)) {
        if i % 2 != 0 {
            s += p;
            if is_prime(s) {
                println!("{:<8}{:<8}{}", i, p, s);
            }
        }
        i += 1;
    }
}

