    if args.len() == 1 {
        println!("Usage: {} <data points separated by spaces or commas>", args[0]);
    } else {
        let mut arr = Vec::with_capacity(args.len() - 1);
        let mut min = f64::INFINITY;
        let mut max = f64::NEG_INFINITY;

        for arg in &args[1..] {
            let trimmed_arg = if arg.ends_with(',') {
                &arg[..arg.len() - 1]
            } else {
                arg
            };
            match f64::from_str(trimmed_arg) {
                Ok(num) => {
                    arr.push(num);
                    if num < min { min = num; }
                    if num > max { max = num; }
                },
                Err(_) => {
                    eprintln!("Invalid number: {}", trimmed_arg);
                    return;
                }
            }
        }

        println!("\nMax: {}, Min: {}, Range: {}", max, min, max - min);

        for &num in &arr {
            let bar_char = 9601 + ((num - min) / (max - min) * 7.0).ceil() as u32;
            print!("{}", char::from_u32(bar_char).unwrap_or(' '));
        }
        println!();
    }
}

