#include <stdio.h>

void padovanN(int n, size_t t, int *p) {
    int i, j;
    if (n < 2 || t < 3) {
        for (i = 0; i < t; ++i) p[i] = 1;
        return;
    }
    padovanN(n-1, t, p);
    for (i = n + 1; i < t; ++i) {
        p[i] = 0;
        for (j = i - 2; j >= i - n - 1; --j) p[i] += p[j];
    }
}

int main() {
    int n, i;
    const size_t t = 15;
    int p[t];
    printf("First %ld terms of the Padovan n-step number sequences:\n", t);
    for (n = 2; n <= 8; ++n) {
        for (i = 0; i < t; ++i) p[i] = 0;
        padovanN(n, t, p);
        printf("%d: ", n);
        for (i = 0; i < t; ++i) printf("%3d ", p[i]);
        printf("\n");
    }
    return 0;
}

522d7ba1aa67b7e5c9678479516f36b2.rust_code:
fn padovan_n(n: usize, t: usize, p: &mut [i32]) {
    if n < 2 || t < 3 {
        for val in p.iter_mut().take(t) {
            *val = 1;
        }
        return;
    }
    padovan_n(n - 1, t, p);
    for i in n + 1..t {
        p[i] = 0;
        for j in (i.saturating_sub(n)..i).rev() {
            p[i] += p[j];
        }
    }
}

fn main() {
    const T: usize = 15;
    let mut p = vec![0; T];
    println!("First {} terms of the Padovan n-step number sequences:", T);
    for n in 2..=8 {
        p.fill(0);
        padovan_n(n, T, &mut p);
        print!("{}: ", n);
        for &val in &p {
            print!("{:3} ", val);
        }
        println!();
    }
}

