use std::env;
use std::process;

fn doubly_even_magic_square(n: usize) -> Option<Vec<Vec<usize>>> {
    if n < 4 || n % 4 != 0 {
        return None;
    }

    let bits = 38505;
    let size = n * n;
    let mult = n / 4;

    let mut result = vec![vec![0; n]; n];

    for (r, row) in result.iter_mut().enumerate() {
        for (c, cell) in row.iter_mut().enumerate() {
            let bit_pos = c / mult + (r / mult) * 4;
            *cell = if (bits & (1 << bit_pos)) != 0 { c + r * n + 1 } else { size - (c + r * n) };
        }
    }

    Some(result)
}

fn num_digits(mut n: usize) -> usize {
    let mut count = 1;
    while n >= 10 {
        n /= 10;
        count += 1;
    }
    count
}

fn print_magic_square(square: &[Vec<usize>], rows: usize) {
    let base_width = num_digits(rows * rows) + 3;
    println!("Doubly Magic Square of Order: {} and Magic Constant: {}\n", rows, (rows * rows + 1) * rows / 2);

    for row in square {
        for &value in row {
            print!("{:width$}", value, width = base_width - num_digits(value));
        }
        println!();
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() != 2 || !args[1].chars().next().unwrap_or('a').is_digit(10) {
        eprintln!("Usage: {} <integer specifying rows in magic square>", args[0]);
        process::exit(1);
    }

    let n: usize = args[1].parse().expect("Please provide a valid integer");

    if let Some(square) = doubly_even_magic_square(n) {
        print_magic_square(&square, n);
    } else {
        eprintln!("The order of the magic square must be a multiple of 4 and at least 4.");
        process::exit(1);
    }
}

