fn is_prime(p: u32) -> bool {
    if p == 2 {
        return true;
    }
    if p % 2 == 0 {
        return false;
    }
    (3..=((p as f64).sqrt() as u32))
        .step_by(2)
        .all(|i| p % i != 0)
}

fn main() {
    let mut s: u64 = 2;
    for p in (3..2_000_000).step_by(2) {
        if is_prime(p) {
            s += p as u64;
        }
    }
    println!("{}", s);
}

