fn main() {
    let buff = "This is 1 string\n";
    println!("{:4}, {:4}, {:4}, {}", count_vowels(buff), count_consonants(buff), length(buff), buff);

    let buff2 = "This is a second string\n";
    println!("{:4}, {:4}, {:4}, {}", count_vowels(buff2), count_consonants(buff2), length(buff2), buff2);

    println!("a: {}", is_vowel('a'));
    println!("b: {}", is_vowel('b'));
    println!("Z: {}", is_consonant('Z'));
    println!("1: {}", is_letter('1'));
}

fn vowels() -> &'static [char] {
    &['a', 'e', 'i', 'o', 'u', '\n']
}

fn length(s: &str) -> usize {
    s.chars().position(|c| c == '\n').unwrap_or(s.len())
}

fn is_vowel(c: char) -> bool {
    vowels().contains(&c)
}

fn is_letter(c: char) -> bool {
    (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

fn is_consonant(c: char) -> bool {
    is_letter(c) && !is_vowel(c)
}

fn count_vowels(s: &str) -> usize {
    s.chars().take_while(|&c| c != '\n').filter(|&c| is_vowel(c)).count()
}

fn count_consonants(s: &str) -> usize {
    s.chars().take_while(|&c| c != '\n').filter(|&c| is_consonant(c)).count()
}

