use std::io::{self, Write};

fn main() -> io::Result<()> {
    let mut input = String::new();
    print!("Enter two integers.  Space delimited, please:  ");
    io::stdout().flush()?;
    io::stdin().read_line(&mut input)?;

    let parts: Vec<&str> = input.trim().split_whitespace().collect();
    if parts.len() != 2 {
        eprintln!("Please enter exactly two integers.");
        return Ok(());
    }

    let user1: usize = parts[0].parse().map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "Invalid integer"))?;
    let user2: usize = parts[1].parse().map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "Invalid integer"))?;

    if user1 == 0 || user2 == 0 {
        eprintln!("Integers must be non-zero.");
        return Ok(());
    }

    let mut array = vec![vec![0; user2]; user1];
    array[user1 / 2][user2 / 2] = user1 + user2;
    println!("array[{}][{}] is {}", user1 / 2, user2 / 2, array[user1 / 2][user2 / 2]);

    Ok(())
}

