#include <stdio.h>
#include <stdlib.h>

void counting_sort_mm(int *array, int n, int min, int max)
{
  int i, j, z;

  int range = max - min + 1;
  int *count = malloc(range * sizeof(*array));

  for(i = 0; i < range; i++) count[i] = 0;
  for(i = 0; i < n; i++) count[ array[i] - min ]++;

  for(i = min, z = 0; i <= max; i++) {
    for(j = 0; j < count[i - min]; j++) {
      array[z++] = i;
    }
  } 

  free(count);
}

void min_max(int *array, int n, int *min, int *max)
{
  int i;

  *min = *max = array[0];
  for(i=1; i < n; i++) {
    if ( array[i] < *min ) {
      *min = array[i];
    } else if ( array[i] > *max ) {
      *max = array[i];
    }
  }
}

d7d824a15829b7491bfe5d7032244fc3.rust_code:
fn counting_sort_mm(array: &mut [i32]) {
    if array.is_empty() {
        return;
    }

    let (min, max) = min_max(array);
    let range = (max - min + 1) as usize;
    let mut count = vec![0; range];

    for &value in array.iter() {
        count[(value - min) as usize] += 1;
    }

    let mut z = 0;
    for (i, &cnt) in count.iter().enumerate() {
        for _ in 0..cnt {
            array[z] = (i as i32) + min;
            z += 1;
        }
    }
}

fn min_max(array: &[i32]) -> (i32, i32) {
    let mut min = array[0];
    let mut max = array[0];
    for &value in array.iter().skip(1) {
        if value < min {
            min = value;
        } else if value > max {
            max = value;
        }
    }
    (min, max)
}

