fn f(n: i32, x: i32, y: i32) -> i32 {
    match (n, y) {
        (0, _) => x + y,
        (_, 0) => x,
        _ => {
            let recursive_call = f(n, x, y - 1);
            f(n - 1, recursive_call, recursive_call + y)
        }
    }
}

fn main() {
    println!("F1(3,3) = {}", f(1, 3, 3));
}

