fn identity(x: i32) -> i32 {
    x
}

fn sum(mut s: i32) -> i32 {
    for i in 0..1_000_000 {
        s += i;
    }
    s
}

fn time_it<F>(action: F, arg: i32) -> f64
where
    F: Fn(i32) -> i32,
{
    let start = Instant::now();
    action(arg);
    let duration = start.elapsed();
    duration.as_secs() as f64 + duration.subsec_nanos() as f64 * 1e-9
}

fn main() {
    println!("identity (4) takes {} s", time_it(identity, 4));
    println!("sum      (4) takes {} s", time_it(sum, 4));
}

