use std::f64;

fn cholesky(a: &[f64], n: usize) -> Vec<f64> {
    let mut l = vec![0.0; n * n];

    for i in 0..n {
        for j in 0..=i {
            let mut s = 0.0;
            for k in 0..j {
                s += l[i * n + k] * l[j * n + k];
            }
            l[i * n + j] = if i == j {
                (a[i * n + i] - s).sqrt()
            } else {
                (1.0 / l[j * n + j]) * (a[i * n + j] - s)
            };
        }
    }

    l
}

fn show_matrix(a: &[f64], n: usize) {
    for i in 0..n {
        for j in 0..n {
            print!("{:2.5} ", a[i * n + j]);
        }
        println!();
    }
}

fn main() {
    let n = 3;
    let m1 = [25.0, 15.0, -5.0, 15.0, 18.0, 0.0, -5.0, 0.0, 11.0];
    let c1 = cholesky(&m1, n);
    show_matrix(&c1, n);
    println!();

    let n = 4;
    let m2 = [
