#include <stdio.h>

#define MAX 15

int count_divisors(int n) {
    int i, count = 0;
    for (i = 1; i * i <= n; ++i) {
        if (!(n % i)) {
            if (i == n / i)
                count++;
            else
                count += 2;
        }
    }
    return count;
}

int main() {
    int i, next = 1;
    printf("The first %d terms of the sequence are:\n", MAX);
    for (i = 1; next <= MAX; ++i) {
        if (next == count_divisors(i)) {           
            printf("%d ", i);
            next++;
        }
    }
    printf("\n");
    return 0;
}

ccb554f01cb19a33e5248dff77244b6c.rust_code:
fn count_divisors(n: u32) -> u32 {
    let mut count = 0;
    let limit = (n as f64).sqrt() as u32 + 1;
    for i in 1..limit {
        if n % i == 0 {
            if i == n / i {
                count += 1;
            } else {
                count += 2;
            }
        }
    }
    count
}

fn main() {
    const MAX: u32 = 15;
    let mut next = 1;
    println!("The first {} terms of the sequence are:", MAX);
    for i in 1.. {
        if next > MAX {
            break;
        }
        if next == count_divisors(i) {
            print!("{} ", i);
            next += 1;
        }
    }
    println!();
}

