use std::cmp;

fn lcp(num: usize, strings: &[&str]) -> String {
    if num == 0 {
        return "".to_string();
    }

    let mut min_len = strings[0].len();
    for &s in &strings[1..] {
        min_len = cmp::min(min_len, s.len());
    }

    if min_len == 0 {
        return "".to_string();
    }

    for i in 0..min_len {
        let c = strings[0].chars().nth(i).unwrap();
        for &s in &strings[1..] {
            if s.chars().nth(i).unwrap() != c {
                return strings[0][..i].to_string();
            }
        }
    }

    strings[0][..min_len].to_string()
}

