    for i in 0..p {
        for j in 0..r {
            alloc[j] += curr[i][j];
        }
    }

    println!("\nAllocated resources: {:?}", alloc);
    let mut avl = max_res.iter().zip(alloc.iter()).map(|(&a, &b)| a - b).collect::<Vec<_>>();

    println!("\nAvailable resources: {:?}", avl);

    while count != 0 {
        safe = false;
        for i in 0..p {
            if running[i] {
                let mut exec = true;
                for j in 0..r {
                    if max_claim[i][j] - curr[i][j] > avl[j] {
                        exec = false;
                        break;
                    }
                }

                if exec {
                    println!("\nProcess{} is executing.", i + 1);
                    running[i] = false;
                    count -= 1;
                    safe = true;
                    for j in 0..r {
                        avl[j] += curr[i][j];
                    }
                    break;
