use std::env;

fn totient(mut n: u64) -> u64 {
    let mut tot = n;
    let mut i = 2;

    while i * i <= n {
        if n % i == 0 {
            while n % i == 0 {
                n /= i;
            }
            tot -= tot / i;
        }
        if i == 2 {
            i = 1;
        }
        i += 2;
    }

    if n > 1 {
        tot -= tot / n;
    }

    tot
}

fn perfect_totients(n: usize) -> Vec<u64> {
    let mut pt_list = Vec::with_capacity(n);
    let mut count = 0;
    let mut m = 1;

    while count < n {
        let mut tot = m;
        let mut sum = 0;

        while tot != 1 {
            tot = totient(tot);
            sum += tot;
        }

        if sum == m {
            pt_list.push(m);
            count += 1;
        }

        m += 1;
    }

    pt_list
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() != 2 {
        println!("Usage: {} <number of perfect Totient numbers required>", args[0]);
    } else {
        match args[1].parse::<usize>() {
            Ok(n) => {
                let pt_list = perfect_totients(n);

                print!("The first {} perfect Totient numbers are: [", n);
                for (index, &num) in pt_list.iter().enumerate() {
                    if index > 0 {
                        print!(", ");
                    }
                    print!("{}", num);
                }
                println!("]");
            }
            Err(_) => println!("Please provide a valid number"),
        }
    }
}

