use std::cmp;

fn lcp(num: usize, strings: &[&str]) -> String {
    if num == 0 {
        return "".to_string();
    }

    let mut min_len = strings[0].len();
    for &s in &strings[1..] {
        min_len = cmp::min(min_len, s.len());
    }

    if min_len == 0 {
        return "".to_string();
    }

    for i in 0..min_len {
        let c = strings[0].chars().nth(i).unwrap();
        for &s in &strings[1..] {
            if s.chars().nth(i).unwrap() != c {
                return strings[0][..i].to_string();
            }
        }
    }

    strings[0][..min_len].to_string()
}

fn main() {
    println!("Longest common prefix: {}", lcp(3, &["interspecies", "interstellar", "interstate"]));
    println!("Longest common prefix: {}", lcp(2, &["throne", "throne"]));
    println!("Longest common prefix: {}", lcp(2, &["throne", "dungeon"]));
    println!("Longest common prefix: {}", lcp(3, &["throne", "", "throne"]));
    println!("Longest common prefix: {}", lcp(1, &["cheese"]));
    println!("Longest common prefix: {}", lcp(1, &[""]));
    println!("Longest common prefix: {}", lcp(0, &[]));
    println!("Longest common prefix: {}", lcp(2, &["prefix", "suffix"]));
    println!("Longest common prefix: {}", lcp(2, &["foo", "foobar"]));
}

