            if (b >= lo && b <= hi) && (!unique || (b != a && b != c && b != d && b != g && b != e && b != f)) {
                *solutions += 1;
                if show {
                    writeln!(output, "{} {} {} {} {} {} {}", a, b, c, d, e, f, g).unwrap();
                }
            }
        }
    }
}

fn ge(a: i32, c: i32, d: i32, lo: i32, hi: i32, unique: bool, show: bool, solutions: &mut i32, output: &mut String) {
    for e in lo..=hi {
        if !unique || (e != a && e != c && e != d) {
            let g = d + e;
            if (g >= lo && g <= hi) && (!unique || (g != a && g != c && g != d && g != e)) {
                bf(a, c, d, e, g, lo, hi, unique, show, solutions, output);
            }
        }
    }
}

fn acd(lo: i32, hi: i32, unique: bool, show: bool, solutions: &mut i32, output: &mut String) {
    for c in lo..=hi {
        for d in lo..=hi {
            if !unique || c != d {
                let a = c + d;
                if (a >= lo && a <= hi) && (!unique || (c != 0 && d != 0)) {
                    ge(a, c, d, lo, hi, unique, show, solutions, output);
                }
            }
        }
    }
}

fn foursquares(plo: i32, phi: i32, punique: bool, pshow: bool) -> String {
    let mut solutions = 0;
    let mut output = String::new();

    acd(plo, phi, punique, pshow, &mut solutions, &mut output);

    if punique {
        writeln!(output, "\n{} unique solutions in {} to {}", solutions, plo, phi).unwrap();
    } else {
        writeln!(output, "\n{} non-unique solutions in {} to {}", solutions, plo, phi).unwrap();
    }

    output
}

fn main() {
    println!("{}", foursquares(1, 7, true, true));
    println!("{}", foursquares(3, 9, true, true));
    println!("{}", foursquares(0, 9, false, false));
}

