use std::io::{self, Read, Write};

fn owp(odd: bool) -> Option<char> {
    let mut stdin = io::stdin().lock();
    let mut buffer = [0; 1];
    if stdin.read_exact(&mut buffer).is_err() {
        return None;
    }
    let ch = buffer[0] as char;

    if !odd {
        print!("{}", ch);
        if ch == '.' || ch == '\x04' { // '\x04' represents EOF on some systems
            return None;
        }
        if ch.is_ascii_punctuation() {
            return Some(ch);
        }
        owp(odd);
        Some(ch)
    } else {
        if ch.is_ascii_punctuation() {
            return Some(ch);
        }
        let ret = owp(odd);
        print!("{}", ch);
        ret
    }
}

fn main() {
    let mut ch = Some('1');
    while let Some(c) = ch {
        ch = owp(c != '1');
        if let Some(c) = ch {
            print!("{}", c);
            if c == '.' {
                break;
            }
        }
    }
}

