fn swap(s: &mut [char], i: usize, j: usize) {
    s.swap(i, j);
}

fn reverse(s: &mut [char], i: usize, j: usize) {
    s[i..=j].reverse();
}

fn next_permutation(s: &mut [char]) -> bool {
    let len = s.len();
    if len < 2 {
        return false;
    }
    for i in (0..len - 1).rev() {
        if s[i] < s[i + 1] {
            let mut k = len - 1;
            while s[i] >= s[k] {
                k -= 1;
            }
            swap(s, i, k);
            reverse(s, i + 1, len - 1);
            return true;
        }
    }
    false
}

fn next_highest_int(n: u32) -> Option<u32> {
    let mut chars: Vec<char> = n.to_string().chars().collect();
    if !next_permutation(&mut chars) {
        None
    } else {
        chars.iter().collect::<String>().parse().ok()
    }
}

fn main() {
    let numbers = [0, 9, 12, 21, 12453, 738440, 45072010, 95322020];
    for &number in &numbers {
        println!("{} -> {:?}", number, next_highest_int(number));
    }

    let big = "9589776899767587796600";
    let mut next: Vec<char> = big.chars().collect();
    if next_permutation(&mut next) {
        println!("{} -> {}", big, next.iter().collect::<String>());
    } else {
        println!("{} -> No next permutation", big);
    }
}

