use std::collections::HashMap;

fn add_code(code: &mut HashMap<char, i32>, s: &str, c: i32) {
    for ch in s.chars() {
        code.insert(ch, c);
        code.insert((ch as u8 ^ 0x20) as char, c);
    }
}

fn init() -> HashMap<char, i32> {
    let mut code = HashMap::new();
    let cls = ["AEIOU", "", "BFPV", "CGJKQSXZ", "DT", "L", "MN", "R"];
    for (i, &class) in cls.iter().enumerate() {
        add_code(&mut code, class, i as i32 - 1);
    }
    code
}

fn soundex(s: &str, code: &HashMap<char, i32>) -> String {
    let mut out = String::with_capacity(4);
    if let Some(first_char) = s.chars().next() {
        out.push(first_char);
        let mut prev = *code.get(&first_char).unwrap_or(&0);
        for ch in s.chars().skip(1) {
            if let Some(&c) = code.get(&ch) {
                if c != prev {
                    if c > 0 {
                        out.push((b'0' + c as u8) as char);
                        prev = c;
                    } else {
                        prev = 0;
                    }
                }
            }
        }
    }
    while out.len() < 4 {
        out.push('0');
    }
    out.truncate(4);
    out
}

