void Combsort11(double a[], int nElements)
{
  int i, j, gap, swapped = 1;
  double temp;

  gap = nElements;
  while (gap > 1 || swapped == 1)
  {
    gap = gap * 10 / 13;
    if (gap == 9 || gap == 10) gap = 11;
    if (gap < 1) gap = 1;
    swapped = 0;
    for (i = 0, j = gap; j < nElements; i++, j++)
    {
      if (a[i] > a[j])
      {
        temp = a[i];
        a[i] = a[j];
        a[j] = temp;
        swapped = 1;
      }
    }
  }
}

1c21ea96b8e76dd67080af27d60be401.rust_code:
fn combsort11(a: &mut [f64]) {
    let mut gap = a.len();
    let mut swapped = true;

    while gap > 1 || swapped {
        gap = (gap as f64 * 10.0 / 13.0).max(1.0) as usize;
        if gap == 9 || gap == 10 {
            gap = 11;
        }
        swapped = false;

        for (i, j) in (0..a.len()).zip(gap..a.len()) {
            if a[i] > a[j] {
                a.swap(i, j);
                swapped = true;
            }
        }
    }
}

