use std::fs::File;
use std::io::{self, BufRead, BufReader};

fn process(line_num: usize, buffer: &str) {
    let mut days = vec![String::new(); 7];
    let mut day_index = 0;
    let mut char_index = 0;

    for c in buffer.chars() {
        if c == ' ' {
            days[day_index].truncate(char_index);
            day_index += 1;
            char_index = 0;
        } else if c == '\n' || c == '\r' {
            days[day_index].truncate(char_index);
            day_index += 1;
            break;
        } else {
            if char_index >= 63 {
                eprintln!("Day name too long in line {}", line_num);
                return;
            }
            days[day_index].push(c);
            char_index += 1;
        }

        if day_index >= 7 {
            eprintln!("There aren't 7 days in line {}", line_num);
            return;
        }
    }

    if day_index < 7 {
        eprintln!("There aren't 7 days in line {}", line_num);
        return;
    }

    for len in 1..64 {
        let mut unique = true;
        for d1 in 0..7 {
            for d2 in (d1 + 1)..7 {
                if days[d1].chars().take(len).eq(days[d2].chars().take(len)) {
                    unique = false;
                    break;
                }
            }
            if !unique {
                break;
            }
        }

        if unique {
            println!("{:2} {:?}", len, days);
            return;
        }
    }

    eprintln!("Failed to find uniqueness within the bounds.");
}

fn main() -> io::Result<()> {
    let file = File::open("days_of_week.txt")?;
    let reader = BufReader::new(file);

    for (line_num, line) in reader.lines().enumerate() {
        let line = line?;
        process(line_num + 1, &line);
    }

    Ok(())
}

