#include <string.h>
#include <stdio.h>

int luhn(const char* cc)
{
	const int m[] = {0,2,4,6,8,1,3,5,7,9}; 
	int i, odd = 1, sum = 0;

	for (i = strlen(cc); i--; odd = !odd) {
		int digit = cc[i] - '0';
		sum += odd ? digit : m[digit];
	}

	return sum % 10 == 0;
}

int main()
{
	const char* cc[] = {
		"49927398716",
		"49927398717",
		"1234567812345678",
		"1234567812345670",
		0
	};
	int i;

	for (i = 0; cc[i]; i++)
		printf("%16s\t%s\n", cc[i], luhn(cc[i]) ? "ok" : "not ok");

	return 0;
}

3fe42654f57acc27c5eb95e9cdbd5a77.rust_code:
fn luhn(cc: &str) -> bool {
    let m = [0, 2, 4, 6, 8, 1, 3, 5, 7, 9];
    let mut odd = true;
    let mut sum = 0;

    for digit_char in cc.chars().rev() {
        if let Some(digit) = digit_char.to_digit(10) {
            sum += if odd { digit } else { m[digit as usize] };
            odd = !odd;
        }
    }

    sum % 10 == 0
}

fn main() {
    let cc = [
        "49927398716",
        "49927398717",
        "1234567812345678",
        "1234567812345670",
    ];

    for card in cc.iter() {
        println!("{:16}\t{}", card, if luhn(card) { "ok" } else { "not ok" });
    }
}

