use std::collections::HashSet;

fn prime_sieve(limit: usize) -> Vec<bool> {
    let mut c = vec![false; limit + 1];
    c[0] = true;
    c[1] = true;
    for i in (4..=limit).step_by(2) {
        c[i] = true;
    }
    let mut p = 3;
    while p * p <= limit {
        let p2 = p * p;
        for i in (p2..=limit).step_by(2 * p) {
            c[i] = true;
        }
        p += 2;
        while c[p] {
            p += 2;
        }
    }
    c
}

fn main() {
    const LIMIT: usize = 1_000_000;
    let c = prime_sieve(LIMIT);
    let n = 63 * LIMIT + 1;
    let mut sum_divs = vec![0; n];
    for i in 1..n {
        for j in (i..n).step_by(i) {
            sum_divs[j] += i;
        }
    }
    let mut s = vec![false; n];
    for i in 1..n {
        let sum = sum_divs[i] - i;
        if sum < n {
            s[sum] = true;
        }
    }
    let mut untouchable = vec![0; 151_000];
    untouchable[0] = 2;
    untouchable[1] = 5;
    let mut uc = 2;
    for n in (6..=LIMIT).step_by(2) {
        if !s[n] && !c[n - 1] && !c[n - 3] {
            untouchable[uc] = n;
            uc += 1;
        }
    }
    println!("List of untouchable numbers <= 2,000:");
    let mut count = 0;
    for &num in &untouchable[..uc] {
        if num > 2000 {
            break;
        }
        print!("{:>6} ", num);
        count += 1;
        if count % 10 == 0 {
            println!();
        }
    }
    println!("\n\n{:>7} untouchable numbers were found  <=     2,000", count);
    let mut p = 10;
    for (i, &num) in untouchable.iter().enumerate().take(uc) {
        if num > p {
            println!("{:>7} untouchable numbers were found  <= {:>9}", i, p);
            p *= 10;
            if p == LIMIT {
                break;
            }
        }
    }
    println!("{:>7} untouchable numbers were found  <= {}", uc, LIMIT);
}

