    let mut r = 1.0;
    for _ in 0..e {
        r *= x;
    }
    r
}

fn root(n: i32, x: f64) -> f64 {
    if x == 0.0 {
        return 0.0;
    }
    if n < 1 || (x < 0.0 && n % 2 == 0) {
        return f64::NAN;
    }

    let mut r = 1.0;
    loop {
        let d = (x / pow_(r, n - 1) - r) / n as f64;
        r += d;
        if d < f64::EPSILON * 10.0 && d > -f64::EPSILON * 10.0 {
            break;
        }
    }
    r
}

