use std::fmt;

fn divisor_count(n: u32) -> u32 {
    let mut count = 0;
    let step = if n % 2 == 0 { 1 } else { 2 };
    let mut i = 1;
    while i * i <= n {
        if n % i == 0 {
            count += 1;
            let j = n / i;
            if j != i {
                count += 1;
            }
        }
        i += step;
    }
    count
}

fn main() {
