#include <stdbool.h>
#include <stdio.h>

#define MAX_WORD 80
#define LETTERS 26

bool is_letter(char c) { return c >= 'a' && c <= 'z'; }

int index(char c) { return c - 'a'; }

void word_wheel(const char* letters, char central, int min_length, FILE* dict) {
    int max_count[LETTERS] = { 0 };
    for (const char* p = letters; *p; ++p) {
        char c = *p;
        if (is_letter(c))
            ++max_count[index(c)];
    }
    char word[MAX_WORD + 1] = { 0 };
    while (fgets(word, MAX_WORD, dict)) {
        int count[LETTERS] = { 0 };
        for (const char* p = word; *p; ++p) {
            char c = *p;
            if (c == '\n') {
                if (p >= word + min_length && count[index(central)] > 0)
                    printf("%s", word);
            } else if (is_letter(c)) {
                int i = index(c);
                if (++count[i] > max_count[i]) {
                    break;
                }
            } else {
                break;
            }
        }
    }
}

int main(int argc, char** argv) {
    const char* dict = argc == 2 ? argv[1] : "unixdict.txt";
    FILE* in = fopen(dict, "r");
    if (in == NULL) {
        perror(dict);
        return 1;
    }
    word_wheel("ndeokgelw", 'k', 3, in);
    fclose(in);
    return 0;
}

cb37920fdb51a1e3f55f9cdfa35634cc.rust_code:
use std::collections::HashMap;
use std::fs::File;
use std::io::{self, BufRead, BufReader};

fn is_letter(c: char) -> bool {
    c.is_ascii_lowercase()
}

fn index(c: char) -> usize {
    (c as u8 - b'a') as usize
}

fn word_wheel(letters: &str, central: char, min_length: usize, dict: &mut BufReader<File>) -> io::Result<()> {
    let mut max_count = [0; 26];
    for c in letters.chars().filter(|&c| is_letter(c)) {
        max_count[index(c)] += 1;
    }

    let mut word = String::with_capacity(81);
    for line in dict.lines() {
        let line = line?;
        let mut count = [0; 26];
        let mut valid = true;

        for (i, c) in line.chars().enumerate() {
            if c == '\n' {
                if i >= min_length && count[index(central)] > 0 {
                    println!("{}", line);
                }
                break;
            } else if is_letter(c) {
                let idx = index(c);
                count[idx] += 1;
                if count[idx] > max_count[idx] {
                    valid = false;
                    break;
                }
            } else {
                valid = false;
                break;
            }
        }

        if !valid {
            continue;
        }
    }

    Ok(())
}

fn main() -> io::Result<()> {
    let dict_path = std::env::args().nth(1).unwrap_or_else(|| "unixdict.txt".to_string());
    let file = File::open(&dict_path)?;
    let mut reader = BufReader::new(file);

    word_wheel("ndeokgelw", 'k', 3, &mut reader)?;

