use std::env;
use std::process;

fn get_water(arr: &[i32], start: usize, end: usize, cutoff: usize) -> i32 {
    arr[start..=end]
        .iter()
        .map(|&height| (arr[cutoff] - height).max(0))
        .sum()
}

fn net_water(arr: &[i32]) -> i32 {
    if arr.len() < 3 {
        return 0;
    }

    let mut sum = 0;
    let mut i = 0;

    while i < arr.len() - 1 {
        if i != arr.len() - 2 && arr[i] > arr[i + 1] {
            let ref1 = i;
            let mut ref2 = None;
            let mut marker = None;
            let mut marker_set = false;

            for j in ref1 + 1..arr.len() {
                if arr[j] >= arr[ref1] {
                    ref2 = Some(j);
                    break;
                } else if j != arr.len() - 1 && arr[j] < arr[j + 1] && (!marker_set || arr[j + 1] >= arr[marker.unwrap()]) {
                    marker = Some(j + 1);
                    marker_set = true;
                }
            }

            match ref2 {
                Some(ref2) => {
                    sum += get_water(arr, ref1 + 1, ref2 - 1, ref1);
                    i = ref2;
                }
                None => {
                    if marker_set {
                        sum += get_water(arr, ref1 + 1, marker.unwrap() - 1, marker.unwrap());
                        i = marker.unwrap();
                        marker_set = false;
                    }
                }
            }
        }
        i += 1;
    }

    sum
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() == 1 {
        eprintln!("Usage: {} <followed by space separated series of integers>", args[0]);
        process::exit(1);
    }

    let arr: Vec<i32> = args.iter()
        .skip(1)
        .map(|s| s.parse().expect("Please provide valid integers"))
        .collect();

    println!("Water collected: {}", net_water(&arr));
}

