use std::cmp::Ordering;
use std::env;
use std::f64;

#[derive(Debug)]
struct Triangle {
    a: i32,
    b: i32,
    c: i32,
    perimeter: i32,
    area: f64,
}

impl Triangle {
    fn new(a: i32, b: i32, c: i32) -> Self {
        let perimeter = a + b + c;
        let s = perimeter as f64 / 2.0;
        let area = (s * (s - a as f64) * (s - b as f64) * (s - c as f64)).sqrt();
        Triangle { a, b, c, perimeter, area }
    }

    fn is_integer_area(&self) -> bool {
        self.area.fract() == 0.0
    }
}

impl Ord for Triangle {
    fn cmp(&self, other: &Self) -> Ordering {
        match self.area.partial_cmp(&other.area).unwrap_or(Ordering::Equal) {
            Ordering::Equal => match self.perimeter.cmp(&other.perimeter) {
                Ordering::Equal => self.a.cmp(&other.a),
                other => other,
            },
            other => other,
        }
    }
}

impl PartialOrd for Triangle {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl PartialEq for Triangle {
    fn eq(&self, other: &Self) -> bool {
        self.area == other.area && self.perimeter == other.perimeter && self.a == other.a
    }
}

impl Eq for Triangle {}

type List = Vec<Triangle>;

fn add_and_order_list(list: &mut List, triangle: Triangle) {
    match list.binary_search(&triangle) {
        Ok(_) => {}
        Err(pos) => list.insert(pos, triangle),
    }
}

fn gcd(mut a: i32, mut b: i32) -> i32 {
    while b != 0 {
        let t = b;
        b = a % b;
        a = t;
    }
    a
}

fn generate_triangle_list(max_side: i32) -> List {
    let mut herons = Vec::new();

    for a in 1..=max_side {
        for b in 1..=a {
            for c in 1..=b {
                if c + b > a && gcd(gcd(a, b), c) == 1 {
                    let t = Triangle::new(a, b, c);
                    if t.is_integer_area() {
                        add_and_order_list(&mut herons, t);
                    }
                }
            }
        }
    }

    herons
}

fn print_list(list: &[Triangle], limit: usize, area: Option<i32>) {
    println!("\nDimensions\tPerimeter\tArea");

    for (count, triangle) in list.iter().enumerate().take(limit) {
        if area.map_or(true, |a| a == triangle.area as i32) {
            println!(
                "{} x {} x {}\t{}\t\t{}",
                triangle.a, triangle.b, triangle.c, triangle.perimeter, triangle.area as i32
            );
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() != 4 {
        println!("Usage: {} <Max side, max triangles to print and area, -1 for area to ignore>", args[0]);
    } else {
        let max_side = args[1].parse::<i32>().expect("Invalid max side");
        let limit = args[2].parse::<usize>().expect("Invalid limit");
        let area = args[3].parse::<i32>().ok().filter(|&x| x != -1);

        let herons = generate_triangle_list(max_side);
        println!("Triangles found: {}", herons.len());
        if let Some(area_val) = area {
            println!("\nPrinting triangles with area {} square units.", area_val);
        } else {
            println!("\nPrinting first {} triangles.", limit);
        }
        print_list(&herons, limit, area);
    }
}

