use std::io::{self, Write};

#[derive(Debug)]
struct Cell {
    data: i32,
    next: Option<Box<Cell>>,
}

type List = Option<Box<Cell>>;

fn add_to_list(mut list: List, num: i32) -> List {
    match list {
        None => Some(Box::new(Cell { data: num, next: None })),
        Some(ref mut head) => {
            let mut current = head;
            while let Some(ref mut next) = current.next {
                current = next;
            }
            current.next = Some(Box::new(Cell { data: num, next: None }));
            list
        }
    }
}

fn delete_from_list(mut list: List, pos: usize) -> List {
    if pos == 0 {
        return list;
    }

    match list {
        None => list,
        Some(ref mut head) if pos == 1 => head.next.take(),
        Some(ref mut head) => {
            let mut current = head;
            for _ in 1..pos - 1 {
                if let Some(ref mut next) = current.next {
                    current = next;
                } else {
                    break;
                }
            }
            current.next = current.next.take().and_then(|mut node| {
                node.next.take();
                Some(node)
            });
            list
        }
    }
}

fn print_list(list: &List) {
    print!("List contains following elements: ");
    let mut current = list;
    while let Some(ref cell) = current {
        print!("{} ", cell.data);
        current = &cell.next;
    }
    println!();
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() == 1 {
        println!("Usage: {} <list of integers to be inserted into the list>", args[0]);
        return;
    }

    let mut list: List = None;
    for arg in &args[1..] {
        if let Ok(num) = arg.parse::<i32>() {
            list = add_to_list(list, num);
        }
    }

    print_list(&list);

    loop {
        print!("Enter position of element to be removed (1-{}): ", args.len() - 1);
        io::stdout().flush().unwrap();

        let mut input = String::new();
        io::stdin().read_line(&mut input).expect("Failed to read line");

        if let Ok(pos) = input.trim().parse::<usize>() {
            if pos > 0 && pos <= args.len() - 1 {
                list = delete_from_list(list, pos);
                print_list(&list);
            } else {
                continue;
            }
        } else {
            continue;
        }

        break;
    }
}

