        return 0;
    }
    if ns.is_empty() || ns == "0" {
        return 0;
    }

    let mut value = 0;
    let mut bb = 1;
    for c in ns.chars().rev() {
        if let Some(i) = DIGITS.find(c) {
            value += i as isize * bb;
            bb *= base;
        }
    }

    value
}

