    if array.is_empty() {
        return;
    }

    let (min, max) = min_max(array);
    let range = (max - min + 1) as usize;
    let mut count = vec![0; range];

    for &value in array.iter() {
        count[(value - min) as usize] += 1;
    }

    let mut z = 0;
    for (i, &cnt) in count.iter().enumerate() {
        for _ in 0..cnt {
            array[z] = (i as i32) + min;
            z += 1;
        }
    }
}

fn min_max(array: &[i32]) -> (i32, i32) {
    let mut min = array[0];
    let mut max = array[0];
    for &value in array.iter().skip(1) {
        if value < min {
            min = value;
        } else if value > max {
            max = value;
        }
    }
    (min, max)
}

