use std::env;
use std::str::FromStr;

fn mean(arr: &[f64]) -> f64 {
    arr.iter().sum::<f64>() / arr.len() as f64
}

fn variance(reference: f64, arr: &[f64]) -> f64 {
    let squared_diffs: Vec<f64> = arr.iter().map(|&x| (reference - x).powi(2)).collect();
    mean(&squared_diffs)
}

fn extract_data(input: &str) -> Result<Vec<f64>, std::num::ParseFloatError> {
    input.split(',').map(f64::from_str).collect()
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        println!("Usage: {} <reference value> <observations separated by commas>", args[0]);
    } else {
        match extract_data(&args[2]) {
            Ok(arr) => {
                let reference = f64::from_str(&args[1]).unwrap();
                let mean_val = mean(&arr);

                println!("Average Error: {:.9}", variance(reference, &arr));
                println!("Crowd Error: {:.9}", (reference - mean_val).powi(2));
                println!("Diversity: {:.9}", variance(mean_val, &arr));
            }
            Err(e) => println!("Error parsing input: {}", e),
        }
    }
}

