		if(str[i++]==',')
			count++;
	}

	arr = (float*)malloc(count*sizeof(float));
	*len = count;

	token = strtok(str,",");

	i = 0;

	while(token!=NULL){
		arr[i++] = atof(token);
		token = strtok(NULL,",");
	}

	return arr;
}

