use std::cmp;

fn fusc(n: u32) -> u32 {
    match n {
        0 | 1 => n,
        _ if n % 2 == 0 => fusc(n / 2),
        _ => fusc((n - 1) / 2) + fusc((n + 1) / 2),
    }
}

fn num_len(mut n: u32) -> usize {
    let mut sum = 1;
    while n > 9 {
        n /= 10;
        sum += 1;
    }
    sum
}

