    println!("\n\nPrinting all largest Fusc numbers up to {}\nIndex-------Value", limit);
    let mut max_len = 1;

    for i in 0..=limit {
        let f = fusc(i);
        let len = num_len(f);

        if len > max_len {
            max_len = len;
            println!("{:5} {:12}", i, f);
        }
    }
}

fn main() {
    println!("Index-------Value");
    for i in 0..61 {
        println!("{:5} {:12}", i, fusc(i));
    }
    print_large_fuscs(u32::MAX);
}

