    let mut f = 0.0;
    for i in 0..n {
        for j in 0..n {
            let g = a[j + i * n];
            f += g * g;
        }
    }
    f = f.sqrt();
    let tol = f * 2.2204460492503131e-16;

    for i in 0..n {
        for j in 0..n {
            b[j + i * n] = if i == j { 1.0 } else { 0.0 };
        }
    }

    for k in 0..n {
        let mut f = a[k + k * n].abs();
        let mut p = k;
        for i in k + 1..n {
            let g = a[k + i * n].abs();
            if g > f {
                f = g;
                p = i;
            }
        }
        if f < tol {
            return Err("Matrix is singular or nearly singular");
        }
        if p != k {
            for j in k..n {
                a.swap(j + k * n, j + p * n);
            }
            for j in 0..n {
                b.swap(j + k * n, j + p * n);
            }
        }
        let f = 1.0 / a[k + k * n];
        for j in k..n {
            a[j + k * n] *= f;
        }
        for j in 0..n {
            b[j + k * n] *= f;
        }
        for i in 0..n {
            if i == k {
                continue;
            }
            let f = a[k + i * n];
            for j in k..n {
                a[j + i * n] -= a[j + k * n] * f;
            }
            for j in 0..n {
                b[j + i * n] -= b[j + k * n] * f;
            }
        }
    }

    Ok(())
}

