#include<stdio.h>
#include<stdlib.h>

int isprime( int p ) {
    int i;
    if(p==2) return 1;
    if(!(p%2)) return 0;
    for(i=3; i*i<=p; i+=2) {
       if(!(p%i)) return 0;
    }
    return 1;
}

int main( void ) {
   int s=0, p, i=1;
   for(p=2;p<=999;p++) {
       if(isprime(p)) {
           if(i%2) {
               s+=p;
               if(isprime(s)) printf( "%d       %d       %d\n", i, p, s );
           }
           i+=1;
       }
   }
   return 0;
}

887fa458c77564b474666118026e2ab2.rust_code:
fn is_prime(p: u32) -> bool {
    if p == 2 {
        return true;
    }
    if p % 2 == 0 {
        return false;
    }
    (3..=((p as f64).sqrt() as u32))
        .step_by(2)
        .all(|i| p % i != 0)
}

fn main() {
    let mut s = 0;
    let mut i = 1;
    for p in (2..=999).filter(|&x| is_prime(x)) {
        if i % 2 != 0 {
            s += p;
            if is_prime(s) {
                println!("{:<8}{:<8}{}", i, p, s);
            }
        }
        i += 1;
    }
}

