use std::env;
use std::str::FromStr;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() != 3 {
        println!("Usage: {} followed by length as <value> <unit>", args[0]);
        return;
    }

    let value = match f64::from_str(&args[1]) {
        Ok(val) => val,
        Err(_) => {
            println!("Invalid value: {}", args[1]);
            return;
        }
    };

    let unit = args[2].to_lowercase();

    let units = [
        "kilometer", "meter", "centimeter", "tochka", "liniya", "diuym", "vershok", "piad", "fut",
        "arshin", "sazhen", "versta", "milia",
    ];
    let factors = [
        1000.0, 1.0, 0.01, 0.000254, 0.00254, 0.0254, 0.04445, 0.1778, 0.3048, 0.7112, 2.1336, 1066.8,
        7467.6,
    ];

    if let Some(reference) = units.iter().position(|&u| unit.contains(u)) {
        let factor = value * factors[reference];

        println!("{} {} is equal in length to:", args[1], args[2]);

        for (i, &unit) in units.iter().enumerate() {
            if i != reference {
                println!("{:.6} {}", factor / factors[i], unit);
            }
        }
    } else {
        println!("Unknown unit: {}", args[2]);
    }
}

