use std::cmp::Ordering;

#[derive(Debug)]
struct FloatList {
    list: Vec<f32>,
}

impl FloatList {
    fn new(list: Vec<f32>) -> Self {
        FloatList { list }
    }

    fn median(&mut self) -> f32 {
        self.list.sort_by(|a, b| a.partial_cmp(b).unwrap_or(Ordering::Equal));
        let mid = self.list.len() / 2;
        0.5 * (self.list[mid] + self.list[mid.saturating_sub(1)])
    }
}

fn main() {
    let mut flist1 = FloatList::new(vec![5.1, 2.6, 6.2, 8.8, 4.6, 4.1]);
