struct Pair {
    x: usize,
    y: usize,
}

fn prime_sieve(limit: usize) -> Vec<usize> {
    let mut c = vec![false; limit + 1];
    c[0] = true;
    c[1] = true;
    for i in (4..=limit).step_by(2) {
        c[i] = true;
    }
    let mut p = 3;
    while p * p <= limit {
        let p2 = p * p;
        for i in (p2..=limit).step_by(2 * p) {
            c[i] = true;
        }
        p += 2;
        while c[p] {
            p += 2;
        }
    }
    c.iter()
        .enumerate()
        .filter_map(|(i, &is_composite)| if !is_composite { Some(i) } else { None })
        .collect()
}

fn digit_sum(mut n: usize) -> usize {
    let mut sum = 0;
    while n > 0 {
        sum += n % 10;
        n /= 10;
    }
    sum
