    let primes = prime_sieve(LIMIT);
    let mut h = Vec::with_capacity(50);
    let mut h10000 = Pair { x: 0, y: 0 };
    let mut count = 0;
    let mut hc = 0;

    for (i, &prime) in primes.iter().enumerate() {
        if digit_sum(i + 1) == digit_sum(prime) {
            count += 1;
