fn check_isbn13(isbn: &str) -> bool {
    let mut count = 0;
    let mut sum = 0;

    for ch in isbn.chars() {
        match ch {
            ' ' | '-' => continue,
            '0'..='9' => {
                let digit = ch.to_digit(10).unwrap();
                if count % 2 == 1 {
                    sum += 3 * digit;
                } else {
                    sum += digit;
                }
                count += 1;
            }
            _ => return false,
        }
    }

    count == 13 && sum % 10 == 0
}

