#include <stdio.h>
#include <stdlib.h>

typedef unsigned long long ULONG;

ULONG get_prime(int idx)
{
        static long n_primes = 0, alloc = 0;
        static ULONG *primes = 0;
        ULONG last, p;
        int i;

        if (idx >= n_primes) {
                if (n_primes >= alloc) {
                        alloc += 16; 
                        primes = realloc(primes, sizeof(ULONG) * alloc);
                }
                if (!n_primes) {
                        primes[0] = 2;
                        primes[1] = 3;
                        n_primes = 2;
                }

                last = primes[n_primes-1];
                while (idx >= n_primes) {
                        last += 2;
                        for (i = 0; i < n_primes; i++) {
                                p = primes[i];
                                if (p * p > last) {
                                        primes[n_primes++] = last;
                                        break;
                                }
                                if (last % p == 0) break;
                        }
                }
        }
        return primes[idx];
}

int main()
{
        ULONG n, x, p;
        int i, first;

        for (x = 1; ; x++) {
                printf("%lld = ", n = x);

                for (i = 0, first = 1; ; i++) {
                        p = get_prime(i);
                        while (n % p == 0) {
                                n /= p;
                                if (!first) printf(" x ");
                                first = 0;
                                printf("%lld", p);
                        }
                        if (n <= p * p) break;
                }

                if (first)      printf("%lld\n", n);
                else if (n > 1) printf(" x %lld\n", n);
                else            printf("\n");
        }
        return 0;
}

6255ad7434c538ed522ab5a55efef12c.rust_code:
use std::collections::VecDeque;

fn get_prime(idx: usize) -> u64 {
    static mut PRIMES: VecDeque<u64> = VecDeque::new();

    unsafe {
        if idx >= PRIMES.len() {
            if PRIMES.is_empty() {
                PRIMES.push_back(2);
                PRIMES.push_back(3);
            }

            let mut last = *PRIMES.back().unwrap();
            while idx >= PRIMES.len() {
                last += 2;
                let mut is_prime = true;
                for &p in &PRIMES {
                    if p * p > last {
                        break;
                    }
                    if last % p == 0 {
                        is_prime = false;
                        break;
                    }
                }
                if is_prime {
                    PRIMES.push_back(last);
                }
            }
        }
        *PRIMES.get(idx).unwrap()
    }
}

fn main() {
    let mut x = 1;
    loop {
        print!("{} = ", x);
        let mut n = x;
        let mut first = true;
        for i in 0.. {
            let p = get_prime(i);
            while n % p == 0 {
                n /= p;
                if !first {
                    print!(" x ");
                }
                first = false;
                print!("{}", p);
            }
            if n <= p * p {
                break;
            }
        }
        if first {
            println!("{}", n);
        } else if n > 1 {
            println!(" x {}", n);
        } else {
            println!();
        }
        x += 1;
    }
}

