#include <stdio.h>

int gcd(int a, int b) {
    int c;
    while (b) {
        c = a;
        a = b;
        b = c % b;
    }
    return a;
}

struct pair {
    int x, y;
};

void printPair(struct pair const *p) {
    printf("{%d, %d}\n", p->x, p->y);
}

int main() {
    struct pair pairs[] = {
        {21,15}, {17,23}, {36,12}, {18,29}, {60,15}
    };

    int i;
    for (i=0; i<5; i++) {
        if (gcd(pairs[i].x, pairs[i].y) == 1)
            printPair(&pairs[i]);
    }
    return 0;
}

7cb29c24954730c141b3a5bc2ec671f5.rust_code:
fn gcd(mut a: i32, mut b: i32) -> i32 {
    while b != 0 {
        let c = a;
        a = b;
        b = c % b;
    }
    a
}

#[derive(Debug)]
struct Pair {
    x: i32,
    y: i32,
}

impl Pair {
    fn print(&self) {
        println!("{{{},{}}}", self.x, self.y);
    }
}

fn main() {
    let pairs = vec![
        Pair { x: 21, y: 15 },
        Pair { x: 17, y: 23 },
        Pair { x: 36, y: 12 },
        Pair { x: 18, y: 29 },
        Pair { x: 60, y: 15 },
    ];

    for pair in &pairs {
        if gcd(pair.x, pair.y) == 1 {
            pair.print();
        }
    }
}

