#include <stdio.h>
#include <string.h>

#define LIMIT 1000

void sieve(int max, char *s) {
    int p, k;
    memset(s, 0, max);
    for (p=2; p*p<=max; p++)
        if (!s[p]) 
            for (k=p*p; k<=max; k+=p) 
                s[k]=1;
}

int main(void) {
    char primes[LIMIT+1];
    int p, count=0;

    sieve(LIMIT, primes);
    for (p=2; p<=LIMIT; p++) {
        if (!primes[p] && !primes[p+4]) {
            count++;
            printf("%4d: %4d\n", p, p+4);
        }
    }

    printf("There are %d cousin prime pairs below %d.\n", count, LIMIT);
    return 0;
}

bf2ebbca5b2373de9b0d995129ab2e7c.rust_code:
fn sieve(max: usize, s: &mut [bool]) {
    for p in 2..=((max as f64).sqrt() as usize) {
        if !s[p] {
            for k in (p * p..=max).step_by(p) {
                s[k] = true;
            }
        }
    }
}

fn main() {
    let limit = 1000;
    let mut primes = vec![false; limit + 1];

    sieve(limit, &mut primes);
    let mut count = 0;

    for p in 2..=limit {
        if !primes[p] && !primes[p + 4] {
            count += 1;
            println!("{:4}: {:4}", p, p + 4);
        }
    }

    println!("There are {} cousin prime pairs below {}.", count, limit);
}

