use std::rc::Rc;
use std::cell::RefCell;

#[derive(Clone)]
struct ListEntry {
    value: Option<String>,
    next: Option<Rc<RefCell<ListEntry>>>,
    prev: Option<Rc<RefCell<ListEntry>>>,
}

type LinkedList = Rc<RefCell<ListEntry>>;
type LIterator = Rc<RefCell<IteratorState>>;

struct IteratorState {
    link: Option<Rc<RefCell<ListEntry>>>,
    head: LinkedList,
}

impl ListEntry {
    fn new(value: Option<&str>) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(ListEntry {
            value: value.map(String::from),
            next: None,
            prev: None,
        }))
    }
}

fn new_list() -> LinkedList {
    ListEntry::new(None)
}

fn ll_append(ll: &LinkedList, new_val: &str) -> bool {
    let new_entry = ListEntry::new(Some(new_val));
    let mut tail = ll.borrow_mut();
    if let Some(prev) = tail.prev.clone() {
        prev.borrow_mut().next = Some(new_entry.clone());
    } else {
        tail.next = Some(new_entry.clone());
    }
    tail.prev = Some(new_entry);
    true
}

fn li_insert(iter: &LIterator, new_val: &str) -> bool {
    let new_entry = ListEntry::new(Some(new_val));
    let current = iter.borrow().link.clone();
    let head = iter.borrow().head.clone();

    if current.as_ref().map_or(true, |c| Rc::ptr_eq(&c, &head)) {
        new_entry.borrow_mut().next = head.borrow().next.clone();
        if let Some(next) = new_entry.borrow().next.clone() {
            next.borrow_mut().prev = Some(new_entry.clone());
        } else {
            head.borrow_mut().prev = Some(new_entry.clone());
        }
        head.borrow_mut().next = Some(new_entry);
    } else {
        new_entry.borrow_mut().prev = current.as_ref().and_then(|c| c.borrow().prev.clone()).or_else(|| head.borrow().prev.clone());
        new_entry.borrow_mut().next = current.clone();
        if let Some(prev) = new_entry.borrow().prev.clone() {
            prev.borrow_mut().next = Some(new_entry.clone());
        } else {
            head.borrow_mut().next = Some(new_entry.clone());
        }
        if let Some(c) = current {
            c.borrow_mut().prev = Some(new_entry);
        } else {
            head.borrow_mut().prev = Some(new_entry);
        }
    }
    true
}

fn ll_get_iterator(ll: &LinkedList) -> LIterator {
    Rc::new(RefCell::new(IteratorState {
        link: ll.borrow().next.clone(),
        head: ll.clone(),
    }))
}

fn lli_at_end(iter: &LIterator) -> bool {
    iter.borrow().link.is_none()
}

fn lli_value(iter: &LIterator) -> Option<String> {
    iter.borrow().link.as_ref().and_then(|entry| entry.borrow().value.clone())
}

fn lli_next(iter: &LIterator) -> bool {
    if let Some(link) = iter.borrow().link.clone() {
        iter.borrow_mut().link = link.borrow().next.clone();
    }
    !lli_at_end(iter)
}

fn lli_prev(iter: &LIterator) -> bool {
    if let Some(link) = iter.borrow().link.clone() {
        iter.borrow_mut().link = link.borrow().prev.clone();
    }
    !lli_at_end(iter)
}

fn main() {
    let contents = ["Read", "Orage", "Yeller", "Glean", "Blew", "Burple"];
    let ll = new_list();

    for content in &contents {
        ll_append(&ll, content);
    }

    let iter = ll_get_iterator(&ll);
    println!("forward");
    let mut iter_clone = iter.clone();
    while lli_next(&iter_clone) {
        if let Some(value) = lli_value(&iter_clone) {
            println!("value={}", value);
        }
    }

    println!("\nreverse");
    let mut iter_clone = iter.clone();
    while lli_prev(&iter_clone) {
        if let Some(value) = lli_value(&iter_clone) {
            println!("value={}", value);
        }
    }
}

