use std::f64;

#[derive(Debug)]
struct SquareMatrix {
    n: usize,
    elems: Vec<Vec<f64>>,
}

impl SquareMatrix {
    fn new(n: usize, elems: &[[f64; 4]]) -> Self {
        let mut matrix = vec![vec![0.0; n]; n];
        for (i, row) in elems.iter().enumerate().take(n) {
            for (j, &val) in row.iter().enumerate().take(n) {
                matrix[i][j] = val;
            }
        }
        SquareMatrix { n, elems: matrix }
    }

    fn copy(&self) -> Self {
        SquareMatrix {
            n: self.n,
            elems: self.elems.clone(),
        }
    }

    fn determinant(&mut self) -> f64 {
        let mut det = 1.0;

        for j in 0..self.n {
            let mut i_max = j;
            for i in j..self.n {
                if self.elems[i][j].abs() > self.elems[i_max][j].abs() {
                    i_max = i;
                }
            }

            if i_max != j {
                self.elems.swap(i_max, j);
                det *= -1.0;
            }

            if self.elems[j][j].abs() < 1e-12 {
                eprintln!("Singular matrix!");
                return f64::NAN;
            }

            for i in j + 1..self.n {
                let mult = -self.elems[i][j] / self.elems[j][j];
                for k in 0..self.n {
                    self.elems[i][k] += mult * self.elems[j][k];
                }
            }
        }

        for i in 0..self.n {
            det *= self.elems[i][i];
        }

        det
    }

    fn solve_cramer(&mut self, det_a: f64, b: &[f64], var: usize) -> f64 {
        let mut tmp = self.copy();
        for i in 0..tmp.n {
            tmp.elems[i][var] = b[i];
        }

        let det_tmp = tmp.determinant();

        det_tmp / det_a
    }
}

fn main() {
    const N: usize = 4;
    let elems = [
        [2.0, -1.0, 5.0, 1.0],
        [3.0, 2.0, 2.0, -6.0],
        [1.0, 3.0, 3.0, -1.0],
        [5.0, -2.0, -3.0, 3.0],
    ];
    let mut a = SquareMatrix::new(N, &elems);

    let mut tmp = a.copy();
    let det_a = tmp.determinant();

    let b = [-3.0, -32.0, -47.0, 49.0];

    for i in 0..N {
        println!("{:7.3}", a.solve_cramer(det_a, &b, i));
    }
}

