use std::str::FromStr;

fn number_of_digits(mut x: i32) -> usize {
    let mut number_of_digits = 0;
    while x != 0 {
        x /= 10;
        number_of_digits += 1;
    }
    number_of_digits
}

fn convert_array(array: &str) -> Vec<i32> {
    let mut converted_array = Vec::new();
    let mut original_element = 0;

    while original_element < array.len() {
        let digit_count = array[original_element..]
            .chars()
