use std::io::{self, BufRead};

const SEDOL_WEIGHTS: [u8; 6] = [1, 3, 1, 7, 3, 9];
const REJECT_CHARS: &[char] = &['A', 'E', 'I', 'O', 'U', 'a', 'e', 'i', 'o', 'u'];

fn sedol_checksum(sedol6: &str) -> Result<char, &'static str> {
    let len = sedol6.len();
    if len == 7 {
        eprintln!("SEDOL code already checksummed? ({})", sedol6);
        return Ok(sedol6.chars().nth(6).unwrap());
    }
    if len != 6 || sedol6.chars().any(|c| REJECT_CHARS.contains(&c)) {
        eprintln!("not a SEDOL code? ({})", sedol6);
        return Err("Invalid SEDOL code");
    }

    let mut sum = 0;
    for (i, c) in sedol6.chars().enumerate() {
        let weight = SEDOL_WEIGHTS[i];
        sum += match c {
            '0'..='9' => (c as u8 - b'0') as u32 * weight as u32,
            'A'..='Z' | 'a'..='z' => ((c.to_ascii_uppercase() as u8 - b'A' + 10) as u32) * weight as u32,
            _ => {
                eprintln!("SEDOL with non-alphanumeric digit");
                return Err("Non-alphanumeric character in SEDOL");
            }
        };
    }
    Ok(std::char::from_digit((10 - (sum % 10)) % 10, 10).unwrap())
}

fn main() {
    let stdin = io::stdin();
    for line in stdin.lock().lines() {
        if let Ok(mut line) = line {
            if line.ends_with('\n') {
                line.pop();
            }
            if let Ok(checksum) = sedol_checksum(&line) {
                println!("{}{}", line, checksum);
            }
        }
    }
}

