    if tutor {
        println!("ethiopian multiplication of {} by {}", plier, plicand);
    }

    while plier >= 1 {
        if is_even(plier) {
            if tutor {
                println!("{:4} {:6} struck", plier, plicand);
            }
        } else {
            if tutor {
                println!("{:4} {:6} kept", plier, plicand);
            }
            result += plicand;
        }
        halve(&mut plier);
        doublit(&mut plicand);
    }
    result
}

