fn is_prime(p: u32) -> bool {
    if p == 2 {
        return true;
    }
    if p % 2 == 0 {
        return false;
    }
    (3..=((p as f64).sqrt() as u32))
        .step_by(2)
        .all(|i| p % i != 0)
}

fn prime(n: u32) -> u32 {
    if n == 1 {
        return 2;
