        for i in 0..dates.len() {
            if !dates[i].2 {
                continue;
            }
            let count = dates.iter().filter(|&&(_, _, a)| a && dates[i].0 == dates[i].0).count();
            if count > 1 {
                for j in 0..dates.len() {
                    if !dates[j].2 {
                        continue;
                    }
                    if dates[j].0 == dates[i].0 {
                        dates[j].2 = false;
                    }
                }
            }
        }
    }

    print_remaining(&dates);

    first_pass(&mut dates);

    print_remaining(&dates);

    second_pass(&mut dates);

    print_remaining(&dates);

    third_pass(&mut dates);

    print_answer(&dates, &months);
}

