#include<stdlib.h>
#include<string.h>
#include<stdio.h>

unsigned long long bruteForceProperDivisorSum(unsigned long long n){
	unsigned long long i,sum = 0;

	for(i=1;i<(n+1)/2;i++)
		if(n%i==0 && n!=i)
			sum += i;

	return sum;
}

void printSeries(unsigned long long* arr,int size,char* type){
	int i;

	printf("\nInteger : %llu, Type : %s, Series : ",arr[0],type);

	for(i=0;i<size-1;i++)
		printf("%llu, ",arr[i]);
	printf("%llu",arr[i]);
}

void aliquotClassifier(unsigned long long n){
	unsigned long long arr[16];
	int i,j;

	arr[0] = n;

	for(i=1;i<16;i++){
		arr[i] = bruteForceProperDivisorSum(arr[i-1]);

		if(arr[i]==0||arr[i]==n||(arr[i]==arr[i-1] && arr[i]!=n)){
			printSeries(arr,i+1,(arr[i]==0)?"Terminating":(arr[i]==n && i==1)?"Perfect":(arr[i]==n && i==2)?"Amicable":(arr[i]==arr[i-1] && arr[i]!=n)?"Aspiring":"Sociable");
			return;
		}

		for(j=1;j<i;j++){
			if(arr[j]==arr[i]){
				printSeries(arr,i+1,"Cyclic");
				return;
			}
		}
	}

	printSeries(arr,i+1,"Non-Terminating");
}

void processFile(char* fileName){
	FILE* fp = fopen(fileName,"r");
	char str[21];

	while(fgets(str,21,fp)!=NULL)
		aliquotClassifier(strtoull(str,(char**)NULL,10));

	fclose(fp);
}

int main(int argC,char* argV[])
{
    if(argC!=2)
		printf("Usage : %s <positive integer>",argV[0]);
	else{
		if(strchr(argV[1],'.')!=NULL)
			processFile(argV[1]);
		else
			aliquotClassifier(strtoull(argV[1],(char**)NULL,10));
	}
	return 0;
}

412a2750a45f91bb02b0e8f61d1cea15.rust_code:
use std::fs::File;
use std::io::{self, BufRead};
use std::str;

fn brute_force_proper_divisor_sum(n: u64) -> u64 {
    (1..n / 2 + 1).filter(|&i| n % i == 0).sum()
}

fn print_series(arr: &[u64], series_type: &str) {
    print!("\nInteger: {}, Type: {}, Series: ", arr[0], series_type);
    for (i, &num) in arr.iter().enumerate() {
        if i != arr.len() - 1 {
            print!("{}, ", num);
        } else {
            println!("{}", num);
        }
    }
}

fn aliquot_classifier(n: u64) {
    let mut arr = vec![n; 16];

    for i in 1..16 {
        arr[i] = brute_force_proper_divisor_sum(arr[i - 1]);

        match arr[i] {
            0 | _ if arr[i] == n => {
                let series_type = if arr[i] == 0 {
                    "Terminating"
                } else if i == 1 {
                    "Perfect"
                } else if i == 2 {
                    "Amicable"
                } else {
                    "Sociable"
                };
                print_series(&arr[..i + 1], series_type);
                return;
            }
            _ if arr[i] == arr[i - 1] => {
                print_series(&arr[..i + 1], "Aspiring");
                return;
            }
            _ => {
                if arr[1..i].contains(&arr[i]) {
                    print_series(&arr[..i + 1], "Cyclic");
                    return;
                }
            }
        }
    }

    print_series(&arr, "Non-Terminating");
}

fn process_file(file_name: &str) -> io::Result<()> {
    let file = File::open(file_name)?;
    let reader = io::BufReader::new(file);

    for line in reader.lines() {
        if let Ok(num_str) = line {
            if let Ok(num) = num_str.trim().parse::<u64>() {
                aliquot_classifier(num);
            }
        }
    }

    Ok(())
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 2 {
        println!("Usage: {} <positive integer>", args[0]);
    } else if args[1].contains('.') {
        if let Err(e) = process_file(&args[1]) {
            eprintln!("Error processing file: {}", e);
        }
    } else if let Ok(num) = args[1].trim().parse::<u64>() {
        aliquot_classifier(num);
    } else {
        println!("Invalid input. Please provide a positive integer.");
    }
}

