    let mut count = 0;
    for n in 1..500 {
        if is_prime(n) && is_prime(reverse(n)) {
            print!("{:3}", n);
            count += 1;
            if count % 10 == 0 {
                println!();
            } else {
                print!(" ");
            }
        }
    }
    println!("\nCount = {}", count);
}

