use std::fs::File;
use std::io::{self, BufRead, BufReader};

fn cusip_check(cusip_str: &str) -> u8 {
    let mut sum = 0;

    for (i, c) in cusip_str.chars().take(8).enumerate() {
        let v = match c {
            '0'..='9' => c as u8 - b'0',
            'A'..='Z' => c as u8 - b'A' + 10,
            '*' => 36,
            '@' => 37,
            '#' => 38,
            _ => continue,
        };

        let v = if i % 2 != 0 { v * 2 } else { v };
        sum += v / 10 + v % 10;
    }

    (10 - (sum % 10)) % 10
}

fn main() -> io::Result<()> {
    if std::env::args().len() == 1 {
        eprintln!("Usage: {} <full path of CUSIP Data file>", std::env::args().next().unwrap());
        return Ok(());
    }

    let file_path = std::env::args().nth(1).unwrap();
    let file = File::open(file_path)?;
    let reader = BufReader::new(file);

    let mut lines = reader.lines();
    if let Some(first_line) = lines.next() {
        let num_lines: usize = first_line?.parse().unwrap();

        println!("CUSIP       Verdict");
        println!("-------------------");

        for line in lines.take(num_lines) {
            let cusip_str = line?;
            let expected_digit = cusip_str.chars().nth(8).unwrap().to_digit(10).unwrap() as u8;
            let verdict = if cusip_check(&cusip_str) == expected_digit { "Valid" } else { "Invalid" };
            println!("{} : {}", cusip_str, verdict);
        }
    }

    Ok(())
}

