use std::sync::{Arc, Mutex, Condvar};
use std::thread;
use std::time::Duration;

fn enjoy(cond_pair: Arc<(Mutex<i32>, Condvar)>) {
    let (lock, cvar) = &*cond_pair;
    let mut bang = lock.lock().unwrap();
    while *bang == 0 {
        bang = cvar.wait(bang).unwrap();
    }
    println!("Enjoy");
}

fn rosetta(cond_pair: Arc<(Mutex<i32>, Condvar)>) {
    let (lock, cvar) = &*cond_pair;
    let mut bang = lock.lock().unwrap();
    while *bang == 0 {
        bang = cvar.wait(bang).unwrap();
    }
    println!("Rosetta");
}

fn code(cond_pair: Arc<(Mutex<i32>, Condvar)>) {
    let (lock, cvar) = &*cond_pair;
    let mut bang = lock.lock().unwrap();
    while *bang == 0 {
        bang = cvar.wait(bang).unwrap();
    }
    println!("Code");
}

fn main() {
    let cond_pair = Arc::new((Mutex::new(0), Condvar::new()));
    let mut handles = vec![];

    for func in &[enjoy, rosetta, code] {
        let cond_pair_clone = Arc::clone(&cond_pair);
        handles.push(thread::spawn(move || {
            func(cond_pair_clone);
        }));
    }

    thread::sleep(Duration::from_secs(1));
    let (lock, cvar) = &*cond_pair;
    let mut bang = lock.lock().unwrap();
    *bang = 1;
    cvar.notify_all();

    for handle in handles {
        handle.join().unwrap();
    }
}

