fn elq(s: &str, sep: char, esc: char) -> usize {
    let mut q = 1;
    let mut e = false;

    for c in s.chars() {
        if c == esc {
            e = !e;
        } else if c == sep {
            if !e {
                q += 1;
            }
        } else {
            e = false;
        }
    }

    q
