    let q = elq(s, sep, esc);
    let mut list = Vec::with_capacity(q);
    let mut e = false;

    let mut start = 0;
    for (i, c) in s.char_indices() {
        if c == esc {
            e = !e;
        } else if c == sep {
            if !e {
                list.push(&s[start..i]);
                start = i + 1;
            }
        } else {
            e = false;
        }
    }
    list.push(&s[start..]);

    list
}

