use std::f64;

fn factorial(n: u32) -> u64 {
    let mut result = 1;
    for i in 1..=n {
        result *= i as u64;
    }
    result
}

fn inverse_factorial(f: u64) -> Option<u32> {
    if f == 1 {
        return Some(0);
    }

    let mut p = 1;
    let mut i = 1;
    while p < f {
