#include <stdio.h>

int check_isbn13(const char *isbn) {
    int ch = *isbn, count = 0, sum = 0;

    for ( ; ch != 0; ch = *++isbn, ++count) {

        if (ch == ' ' || ch == '-') {
            --count;
            continue;
        }
        if (ch < '0' || ch > '9') {
            return 0;
        }
        if (count & 1) {
            sum += 3 * (ch - '0');
        } else {
            sum += ch - '0';
        }
    }
    if (count != 13) return 0;
    return !(sum%10);
}

int main() {
    int i;
    const char* isbns[] = {"978-1734314502", "978-1734314509", "978-1788399081", "978-1788399083"};
    for (i = 0; i < 4; ++i) {
        printf("%s: %s\n", isbns[i], check_isbn13(isbns[i]) ? "good" : "bad");
    }
    return 0;
}

6dab3bb067378beb3f398b794e213b07.rust_code:
fn check_isbn13(isbn: &str) -> bool {
    let mut count = 0;
    let mut sum = 0;

    for ch in isbn.chars() {
        match ch {
            ' ' | '-' => continue,
            '0'..='9' => {
                let digit = ch.to_digit(10).unwrap();
                if count % 2 == 1 {
                    sum += 3 * digit;
                } else {
                    sum += digit;
                }
                count += 1;
            }
            _ => return false,
        }
    }

    count == 13 && sum % 10 == 0
}

fn main() {
    let isbns = ["978-1734314502", "978-1734314509", "978-1788399081", "978-1788399083"];
    for isbn in isbns.iter() {
        println!("{}: {}", isbn, if check_isbn13(isbn) { "good" } else { "bad" });
    }
}

