#include<stdio.h>
#include<stdlib.h>

int isprime( int p ) {
    int i;
    if(p==2) return 1;
    if(!(p%2)) return 0;
    for(i=3; i*i<=p; i+=2) {
       if(!(p%i)) return 0;
    }
    return 1;
}

int prime( int n ) {
    int p, pn=1;
    if(n==1) return 2;
    for(p=3;pn<n;p+=2) {
        if(isprime(p)) pn++;
    }
    return p-2;
}

int main(void) {
    printf( "%d\n", prime(10001) );
    return 0;
}

1ffd62fd4411658879c108fb8cdf155a.rust_code:
fn is_prime(p: u32) -> bool {
    if p == 2 {
        return true;
    }
    if p % 2 == 0 {
        return false;
    }
    (3..=((p as f64).sqrt() as u32))
        .step_by(2)
        .all(|i| p % i != 0)
}

fn prime(n: u32) -> u32 {
    if n == 1 {
        return 2;
    }
    let mut p = 3;
    let mut pn = 1;
    while pn < n {
        if is_prime(p) {
            pn += 1;
        }
        p += 2;
    }
    p - 2
}

fn main() {
    println!("{}", prime(10001));
}

