use std::f64;

fn main() {
    const MU_MAX: usize = 1_000_000;
    let mut mu = vec![1; MU_MAX + 1];
    let sqroot = (MU_MAX as f64).sqrt() as usize;

    for i in 2..=sqroot {
        if mu[i] == 1 {
            for j in (i..=MU_MAX).step_by(i) {
                mu[j] *= -(i as i32);
            }
            for j in (i * i..=MU_MAX).step_by(i * i) {
                mu[j] = 0;
            }
        }
    }

    for i in 2..=MU_MAX {
        mu[i] = match mu[i] {
            x if x == i as i32 => 1,
            x if x == -(i as i32) => -1,
            _ if mu[i] < 0 => 1,
            _ => -1,
        };
    }

    println!("First 199 terms of the möbius function are as follows:");
    print!("    ");
    for (i, &value) in mu.iter().enumerate().take(200).skip(1) {
        print!("{:2}  ", value);
        if (i + 1) % 20 == 0 {
            println!();
        }
    }
}

