    print!("Enter arabic number:\n");
    io::stdout().flush()?;
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let n: i32 = input.trim().parse().expect("Please enter a valid integer");

    print!("\nRoman number:\n");
    let mut remaining = n;
    for (&value, &symbol) in arabic.iter().zip(roman.iter()) {
        while remaining >= value {
            print!("{}", symbol);
            remaining -= value;
        }
    }
    println!();

    Ok(())
}

