fn next_perm(nums: &mut [usize]) -> bool {
    if let Some(k) = (0..nums.len().saturating_sub(1))
        .rev()
        .find(|&k| nums[k] < nums[k + 1])
    {
        let l = (k + 1..nums.len())
            .rev()
            .find(|&l| nums[l] > nums[k])
            .unwrap();
        nums.swap(k, l);
        nums[k + 1..].reverse();
        true
    } else {
        false
    }
}

fn make_part(n: usize, sizes: &[usize]) {
    let mut x = Vec::with_capacity(sizes.iter().sum());
    for (i, &size) in sizes.iter().enumerate() {
        x.extend(std::iter::repeat(i).take(size));
    }

    loop {
        for i in 0..n {
            print!(" {{ ");
            for (j, &val) in x.iter().enumerate() {
                if val == i {
                    print!("{} ", j);
                }
            }
            print!("}}");
        }
        println!();
        if !next_perm(&mut x) {
            break;
        }
    }
}

