use std::io::{self, Write};

fn main() -> io::Result<()> {
    let mut inputs = [0.0; 11];
    let check = 400.0;

    println!("\nPlease enter 11 numbers:");

    for input in inputs.iter_mut() {
        print!("> ");
        io::stdout().flush()?;
        *input = read_input()?;
    }

    println!("\n\n\nEvaluating f(x) = |x|^0.5 + 5x^3 for the given inputs:");

    for &input in inputs.iter().rev() {
        let result = input.abs().sqrt() + 5.0 * input.powi(3);

        print!("f({}) = ", input);

        if result > check {
            println!("Overflow!");
        } else {
            println!("{}", result);
        }
    }

    Ok(())
}

fn read_input() -> io::Result<f64> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    input.trim().parse().map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "Please enter a valid number"))
}

