fn kprime(n: u32, k: u32) -> bool {
    let mut p = 2;
    let mut f = 0;
    while f < k && p * p <= n {
        while n % p == 0 {
            f += 1;
            if f >= k {
                break;
            }
            p *= n / p;
        }
        p += 1;
    }
    f + (if n > 1 { 1 } else { 0 }) == k
}

fn main() {
    for k in 1..=5 {
        print!("k = {}: ", k);
        let mut count = 0;
        let mut i = 2;
        while count < 10 {
            if kprime(i, k) {
                print!("{} ", i);
                count += 1;
            }
            i += 1;
        }
        println!();
    }
