use std::fs::File;
use std::io::{self, BufRead, BufReader};

fn check(word: &str) -> bool {
    let mut e_count = 0;
    let mut ok = true;

    for c in word.chars() {
        match c {
            'a' | 'i' | 'o' | 'u' => {
                ok = false;
                break;
            }
            'e' => e_count += 1,
            _ => {}
        }
    }

    ok && e_count > 3
}

fn main() -> io::Result<()> {
    let file = File::open("unixdict.txt")?;
    let reader = BufReader::new(file);

    for line in reader.lines() {
        let line = line?;
        if check(&line) {
            println!("{}", line);
        }
    }

    Ok(())
}

