    c[0] += 1;
    c[n] -= 1;
    c.iter().take(n + 1).all(|&x| x % n as i64 == 0)
}

fn show(c: &[i64], n: usize) {
    for i in (0..=n).rev() {
        print!("{:+}x^{}", c[i], i);
    }
}

fn main() {
    for n in 0..10 {
        let mut c = vec![0; MAX_N];
        coef(&mut c, n);
        print!("(x-1)^{} = ", n);
        show(&c, n);
        println!();
    }

    print!("\nprimes (never mind the 1):");
    for n in 1..=63 {
        if is_prime(n) {
            print!(" {}", n);
        }
    }
    println!();
}

