const BASE64: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

fn find_index(val: u8) -> Option<usize> {
    match val {
        b'A'..=b'Z' => Some((val - b'A') as usize),
        b'a'..=b'z' => Some((val - b'a' + 26) as usize),
        b'0'..=b'9' => Some((val - b'0' + 52) as usize),
        b'+' => Some(62),
        b'/' => Some(63),
        _ => None,
    }
}

fn decode(source: &str) -> Result<Vec<u8>, &'static str> {
    let bytes = source.as_bytes();
    if bytes.len() % 4 != 0 {
        return Err("Invalid base64 input length");
    }

    let mut sink = Vec::with_capacity(bytes.len() * 3 / 4);
    let mut it = bytes.iter().copied();

    while let (Some(b1), Some(b2), Some(b3), Some(b4)) = (it.next(), it.next(), it.next(), it.next()) {
        let i1 = find_index(b1).ok_or("Invalid base64 character")?;
        let i2 = find_index(b2).ok_or("Invalid base64 character")?;

        let mut acc = i1 << 2;
        acc |= i2 >> 4;
        sink.push(acc as u8);

        if b3 != b'=' {
            let i3 = find_index(b3).ok_or("Invalid base64 character")?;

            acc = (i2 & 0xF) << 4;
            acc |= i3 >> 2;
            sink.push(acc as u8);

            if b4 != b'=' {
                let i4 = find_index(b4).ok_or("Invalid base64 character")?;

                acc = (i3 & 0x3) << 6;
                acc |= i4;
                sink.push(acc as u8);
            }
        }
    }

    Ok(sink)
}

fn main() {
    let data = "VG8gZXJyIGlzIGh1bWFuLCBidXQgdG8gcmVhbGx5IGZvdWwgdGhpbmdzIHVwIHlvdSBuZWVkIGEgY29tcHV0ZXIuCiAgICAtLVBhdWwgUi5FaHJsaWNo";
    match decode(data) {
        Ok(decoded) => println!("{}", String::from_utf8_lossy(&decoded)),
        Err(e) => eprintln!("Decoding error: {}", e),
    }
}

