fn find_num_of_dec(s: &str) -> usize {
    let pos = s.find('.').map_or(s.len(), |pos| pos + 1);
    s[pos..].len()
}

fn test(s: &str) {
    let num = find_num_of_dec(s);
    let suffix = if num != 1 { "s" } else { "" };
    println!("{} has {} decimal{}", s, num, suffix);
}

fn main() {
    test("12");
    test("12.0");
    test("12.345");
    test("12.345555555555");
    test("12.3450");
    test("12.34555555555555555555");
    let str_val = format!("{:e}", 1.2345e+54);
    test(&str_val);
}

