    while i % 2 == 0 {
        i /= 2;
    }
    while i % 3 == 0 {
        i /= 3;
    }
    while i % 5 == 0 {
        i /= 5;
    }
    while i % 7 == 0 {
        i /= 7;
    }
    i == 1
}

fn main() {
    let limit = i16::MAX as usize;
    let mut humble = vec![0; 16];
    let mut count = 0;
    let mut num = 1;

    for _ in 0..limit {
        if is_humble(num) {
            let mut buffer = String::new();
            write!(&mut buffer, "{}", num).unwrap();
            let len = buffer.len();
            if len >= 16 {
                break;
            }
            humble[len] += 1;

            if count < 50 {
                print!("{} ", num);
            }
            count += 1;
        }
        num += 1;
    }
    println!();

    println!("Of the first {} humble numbers:", count);
    for num in 1..10 {
        println!("{:>5} have {} digits", humble[num], num);
    }
}

