fn find_num_of_dec(x: f64) -> usize {
    let formatted = format!("{:.14}", x);
    let mut num = 0;
    if let Some(dot_pos) = formatted.find('.') {
        let mut pos = formatted.len().saturating_sub(1);
        while pos > dot_pos && formatted.as_bytes()[pos] == b'0' {
            pos = pos.saturating_sub(1);
        }
        while pos > dot_pos {
            num += 1;
            pos = pos.saturating_sub(1);
        }
    }
    num
}

fn test(x: f64) {
    let num = find_num_of_dec(x);
    println!("{} has {} decimals", x, num);
}

