fn three_3s(items: &[i32]) -> bool {
    let mut threes = 0;
    for &item in items {
        if item == 3 {
            if threes < 3 {
                threes += 1;
            } else {
                return false;
            }
        } else if threes != 0 && threes != 3 {
            return false;
        }
    }
    true
}

fn print_list(items: &[i32]) {
    for &item in items {
        print!("{} ", item);
    }
}

fn main() {
    let lists = [
        [9, 3, 3, 3, 2, 1, 7, 8, 5],
        [5, 2, 9, 3, 3, 6, 8, 4, 1],
        [1, 4, 3, 6, 7, 3, 8, 3, 2],
        [1, 2, 3, 4, 5, 6, 7, 8, 9],
        [4, 6, 8, 7, 2, 3, 3, 3, 1],
    ];

    for list in &lists {
        print_list(list);
        println!("-> {}", if three_3s(list) { "true" } else { "false" });
    }
}

