use std::collections::HashSet;

fn sieve(limit: usize) -> Vec<bool> {
    let mut c = vec![false; limit + 1];
    c[0] = true;
    c[1] = true;
    for i in (4..=limit).step_by(2) {
        c[i] = true;
    }
    let mut p = 3;
    while p * p <= limit {
        let p2 = p * p;
        for i in (p2..=limit).step_by(2 * p) {
            c[i] = true;
        }
        p += 2;
        while c[p] {
            p += 2;
        }
    }
    c
}

struct Digits {
    digs: [u8; 20],
    count: usize,
}

fn get_digits(mut n: u32) -> Digits {
    if n == 0 {
        return Digits { digs: [0; 20], count: 1 };
    }
    let mut d = Digits { digs: [0; 20], count: 0 };
    while n > 0 {
        d.digs[d.count] = (n % 10) as u8;
        n /= 10;
        d.count += 1;
    }
    d
}

#[derive(Debug)]
struct Pair {
    x: u32,
    y: u32,
}

fn main() {
    const LIMIT: usize = 1_000_000_000;
    let c = sieve(LIMIT);
    let primes: Vec<u32> = c.iter().enumerate()
        .filter_map(|(i, &is_not_prime)| if !is_not_prime { Some(i as u32) } else { None })
        .collect();
    let mut orm30 = Vec::with_capacity(30);
    let mut counts = [0; 5];
    let mut count = 0;
    let mut count2 = 0;
    let mut j = 100_000;
    for window in primes.windows(2) {
        let (p1, p2) = (window[0], window[1]);
        if (p2 - p1) % 18 != 0 {
            continue;
        }
        let key1 = get_key(p1, &primes);
        let key2 = get_key(p2, &primes);
        if key1 == key2 {
            if count < 30 {
                orm30.push(Pair { x: p1, y: p2 });
            }
            if p1 >= j as u32 {
                counts[count2] = count;
                count2 += 1;
                j *= 10;
            }
            count += 1;
        }
    }
    counts[count2] = count;
    println!("First 30 Ormiston pairs:");
    for (i, pair) in orm30.iter().enumerate() {
        print!("[{:6}, {:6}] ", pair.x, pair.y);
        if (i + 1) % 3 == 0 {
            println!();
        }
    }
    println!();
    j = 100_000;
    for (i, &cnt) in counts.iter().enumerate() {
        println!("{} Ormiston pairs before {}", cnt, j);
        j *= 10;
    }
}

fn get_key(n: u32, primes: &[u32]) -> u64 {
    let d = get_digits(n);
    let mut key = 1_u64;
    for &digit in &d.digs[..d.count] {
        key *= primes[digit as usize] as u64;
    }
    key
}

