    let mut buf = [0u8; 256];
    let mut len = 0;
    let mut repeat = false;
    let mut end = false;

    while !end {
        match in_stream.get() {
            Some(c) => {
                buf[len] = c;
                len += 1;
                end = false;
            }
            None => end = true,
        }

        if repeat {
            if buf[len - 1] != buf[len - 2] {
                repeat = false;
