                    buf[0] = buf[1];
                    buf[1] = buf[len - 1];
                    len = 2;
                }
                continue;
            }
            if len == 128 || end {
                output(out_stream, &buf, len)?;
                len = 0;
                repeat = false;
            }
        }
    }
    out_stream.put(0)?;
    Ok(())
}

