use std::io::{self, Read};

fn get_line<R: Read>(reader: &mut R) -> Option<String> {
    let mut buf = Vec::new();
    let mut handle = reader.bytes();

    while let Some(Ok(byte)) = handle.next() {
        buf.push(byte);
        if byte == b'\n' {
            break;
        }
    }

    if buf.is_empty() {
        None
    } else {
        buf.push(b'\0');
        String::from_utf8_lossy(&buf[..buf.len() - 1]).into_owned().into()
    }
}

fn main() {
    let stdin = io::stdin();
    let mut handle = stdin.lock();

    while let Some(line) = get_line(&mut handle) {
        println!("{}", line);
    }
}

