        (8, 14, true), (8, 15, true), (8, 17, true)
    ];

    fn print_remaining(dates: &[(i32, i32, bool)]) {
        let count = dates.iter().filter(|&&(_, _, active)| active).count();
        println!("{} remaining.", count);
    }

    fn print_answer(dates: &[(i32, i32, bool)], months: &[&str]) {
        for &(month, day, active) in dates {
            if active {
                println!("{}, {}", months[month as usize], day);
            }
        }
    }

    fn first_pass(dates: &mut [(i32, i32, bool)]) {
        for i in 0..dates.len() {
            let count = dates.iter().filter(|&&(d, _, _)| d == dates[i].1).count();
            if count == 1 {
                for j in 0..dates.len() {
                    if !dates[j].2 {
                        continue;
                    }
                    if dates[j].0 == dates[i].0 {
                        dates[j].2 = false;
                    }
                }
            }
        }
    }

    fn second_pass(dates: &mut [(i32, i32, bool)]) {
        for i in 0..dates.len() {
            if !dates[i].2 {
                continue;
            }
            let count = dates.iter().filter(|&&(_, d, _)| d == dates[i].1 && dates[i].2).count();
            if count > 1 {
                for j in 0..dates.len() {
                    if !dates[j].2 {
                        continue;
                    }
                    if dates[j].1 == dates[i].1 {
                        dates[j].2 = false;
                    }
                }
            }
        }
    }

    fn third_pass(dates: &mut [(i32, i32, bool)]) {
        for i in 0..dates.len() {
            if !dates[i].2 {
                continue;
            }
            let count = dates.iter().filter(|&&(_, _, a)| a && dates[i].0 == dates[i].0).count();
            if count > 1 {
                for j in 0..dates.len() {
                    if !dates[j].2 {
                        continue;
                    }
                    if dates[j].0 == dates[i].0 {
                        dates[j].2 = false;
                    }
                }
            }
        }
    }

    print_remaining(&dates);

    first_pass(&mut dates);

    print_remaining(&dates);

    second_pass(&mut dates);

    print_remaining(&dates);

    third_pass(&mut dates);

    print_answer(&dates, &months);
}

