                if d > 0 {
                    iter_string("XHXVX", d - 1, x, y, dx, dy, scale, clen, cscale, pix);
                } else {
                    *clen += 1;
                    h_rgb(pix, *x, *y, scale, *clen, cscale);
                    *x += dx;
                    *y -= dy;
                }
            }
            'V' => {
                let len = 1 << d;
                for _ in 0..len {
                    *clen += 1;
                    h_rgb(pix, *x, *y, scale, *clen, cscale);
                    *y += dy;
                }
            }
            'H' => {
                let len = 1 << d;
                for _ in 0..len {
                    *clen += 1;
                    h_rgb(pix, *x, *y, scale, *clen, cscale);
                    *x -= dx;
                }
            }
            _ => {}
        }
    }
}

fn sierp(leng: i64, depth: i32) {
