    let mut x = 10;
    let mut y = 10;
    let dx = leng;
    let dy = leng;
    let mut scale = 1;
    let mut clen = 0;
    let mut cscale = 3;

    for _ in 0..depth {
        sc_up(&mut scale, &mut x, &mut y, &mut cscale);
