fn twice(x: i32) -> i32 {
    2 * x
}

fn main() {
    println!("This will demonstrate function and label scopes.");
    println!("All output is happening through println!(), a macro provided by Rust.");
    println!("Enter a number: ");

    let mut input = String::new();
    io::stdout().flush().unwrap();
    if io::stdin().read_line(&mut input).is_err() {
        return;
    }

    let x: i32 = match input.trim().parse() {
        Ok(num) => num,
        Err(_) => return,
    };

    match x % 2 {
        _ => println!("Case labels in match statements do not have scope like in C."),
        0 => {
            println!("You entered an even number.");
            println!("Its square is {}, which was computed by a function.", sqr(x));
        }
        1 => {
            println!("You entered an odd number.");
            greet();
            if x == -1 {
                scram();
            } else {
                jump_in(x);
            }
        }
        _ => unreachable!(),
    }

    println!("We now come to control flow, it's powerful but can be misused.");

    if x != -1 {
        jump_in(-1);
    }
}

fn sqr(x: i32) -> i32 {
    x * x
}

fn greet() {
    println!("Hello There!");
}

fn jump_in(x: i32) {
    println!("2 times {} is {}, which was computed by a function defined in this file.", x, twice(x));
    println!("Since you jumped in, you will now be greeted, again!");
    greet();
    if x == -1 {
        scram();
    }
}

fn scram() {
    println!("If you are trying to figure out what happened, you now understand control flow.");
}

