#[derive(Debug)]
enum Type {
    Int,
    String,
}

#[derive(Debug)]
struct Maybe {
    i: i32,
    s: Option<String>,
    t: Type,
    is_something: bool,
}

impl Maybe {
    fn print(&self) {
        match self.t {
            Type::Int => println!("Just {} : INT", self.i),
            Type::String => {
                if let Some(ref s) = self.s {
                    println!("Just \"{}\" : STRING", s);
                } else {
                    println!("Nothing");
                }
            }
            _ => println!("Nothing"),
        }
    }
}

fn return_maybe(data: &dyn std::any::Any, t: Type) -> Maybe {
    match t {
        Type::Int => {
            if let Some(&value) = data.downcast_ref::<i32>() {
                Maybe {
                    i: value,
                    s: None,
                    t: Type::Int,
                    is_something: true,
                }
            } else {
                Maybe {
                    i: 0,
                    s: None,
                    t: Type::Int,
                    is_something: false,
                }
            }
        }
        Type::String => {
            if let Some(value) = data.downcast_ref::<&str>() {
                Maybe {
                    i: 0,
                    s: Some(value.to_string()),
                    t: Type::String,
                    is_something: true,
                }
            } else {
                Maybe {
                    i: 0,
                    s: None,
                    t: Type::String,
                    is_something: false,
                }
            }
        }
        _ => Maybe {
            i: 0,
            s: None,
            t: Type::Int,
            is_something: false,
        },
    }
}

fn bind_maybe<F>(m: &Maybe, f: F) -> Maybe
where
    F: FnOnce(&i32) -> Maybe,
{
    if m.is_something {
        f(&m.i)
    } else {
        Maybe {
            i: 0,
            s: None,
            t: Type::Int,
            is_something: false,
        }
    }
}

fn f_1(v: &i32) -> Maybe {
    Maybe {
        i: v * v,
        s: None,
        t: Type::Int,
        is_something: true,
    }
}

fn f_2(v: &i32) -> Maybe {
    let mut s = String::new();
    s.extend(std::iter::repeat('x').take(*v as usize));
    Maybe {
        i: 0,
        s: Some(s),
        t: Type::String,
        is_something: true,
    }
}

fn main() {
    let i = 7;
    let s = "lorem ipsum dolor sit amet";

    let m_1 = return_maybe(&i, Type::Int);
    let m_2 = return_maybe(&s, Type::String);

    m_1.print();
    m_2.print();

    bind_maybe(&m_1, f_1).print();
    bind_maybe(&m_1, f_2).print();

    bind_maybe(&bind_maybe(&m_1, f_1), f_2).print();
}

