fn gcd(mut a: i32, mut b: i32) -> i32 {
    while b != 0 {
        let c = a;
        a = b;
        b = c % b;
    }
    a
}

#[derive(Debug)]
struct Pair {
    x: i32,
    y: i32,
}

impl Pair {
    fn print(&self) {
        println!("{{{},{}}}", self.x, self.y);
    }
}

fn main() {
    let pairs = vec![
        Pair { x: 21, y: 15 },
        Pair { x: 17, y: 23 },
        Pair { x: 36, y: 12 },
        Pair { x: 18, y: 29 },
        Pair { x: 60, y: 15 },
    ];

    for pair in &pairs {
        if gcd(pair.x, pair.y) == 1 {
            pair.print();
        }
    }
}

