fn num_prime_factors(mut x: u32) -> usize {
    let mut p = 2;
    let mut pf = 0;
    if x == 1 {
        return 1;
    } else {
        loop {
            if x % p == 0 {
                pf += 1;
                x /= p;
                if x == 1 {
                    return pf;
                }
            } else {
                p += 1;
            }
        }
    }
}

fn prime_factors(mut x: u32, arr: &mut [u32]) {
    let mut p = 2;
    let mut pf = 0;
    if x == 1 {
        arr[pf] = 1;
    } else {
        loop {
            if x % p == 0 {
                arr[pf] = p;
                pf += 1;
                x /= p;
                if x == 1 {
                    return;
                }
            } else {
                p += 1;
            }
        }
    }
}

fn sum_digits(mut x: u32) -> u32 {
    let mut sum = 0;
    while x > 0 {
        sum += x % 10;
        x /= 10;
    }
    sum
}

fn sum_factors(arr: &[u32]) -> u32 {
    arr.iter().map(|&x| sum_digits(x)).sum()
}

fn list_all_smith_numbers(limit: u32) {
    for a in 4..limit {
        let numfactors = num_prime_factors(a);
        if numfactors < 2 {
            continue;
        }
        let mut factors = vec![0; numfactors];
        prime_factors(a, &mut factors);
        if sum_digits(a) == sum_factors(&factors) {
            print!("{:4} ", a);
        }
    }
}

fn main() {
    println!("All the Smith Numbers < 10000 are:");
    list_all_smith_numbers(10000);
}

