use std::io::{self, Write};

fn leonardo(a: i32, b: i32, step: i32, num: usize) {
    print!("First 25 Leonardo numbers: ");
    let mut a = a;
    let mut b = b;

    for i in 1..=num {
        match i {
            1 => print!(" {}", a),
            2 => print!(" {}", b),
            _ => {
                let next = a + b + step;
                print!(" {}", next);
                a = b;
                b = next;
            }
        }
    }
    println!();
}

fn main() {
    let mut input = String::new();
    print!("Enter first two Leonardo numbers and increment step: ");
    io::stdout().flush().unwrap();
    io::stdin().read_line(&mut input).expect("Failed to read line");

    let parts: Vec<&str> = input.trim().split_whitespace().collect();
    let a: i32 = parts[0].parse().expect("Please type a number!");
    let b: i32 = parts[1].parse().expect("Please type a number!");
    let step: i32 = parts[2].parse().expect("Please type a number!");

    leonardo(a, b, step, 25);
}

