fn count_divisors(n: u32) -> u32 {
    let mut count = 0;
    let limit = (n as f64).sqrt() as u32 + 1;
    for i in 1..limit {
        if n % i == 0 {
            if i == n / i {
                count += 1;
            } else {
                count += 2;
            }
        }
    }
    count
}

fn main() {
    const MAX: u32 = 15;
    let mut next = 1;
    println!("The first {} terms of the sequence are:", MAX);
    for i in 1.. {
        if next > MAX {
            break;
        }
        if next == count_divisors(i) {
            print!("{} ", i);
            next += 1;
        }
    }
    println!();
}

