fn pascal(a: i32, b: i32, mid: i32, top: i32) -> Option<(i32, i32, i32)> {
    let ytemp = (top - 4 * (a + b)) as f64 / 7.0;
    if ytemp.fract() >= 0.0001 {
        return None;
    }
    let y = ytemp as i32;
    let x = mid - 2 * a - y;
    let z = y - x;
    Some((x, y, z))
}

fn main() {
    let a = 11;
    let b = 4;
    let mid = 40;
    let top = 151;

    match pascal(a, b, mid, top) {
        Some((x, y, z)) => println!("x: {}, y: {}, z: {}", x, y, z),
        None => println!("No solution"),
    }
}

