fn modpow(mut b: u32, mut e: u32, m: u32) -> u32 {
    let mut p = 1;
    while e > 0 {
        if e & 1 != 0 {
            p = p * b % m;
        }
        b = b * b % m;
        e >>= 1;
    }
    p
}

fn is_deceptive(n: u32) -> bool {
    if n & 1 != 0 && n % 3 != 0 && n % 5 != 0 {
        for x in (7..).step_by(6).take_while(|&x| x * x <= n) {
            if n % x == 0 || n % (x + 4) == 0 {
                return modpow(10, n - 1, n) == 1;
            }
        }
    }
    false
}

fn main() {
    let mut count = 0;
    let mut i = 49;
    while count != 50 {
        if is_deceptive(i) {
            print!(" {}", i);
            count += 1;
        }
        i += 1;
    }
}

