fn reduce<F>(fn_: F, elms: &[i32]) -> i32
where
    F: Fn(i32, i32) -> i32,
{
    let mut val = elms[0];
    for &elm in &elms[1..] {
        val = fn_(val, elm);
    }
    val
}

fn add(a: i32, b: i32) -> i32 { a + b }
