fn mul(a: i32, b: i32) -> i32 { a * b }

fn main() {
    let nums = [1, 2, 3, 4, 5];
    println!("{}", reduce(add, &nums));
    println!("{}", reduce(sub, &nums));
    println!("{}", reduce(mul, &nums));
}

