use std::cmp::Reverse;

fn compare_and_report_strings_length(strings: &[&str]) {
    if !strings.is_empty() {
        let mut si: Vec<(usize, usize)> = strings.iter().enumerate().map(|(i, s)| (s.len(), i)).collect();

        si.sort_by_key(|&(len, _)| Reverse(len));

        let max_len = si[0].0;
        let min_len = si.last().unwrap().0;

        for &(length, index) in &si {
            let string = strings[index];
            let predicate = match length {
                len if len == max_len => "and is the longest string",
                len if len == min_len => "and is the shortest string",
                _ => "and is neither the longest nor the shortest string",
            };
            println!("\"{}\" has length {} {}", string, length, predicate);
        }
    }
}

fn main() {
    let list = ["abcd", "123456789", "abcdef", "1234567"];
    compare_and_report_strings_length(&list);
}

