    let mut a = [[2; 17]; 17];
    let mut idx = [0; 4];
    let mark = ['0', '1', '-'];

    for k in (1..=8).step_by(8) {
        for i in 0..17 {
            let j = (i + k) % 17;
            a[i][j] = 1;
            a[j][i] = 1;
        }
    }

    for row in &a {
        for &val in row {
            print!("{} ", mark[val as usize]);
        }
        println!();
    }

    for i in 0..17 {
        idx[0] = i;
        if find_group(&a, &mut idx, 1, i + 1, 17, 1) || find_group(&a, &mut idx, 0, i + 1, 17, 1) {
            println!("no good");
            return;
        }
    }
    println!("all good");
}

