4a655fa062bee7e4c181ea037ee9d9b6.c_code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void wordle(const char *answer, const char *guess, int *result) {
    int i, ix, n = strlen(guess);
    char *ptr;
    if (n != strlen(answer)) {
        printf("The words must be of the same length.\n");
        exit(1);
    }
    char answer2[n+1];
    strcpy(answer2, answer);
    for (i = 0; i < n; ++i) {
        if (guess[i] == answer2[i]) {
            answer2[i] = '\v';
            result[i] = 2;
        }
    }
    for (i = 0; i < n; ++i) {
        if ((ptr = strchr(answer2, guess[i])) != NULL) {
            ix = ptr - answer2;
            answer2[ix] = '\v';
            result[i] = 1;
        }
    }
}

int main() {
    int i, j;
    const char *answer, *guess;
    int res[5];
    const char *res2[5];
    const char *colors[3] = {"grey", "yellow", "green"};
    const char *pairs[5][2] = {
        {"ALLOW", "LOLLY"},
        {"BULLY", "LOLLY"},
        {"ROBIN", "ALERT"},
        {"ROBIN", "SONIC"},
        {"ROBIN", "ROBIN"}
    };
    for (i = 0; i < 5; ++i) {
        answer = pairs[i][0];
        guess  = pairs[i][1];
        for (j = 0; j < 5; ++j) res[j] = 0;
        wordle(answer, guess, res);
        for (j = 0; j < 5; ++j) res2[j] = colors[res[j]];
        printf("%s v %s => { ", answer, guess);
        for (j = 0; j < 5; ++j) printf("%d ", res[j]);
        printf("} => { ");
        for (j = 0; j < 5; ++j) printf("%s ", res2[j]);
        printf("}\n");
    }
    return 0;
}

4a655fa062bee7e4c181ea037ee9d9b6.rust_code:
use std::collections::HashMap;

fn wordle(answer: &str, guess: &str) -> Result<Vec<i32>, &'static str> {
    if answer.len() != guess.len() {
        return Err("The words must be of the same length.");
    }

    let mut result = vec![0; answer.len()];
    let mut answer_chars: Vec<char> = answer.chars().collect();

    for (i, (a, g)) in answer_chars.iter_mut().zip(guess.chars()).enumerate() {
        if a == &g {
            *a = '\x0b'; // ASCII vertical tab, similar to '\v'
            result[i] = 2;
        }
    }

    let mut char_count: HashMap<char, usize> = HashMap::new();
    for c in answer_chars.iter().cloned().filter(|&c| c != '\x0b') {
        *char_count.entry(c).or_insert(0) += 1;
    }

    for (i, g) in guess.chars().enumerate() {
        if result[i] == 0 && char_count.get(&g).copied().unwrap_or(0) > 0 {
            *char_count.get_mut(&g).unwrap() -= 1;
            result[i] = 1;
        }
    }

    Ok(result)
}

fn main() {
    let colors = ["grey", "yellow", "green"];
    let pairs = [
        ("ALLOW", "LOLLY"),
        ("BULLY", "LOLLY"),
        ("ROBIN", "ALERT"),
        ("ROBIN", "SONIC"),
        ("ROBIN", "ROBIN"),
    ];

    for (answer, guess) in pairs {
        match wordle(answer, guess) {
            Ok(res) => {
                let res2: Vec<&str> = res.iter().map(|&r| colors[r as usize]).collect();
                println!("{} v {} => {:?} => {:?}", answer, guess, res, res2);
            }
            Err(e) => println!("Error: {}", e),
