fn wordle(answer: &str, guess: &str) -> Result<Vec<i32>, &'static str> {
    if answer.len() != guess.len() {
        return Err("The words must be of the same length.");
    }

    let mut result = vec![0; answer.len()];
    let mut answer_chars: Vec<char> = answer.chars().collect();

    for (i, (a, g)) in answer_chars.iter_mut().zip(guess.chars()).enumerate() {
        if a == &g {
            *a = '\x0b'; // ASCII vertical tab, similar to '\v'
            result[i] = 2;
        }
    }

    let mut char_count: HashMap<char, usize> = HashMap::new();
    for c in answer_chars.iter().cloned().filter(|&c| c != '\x0b') {
        *char_count.entry(c).or_insert(0) += 1;
    }

    for (i, g) in guess.chars().enumerate() {
        if result[i] == 0 && char_count.get(&g).copied().unwrap_or(0) > 0 {
            *char_count.get_mut(&g).unwrap() -= 1;
            result[i] = 1;
        }
    }

    Ok(result)
}

fn main() {
    let colors = ["grey", "yellow", "green"];
    let pairs = [
        ("ALLOW", "LOLLY"),
        ("BULLY", "LOLLY"),
        ("ROBIN", "ALERT"),
        ("ROBIN", "SONIC"),
        ("ROBIN", "ROBIN"),
    ];

    for (answer, guess) in pairs {
        match wordle(answer, guess) {
            Ok(res) => {
                let res2: Vec<&str> = res.iter().map(|&r| colors[r as usize]).collect();
                println!("{} v {} => {:?} => {:?}", answer, guess, res, res2);
            }
            Err(e) => println!("Error: {}", e),
        }
    }
}

