fn is_prime(p: u32) -> bool {
    if p == 2 {
        return true;
    }
    if p % 2 == 0 {
        return false;
    }
    (3..=((p as f64).sqrt() as u32))
        .step_by(2)
        .all(|i| p % i != 0)
}

fn prime(n: u32) -> u32 {
    if n == 1 {
        return 2;
    }
    let mut p = 3;
    let mut pn = 1;
    while pn < n {
        if is_prime(p) {
            pn += 1;
        }
        p += 2;
    }
    p - 2
}

fn main() {
    println!("{}", prime(10001));
}

