use std::fmt::Write;

fn is_prime(n: u64) -> bool {
    if n < 2 {
        return false;
    }
    if n % 2 == 0 {
        return n == 2;
    }
    if n % 3 == 0 {
        return n == 3;
    }
    let mut d = 5;
    while d * d <= n {
        if n % d == 0 {
            return false;
        }
        d += 2;
        if n % d == 0 {
            return false;
        }
        d += 4;
    }
    true
}

fn ord(n: i32) -> String {
    let m = n % 100;
    let suffix = match m {
        4..=20 => "th",
        _ => match m % 10 {
            1 => "st",
            2 => "nd",
            3 => "rd",
            _ => "th",
        },
    };
    format!("{}{}", n, suffix)
}

fn is_magnanimous(n: u64) -> bool {
    if n < 10 {
        return true;
    }
    let mut p = 10;
    loop {
        let q = n / p;
        let r = n % p;
        if !is_prime(q + r) {
            return false;
        }
        if q < 10 {
            break;
        }
        p *= 10;
    }
    true
}

fn list_mags(from: i32, thru: i32, digs: usize, per_line: i32) {
    let mut i = 0;
    let mut c = 0;
    if from < 2 {
        println!("\nFirst {} magnanimous numbers:", thru);
