    }
    while c < thru {
        if is_magnanimous(i as u64) {
            if c + 1 >= from {
                print!("{:width$} ", i, width = digs);
                c += 1;
                if c % per_line == 0 {
                    println!();
                }
            }
        }
        i += 1;
    }
}

