#include <stdio.h>


void lshift(int *l, size_t n) {
    int i, f;
    if (n < 2) return;
    f = l[0];
    for (i = 0; i < n-1; ++i) l[i] = l[i+1];
    l[n-1] = f;
}

int main() {
    int l[] = {1, 2, 3, 4, 5, 6, 7, 8, 9};
    int i;
    size_t n = 9;
    printf("Original list     : ");
    for (i = 0; i < n; ++i) printf("%d ", l[i]);
    printf("\nShifted left by 3 : ");
    for (i = 0; i < 3; ++i) lshift(l, n);
    for (i = 0; i < n; ++i) printf("%d ", l[i]);
    printf("\n");
    return 0;
}

d6b2e66b2b681b701b15e9b3aea60bf1.rust_code:
fn lshift(l: &mut [i32]) {
    if l.len() < 2 {
        return;
    }
    let first = l[0];
    l.copy_within(1.., 0);
    l[l.len() - 1] = first;
}

fn main() {
    let mut l = vec![1, 2, 3, 4, 5, 6, 7, 8, 9];
    println!("Original list     : {}", l.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(" "));
    println!("Shifted left by 3 : {}", {
        for _ in 0..3 {
            lshift(&mut l);
        }
        l.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(" ")
    });
}

