fn reverse(mut n: i32) -> i32 {
    let mut result = 0;
    while n > 0 {
        result = 10 * result + n % 10;
        n /= 10;
    }
    result
}

fn main() {
    const LIMIT1: i32 = 200;

    let mut row = 0;
    let mut num = 0;

    for n in 1..LIMIT1 {
        let mut flag = true;
        let rev_num = reverse(n);

        for m in 1..n / 2 {
            let rev_div = reverse(m);
            if n % m == 0 {
                if rev_num % rev_div != 0 {
                    flag = false;
                    break;
                }
            }
        }

        if flag {
            num += 1;
            row += 1;
            print!("{:4} ", n);
            if row % 10 == 0 {
                println!();
            }
        }
    }

    println!("\n\nFound {} special divisors N that reverse(D) divides reverse(N) for all divisors D of N, where N < {}", num, LIMIT1);
}

