    for i in 0..n {
        for j in 0..n {
            mat[i][j] = if i < j {
                0
            } else if i == j || j == 0 {
                1
            } else {
                mat[i - 1][j - 1] + mat[i - 1][j]
            };
        }
    }
}

fn pascal_upp(mat: &mut Vec<Vec<i32>>, n: usize) {
    for i in 0..n {
        for j in 0..n {
            mat[i][j] = if i > j {
