            } else if i == j || i == 0 {
                1
            } else {
                mat[i - 1][j - 1] + mat[i][j - 1]
            };
        }
    }
}

fn pascal_sym(mat: &mut Vec<Vec<i32>>, n: usize) {
    for i in 0..n {
        for j in 0..n {
