use std::env;
use std::process;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} number1 number2 ...", args[0]);
        process::exit(1);
    }

    let mut count = 0;
    let mut sum = 0.0;
    let mut prod = 1.0;
    let mut resum = 0.0;

    for arg in &args[1..] {
        match arg.parse::<f64>() {
            Ok(f) => {
                count += 1;
                sum += f;
                prod *= f;
                resum += 1.0 / f;
            }
            Err(_) => {
                eprintln!("Please provide valid numbers");
                process::exit(1);
            }
        }
    }

    println!("Arithmetic mean = {}", sum / count as f64);
    println!("Geometric mean = {}", prod.powf(1.0 / count as f64));
    println!("Harmonic mean = {}", count as f64 / resum);
}

