    let mut r = m;
    for i in 1..k {
        r = r * (m + i) / (i + 1);
    }
    r
}

fn tree(br: XInt, n: XInt, cnt: XInt, sum: XInt, l: XInt, rooted: &mut [XInt], unrooted: &mut [XInt]) {
    for b in (br + 1)..=BRANCH as XInt {
        let s = sum + (b - br) * n;
        if s >= MAX_N as XInt {
            return;
        }

        let c = choose(rooted[n as usize], b - br) * cnt;

        if l * 2 < s {
            unrooted[s as usize] += c;
        }

        if b == BRANCH as XInt {
            return;
        }
        rooted[s as usize] += c;

        for m in (1..n).rev() {
            tree(b, m, c, s, l, rooted, unrooted);
        }
    }
}

