use std::env;
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::process;

const INOUT_LEN: usize = 4;
const TIME_LEN: usize = 20;
const MAX_MAXOUT: usize = 1000;

fn main() {
    let args: Vec<String> = env::args().collect();
    let input: Box<dyn BufRead> = if args.len() > 1 {
        let file = File::open(&args[1]).unwrap_or_else(|_| {
            eprintln!("cannot read {}", args[1]);
            process::exit(1);
        });
        Box::new(BufReader::new(file))
    } else {
        Box::new(BufReader::new(io::stdin()))
    };

    let mut inout = String::with_capacity(INOUT_LEN);
    let mut time = String::with_capacity(TIME_LEN);
    let mut jobnum: u32 = 0;
    let mut maxtime = vec![String::with_capacity(TIME_LEN); MAX_MAXOUT];
    let mut l_out = 0;
    let mut maxout = -1;
    let mut maxcount = 0;

    for line in input.lines() {
        let line = line.unwrap_or_else(|_| {
            eprintln!("error reading line");
            process::exit(1);
        });
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() == 5 && parts[0] == "License" && parts[2] == "@" && parts[4].starts_with("job") {
            inout.clear();
            inout.push_str(parts[1]);
            time.clear();
            time.push_str(parts[3]);
            jobnum = parts[4][3..].parse().unwrap_or_else(|_| {
                eprintln!("invalid job number");
                process::exit(1);
            });

            if inout == "OUT" {
                l_out += 1;
            } else {
                l_out -= 1;
            }

            if l_out > maxout {
                maxout = l_out;
                maxcount = 0;
            }
            if l_out == maxout {
                if maxcount < MAX_MAXOUT {
                    maxtime[maxcount].clear();
                    maxtime[maxcount].push_str(&time);
                    maxcount += 1;
                } else {
                    eprintln!("increase MAX_MAXOUT (now it is {})", MAX_MAXOUT);
                    process::exit(1);
                }
            }
        }
    }

    println!("Maximum simultaneous license use is {} at the following times:", maxout);
    for i in 0..maxcount {
        println!("{}", maxtime[i]);
    }
}

