use std::process;

const MAX_N: usize = 64;

fn coef(c: &mut [i64], n: usize) {
    if n >= MAX_N {
        process::abort();
    }

    c[0] = 1;
    for i in 0..n {
        c[0] = -c[0];
        c[i + 1] = 1;
        for j in (1..=i).rev() {
            c[j] = c[j - 1] - c[j];
        }
    }
}

fn is_prime(n: usize) -> bool {
    let mut c = vec![0; MAX_N];
    coef(&mut c, n);
    c[0] += 1;
    c[n] -= 1;
    c.iter().take(n + 1).all(|&x| x % n as i64 == 0)
}

fn show(c: &[i64], n: usize) {
    for i in (0..=n).rev() {
        print!("{:+}x^{}", c[i], i);
    }
}

fn main() {
    for n in 0..10 {
        let mut c = vec![0; MAX_N];
        coef(&mut c, n);
        print!("(x-1)^{} = ", n);
        show(&c, n);
        println!();
    }

    print!("\nprimes (never mind the 1):");
    for n in 1..=63 {
        if is_prime(n) {
            print!(" {}", n);
        }
    }
    println!();
}

