        .rev()
        .find(|&k| nums[k] < nums[k + 1])
    {
        let l = (k + 1..nums.len())
            .rev()
            .find(|&l| nums[l] > nums[k])
            .unwrap();
        nums.swap(k, l);
        nums[k + 1..].reverse();
        true
    } else {
