fn max(a: &[i32], n: usize, i: usize, j: usize, k: usize) -> usize {
    let mut m = i;
    if j < n && a[j] > a[m] {
        m = j;
    }
    if k < n && a[k] > a[m] {
        m = k;
    }
    m
}

fn downheap(a: &mut [i32], n: usize, mut i: usize) {
    while let Some(j) = (0..n).find(|&j| j == max(a, n, i, 2 * i + 1, 2 * i + 2)) {
        if j == i {
            break;
        }
        a.swap(i, j);
        i = j;
    }
}

fn heapsort(a: &mut [i32]) {
    let n = a.len();
    for i in (0..(n - 1) / 2).rev() {
        downheap(a, n, i);
    }
    for i in 0..n {
        a.swap(n - i - 1, 0);
        downheap(a, n - i - 1, 0);
    }
}

