    let mut a = vec![4, 65, 2, -31, 0, 99, 2, 83, 782, 1];
    println!("{}", a.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(" "));
    heapsort(&mut a);
    println!("{}", a.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(" "));
}

