fn ipow(base: i32, exp: i32) -> i32 {
    if exp < 0 {
        assert_ne!(base, 0);
        return if base * base != 1 { 0 } else { if exp & 1 == 1 { base } else { 1 } };
    }

    let mut pow = base;
    let mut v = 1;
    let mut e = exp;

    while e > 0 {
        if e & 1 == 1 {
            v *= pow;
        }
        pow *= pow;
        e >>= 1;
    }
    v
}

fn dpow(base: f64, exp: i32) -> f64 {
    let mut v = 1.0;
    let mut pow = if exp < 0 { 1.0 / base } else { base };
    let mut e = exp.abs();

    while e > 0 {
        if e & 1 == 1 {
            v *= pow;
        }
        pow *= pow;
        e >>= 1;
    }
    v
}

fn main() {
    println!("2^6 = {}", ipow(2, 6));
    println!("2^-6 = {}", ipow(2, -6));
    println!("2.71^6 = {}", dpow(2.71, 6));
    println!("2.71^-6 = {}", dpow(2.71, -6));
}

