use std::str::FromStr;

fn number_of_digits(mut x: i32) -> usize {
    let mut number_of_digits = 0;
    while x != 0 {
        x /= 10;
        number_of_digits += 1;
    }
    number_of_digits
}

fn convert_array(array: &str) -> Vec<i32> {
    let mut converted_array = Vec::new();
    let mut original_element = 0;

    while original_element < array.len() {
        let digit_count = array[original_element..]
            .chars()
            .take_while(|c| c.is_digit(10))
            .count();
        let element_str = &array[original_element..original_element + digit_count];
        if let Ok(converted_element) = i32::from_str(element_str) {
            converted_array.push(converted_element);
        }
        original_element += digit_count + 1;
    }

    converted_array
}

fn is_sorted(array: &[i32]) -> bool {
    array.windows(2).all(|w| w[0] <= w[1])
}

fn main() {
    if let Some(input) = std::env::args().nth(1) {
        let converted_array = convert_array(&input);

        if is_sorted(&converted_array) {
            println!("Did you forgot to turn on your brain?! This array is already sorted!");
        } else if converted_array.len() <= 10 {
            println!("Am I really supposed to sort this? Sort it by yourself!");
        } else {
            println!("Am I really supposed to sort this? Bhahahaha!");
        }
    }
}

