fn is_prime(p: u32) -> bool {
    if p == 2 {
        return true;
    }
    if p % 2 == 0 {
        return false;
    }
    (3..=((p as f64).sqrt() as u32)).step_by(2).all(|i| p % i != 0)
}

fn next_prime(mut p: u32) -> u32 {
    if p == 0 {
        return 2;
    }
    if p < 3 {
        return p + 1;
    }
    loop {
        p += 1;
        if is_prime(p) {
            return p;
        }
    }
}

fn main() {
    let mut i = 3;
    let mut j = 5;
    let mut champ = 3;
    let mut champj = 5;
    let mut record = 2;

    while j <= 1_000_000 {
        i = j;
        j = next_prime(i);
        if j - i > record {
            champ = i;
            champj = j;
            record = j - i;
        }
    }

    println!("The largest difference was {}, between {} and {}.", record, champ, champj);
}

