#include<stdarg.h>
#include<stdio.h>

long int factorial(int n){
	if(n>1)
		return n*factorial(n-1);
	return 1;
}

long int sumOfFactorials(int num,...){
	va_list vaList;
	long int sum = 0;

	va_start(vaList,num);

	while(num--)
		sum += factorial(va_arg(vaList,int));

	va_end(vaList);

	return sum;
}

int main()
{
	printf("\nSum of factorials of [1,5] : %ld",sumOfFactorials(5,1,2,3,4,5));
	printf("\nSum of factorials of [3,5] : %ld",sumOfFactorials(3,3,4,5));
	printf("\nSum of factorials of [1,3] : %ld",sumOfFactorials(3,1,2,3));

	return 0;
}

6642b78d4c79ec261bdbb2cb4732cfeb.rust_code:
fn factorial(n: u32) -> u64 {
    match n {
        0 | 1 => 1,
        _ => n as u64 * factorial(n - 1),
    }
}

fn sum_of_factorials(numbers: &[u32]) -> u64 {
    numbers.iter().map(|&num| factorial(num)).sum()
}

fn main() {
    let numbers1 = [1, 2, 3, 4, 5];
    let numbers2 = [3, 4, 5];
    let numbers3 = [1, 2, 3];

    println!("\nSum of factorials of {:?} : {}", numbers1, sum_of_factorials(&numbers1));
    println!("\nSum of factorials of {:?} : {}", numbers2, sum_of_factorials(&numbers2));
    println!("\nSum of factorials of {:?} : {}", numbers3, sum_of_factorials(&numbers3));
}

