use std::fmt::Write;

fn find_group(a: &[[i32; 17]; 17], idx: &mut [usize; 4], type_: i32, min_n: usize, max_n: usize, depth: usize) -> bool {
    if depth == 4 {
        let mut output = String::from("totally ");
        if type_ == 0 {
            output.push_str("un");
        }
        output.push_str("connected group:");
        for &i in &idx[..depth] {
            write!(&mut output, " {}", i).unwrap();
        }
        output.push('\n');
        print!("{}", output);
        return true;
    }

    for i in min_n..max_n {
        if (0..depth).all(|n| a[idx[n]][i] == type_) {
            idx[depth] = i;
            if find_group(a, idx, type_, 1, max_n, depth + 1) {
                return true;
            }
        }
    }
    false
}

fn main() {
    let mut a = [[2; 17]; 17];
    let mark = ['0', '1', '-'];

    for k in (1..=8).step_by(8) {
        for i in 0..17 {
            let j = (i + k) % 17;
            a[i][j] = 1;
            a[j][i] = 1;
        }
    }

    for row in &a {
        for &val in row {
            print!("{} ", mark[val as usize]);
        }
        println!();
    }

    let mut idx = [0; 4];
    for i in 0..17 {
        idx[0] = i;
        if find_group(&a, &mut idx, 1, i + 1, 17, 1) || find_group(&a, &mut idx, 0, i + 1, 17, 1) {
            println!("no good");
            return;
        }
    }
    println!("all good");
}

