#include<stdio.h>

#define MOD 1000000000
int state[55], si = 0, sj = 0;

int subrand();

void subrand_seed(int p1)
{
	int i, j, p2 = 1;

	state[0] = p1 % MOD;
	for (i = 1, j = 21; i < 55; i++, j += 21) {
		if (j >= 55) j -= 55;
		state[j] = p2;
		if ((p2 = p1 - p2) < 0) p2 += MOD;
		p1 = state[j];
	}
	si = 0;
	sj = 24;
	for (i = 0; i < 165; i++) subrand();
}

int subrand()
{
	int x;
	if (si == sj) subrand_seed(0);

	if (!si--) si = 54;
	if (!sj--) sj = 54;
	if ((x = state[si] - state[sj]) < 0) x += MOD;

	return state[si] = x;
}

int main()
{
	subrand_seed(292929);
	int i;
	for (i = 0; i < 10; i++) printf("%d\n", subrand());

	return 0;
}

8c51ea425c75c0e1d25e753f16744b82.rust_code:
const MOD: u32 = 1_000_000_000;

struct Subrand {
    state: [u32; 55],
    si: usize,
    sj: usize,
}

impl Subrand {
    fn new() -> Self {
        Subrand {
            state: [0; 55],
            si: 0,
            sj: 0,
        }
    }

    fn seed(&mut self, mut p1: u32) {
        self.state[0] = p1 % MOD;
        let mut p2 = 1;
        for (i, j) in (1..55).zip((21..).cycle().take(54)) {
            self.state[j] = p2;
            p2 = if p1 >= p2 { p1 - p2 } else { MOD + p1 - p2 };
            p1 = self.state[j];
        }
        self.si = 0;
        self.sj = 24;
        for _ in 0..165 {
            self.subrand();
        }
    }

    fn subrand(&mut self) -> u32 {
        if self.si == self.sj {
            self.seed(0);
        }

        self.si = if self.si == 0 { 54 } else { self.si - 1 };
        self.sj = if self.sj == 0 { 54 } else { self.sj - 1 };
        let x = if self.state[self.si] >= self.state[self.sj] {
            self.state[self.si] - self.state[self.sj]
        } else {
            MOD + self.state[self.si] - self.state[self.sj]
        };

        self.state[self.si] = x;
        x
    }
}

fn main() {
    let mut rng = Subrand::new();
    rng.seed(292929);
    for _ in 0..10 {
        println!("{}", rng.subrand());
    }
}

