        (x - x1) * (x - x1) + (y - y1) * (y - y1)
    } else if dot_product <= 1.0 {
        let p_p1_square_length = (x1 - x) * (x1 - x) + (y1 - y) * (y1 - y);
        p_p1_square_length - dot_product * dot_product * p1_p2_square_length
    } else {
        (x - x2) * (x - x2) + (y - y2) * (y - y2)
    }
}

