    if distance_square_point_to_segment(x1, y1, x2, y2, x, y) <= EPS_SQUARE {
        return true;
    }
    if distance_square_point_to_segment(x2, y2, x3, y3, x, y) <= EPS_SQUARE {
        return true;
    }
    if distance_square_point_to_segment(x3, y3, x1, y1, x, y) <= EPS_SQUARE {
