use std::f64;

fn is_prime(p: u32) -> bool {
    if p == 2 {
        return true;
    }
    if p % 2 == 0 {
        return false;
    }
    let limit = (p as f64).sqrt() as u32;
    for i in (3..=limit).step_by(2) {
        if p % i == 0 {
            return false;
        }
    }
    true
}

fn main() {
    let mut np = 1;
    println!("3");
    for d in 1..6 {
        for i in (3..10u32.pow(d) - 1).step_by(10) {
            let n = i + 3 * 10u32.pow(d);
            if is_prime(n) {
                np += 1;
                if n < 4009 {
                    print!("{}  ", n);
                    if np % 10 == 0 {
                        println!();
                    }
                }
            }
