#[derive(Debug, Clone)]
struct Node {
    val: i32,
    op: i32,
    left: Option<usize>,
    right: Option<usize>,
}

fn eval(node: &Node, nodes: &[Node], b: &mut bool) -> f64 {
    if node.op != -1 {
        let l = eval(&nodes[node.left.unwrap()], nodes, b);
        let r = eval(&nodes[node.right.unwrap()], nodes, b);
        match node.op {
            0 => l + r,
            1 => l - r,
            2 => r - l,
            3 => l * r,
            4 => if r != 0.0 { l / r } else { *b = true; 0.0 },
            5 => if l != 0.0 { r / l } else { *b = true; 0.0 },
            _ => unreachable!(),
        }
    } else {
        node.val as f64
    }
}

fn show(node: &Node, nodes: &[Node]) {
    if node.op != -1 {
        print!("(");
        match node.op {
            0 => {
                show(&nodes[node.left.unwrap()], nodes);
                print!(" + ");
                show(&nodes[node.right.unwrap()], nodes);
            }
            1 => {
                show(&nodes[node.left.unwrap()], nodes);
                print!(" - ");
                show(&nodes[node.right.unwrap()], nodes);
            }
            2 => {
                show(&nodes[node.right.unwrap()], nodes);
                print!(" - ");
                show(&nodes[node.left.unwrap()], nodes);
            }
            3 => {
                show(&nodes[node.left.unwrap()], nodes);
                print!(" * ");
                show(&nodes[node.right.unwrap()], nodes);
            }
            4 => {
                show(&nodes[node.left.unwrap()], nodes);
                print!(" / ");
                show(&nodes[node.right.unwrap()], nodes);
            }
            5 => {
                show(&nodes[node.right.unwrap()], nodes);
                print!(" / ");
                show(&nodes[node.left.unwrap()], nodes);
            }
            _ => unreachable!(),
        }
        print!(")");
    } else {
        print!("{}", node.val);
    }
}

fn float_fix(x: f64) -> bool {
    x.abs() < 0.00001
}

fn solutions(a: &[i32], n: usize, t: f64, s: usize, nodes: &mut Vec<Node>, i_nodes: &mut usize) {
    if s == n {
        let mut b = false;
        let e = eval(&nodes[0], nodes, &mut b);

        if !b && float_fix(e - t) {
            show(&nodes[0], nodes);
            println!();
        }
    } else {
        nodes.push(Node {
            val: a[s],
            op: -1,
            left: None,
            right: None,
        });

        for op in 0..6 {
            let k = *i_nodes;
            for i in 0..k {
                nodes.push(nodes[i].clone());
                nodes[i] = Node {
                    val: -1,
                    op,
                    left: Some(*i_nodes),
                    right: Some(*i_nodes - 1),
                };
                solutions(a, n, t, s + 1, nodes, i_nodes);
                nodes[i] = nodes[*i_nodes - 1].clone();
                *i_nodes -= 1;
            }
        }

        *i_nodes -= 1;
    }
}

fn main() {
    let a = [8, 3, 8, 3];
    let t = 24.0;

    let mut nodes = vec![Node {
        val: a[0],
        op: -1,
        left: None,
        right: None,
    }];
    let mut i_nodes = 1;

    solutions(&a, a.len(), t, 1, &mut nodes, &mut i_nodes);
}

