    while b != 0 {
        let c = a;
        a = b;
        b = c % b;
    }
    a
}

#[derive(Debug)]
struct Pair {
    x: i32,
    y: i32,
}

impl Pair {
    fn print(&self) {
        println!("{{{},{}}}", self.x, self.y);
    }
}

