fn sieve(prime: &mut [bool], max: usize) {
    prime.iter_mut().for_each(|p| *p = true);
    prime[0] = false;
    prime[1] = false;

    for p in 2..=((max as f64).sqrt() as usize) {
        if prime[p] {
            for c in (p * p..=max).step_by(p) {
                prime[c] = false;
            }
        }
    }
}

fn lo_fac(prime: &[bool], n: usize) -> usize {
    if n == 1 { return 1; }
    for f in 2..=n {
        if prime[f] && n % f == 0 {
            return f;
        }
    }
    n
}

fn hi_fac(prime: &[bool], n: usize) -> usize {
    if n == 1 { return 1; }
    for f in (2..=n).rev() {
        if prime[f] && n % f == 0 {
            return f;
        }
    }
    n
}

fn main() {
    const MAX: usize = 100;
    let mut prime = vec![false; MAX + 1];
    sieve(&mut prime, MAX);

    for i in 1..=MAX {
        print!("{:6}", lo_fac(&prime, i) * hi_fac(&prime, i));
        if i % 10 == 0 {
            println!();
        }
    }
}

