use std::io::{self, Write};

const N_COND: usize = 3;
const COND_LEN: usize = 1 << N_COND;

struct Condition {
    str: &'static str,
    truth: &'static str,
}

struct Solution {
    str: &'static str,
    truth: &'static str,
}

fn main() -> io::Result<()> {
    let conditions = [
        Condition { str: "Printer does not print", truth: "1111...." },
        Condition { str: "A red light is flashing", truth: "11..11.." },
        Condition { str: "Printer is unrecognised", truth: "1.1.1.1." },
    ];

    let solutions = [
        Solution { str: "Check the power cable", truth: "..1....." },
        Solution { str: "Check the printer-computer cable", truth: "1.1....." },
        Solution { str: "Ensure printer software is installed", truth: "1.1.1.1." },
        Solution { str: "Check/replace ink", truth: "11..11.." },
        Solution { str: "Check for paper jam", truth: ".1.1...." },
    ];

    let mut ans = 0;
    let stdin = io::stdin();
    let mut stdout = io::stdout();

    for condition in &conditions {
        loop {
            write!(stdout, "{}? ", condition.str)?;
            stdout.flush()?;
            let mut input = String::new();
            stdin.read_line(&mut input)?;
            if let Some(c) = input.chars().next() {
                if c == 'y' || c == 'n' {
                    ans = (ans << 1) | (if c == 'y' { 0 } else { 1 });
                    break;
                }
            }
        }
    }

    if ans == COND_LEN - 1 {
        println!("\nSo, you don't have a problem then?");
    } else {
        println!("\nSolutions:");
        for solution in &solutions {
            if solution.truth.as_bytes()[ans] == b'1' {
                println!("    {}", solution.str);
            }
        }
    }

    Ok(())
}

