#include<stdlib.h>

int isprime( int p ) {
    int i;
    if(p==2) return 1;
    if(!(p%2)) return 0;
    for(i=3; i*i<=p; i+=2) {
       if(!(p%i)) return 0;
    }
    return 1;
}

int main( void ) {
    int p;
    long int s = 2;
    for(p=3;p<2000000;p+=2) {
        if(isprime(p)) s+=p;
    }
    printf( "%ld\n", s );
    return 0;
}

425329ff54b146144eebfc23cd08b4fc.rust_code:
fn is_prime(p: u32) -> bool {
    if p == 2 {
        return true;
    }
    if p % 2 == 0 {
        return false;
    }
    (3..=((p as f64).sqrt() as u32))
        .step_by(2)
        .all(|i| p % i != 0)
}

fn main() {
    let mut s: u64 = 2;
    for p in (3..2_000_000).step_by(2) {
        if is_prime(p) {
            s += p as u64;
        }
    }
    println!("{}", s);
}

