#include <stdio.h>

int SumDigits(unsigned long long n, const int base) {
    int sum = 0;
    for (; n; n /= base)
    	sum += n % base;
    return sum;
}

int main() {
    printf("%d %d %d %d %d\n",
        SumDigits(1, 10),
        SumDigits(12345, 10),
        SumDigits(123045, 10),
        SumDigits(0xfe, 16),
        SumDigits(0xf0e, 16) );
    return 0;
}

f54755cc3e75b9608f01cad1caad6ef6.rust_code:
fn sum_digits(mut n: u64, base: u32) -> u32 {
    let mut sum = 0;
    while n > 0 {
        sum += (n % base as u64) as u32;
        n /= base as u64;
    }
    sum
}

fn main() {
    println!("{} {} {} {} {}", 
             sum_digits(1, 10), 
             sum_digits(12345, 10), 
             sum_digits(123045, 10), 
             sum_digits(0xfe, 16), 
             sum_digits(0xf0e, 16));
}

