#include<stdlib.h>
#include<stdio.h>

typedef struct{
        int x;
        int (*funcPtr)(int);
}functionPair;

int factorial(int num){
        if(num==0||num==1)
                return 1;
        else
                return num*factorial(num-1);
}

int main(int argc,char** argv)
{
        functionPair response;

        if(argc!=2)
                return printf("Usage : %s <non negative integer>",argv[0]);
        else{
                response = (functionPair){.x = atoi(argv[1]),.funcPtr=&factorial};
                printf("\nFactorial of %d is %d\n",response.x,response.funcPtr(response.x));
        }
        return 0;
}

84cc8205b7a7c69cf9b191f3a95eefdc.rust_code:
use std::env;
use std::process;

struct FunctionPair {
    x: i32,
    func_ptr: fn(i32) -> i32,
}

fn factorial(num: i32) -> i32 {
    match num {
        0 | 1 => 1,
        _ => num * factorial(num - 1),
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() != 2 {
        eprintln!("Usage: {} <non negative integer>", args[0]);
        process::exit(1);
    }

    let x: i32 = match args[1].parse() {
        Ok(n) => n,
        Err(_) => {
            eprintln!("Please provide a valid non-negative integer.");
            process::exit(1);
        }
    };

    let response = FunctionPair {
        x,
        func_ptr: factorial,
    };

    println!("\nFactorial of {} is {}\n", response.x, (response.func_ptr)(response.x));
}

