fn bsearch(a: &[i32], x: i32) -> Option<usize> {
    let mut i = 0;
    let mut j = a.len().wrapping_sub(1);
    while i <= j {
        let k = i + (j - i) / 2;
        match a[k].cmp(&x) {
            std::cmp::Ordering::Equal => return Some(k),
            std::cmp::Ordering::Less => i = k + 1,
            std::cmp::Ordering::Greater => j = k.wrapping_sub(1),
        }
    }
    None
}

fn bsearch_r(a: &[i32], x: i32, i: usize, j: usize) -> Option<usize> {
    if j < i {
        return None;
    }
    let k = i + (j - i) / 2;
    match a[k].cmp(&x) {
        std::cmp::Ordering::Equal => Some(k),
        std::cmp::Ordering::Less => bsearch_r(a, x, k + 1, j),
        std::cmp::Ordering::Greater => bsearch_r(a, x, i, k.wrapping_sub(1)),
    }
}

fn main() {
    let a = vec![-31, 0, 1, 2, 2, 4, 65, 83, 99, 782];
