use std::cmp::Ordering;

#[derive(Debug)]
enum Op {
    Add,
    Sub,
    Join,
}

#[derive(Debug)]
struct Expression {
    sum: i32,
    code: u32,
}

#[derive(Debug)]
struct CountSum {
    counts: usize,
    sum: i32,
}

fn evaluate(code: u32) -> i32 {
    let mut value = 0;
    let mut number = 0;
    let mut power = 1;
    let mut code = code;
    for k in (1..=9).rev() {
        number = power * k + number;
        match code % 3 {
            0 => {
                value += number;
                number = 0;
                power = 1;
            }
            1 => {
                value -= number;
                number = 0;
                power = 1;
            }
            2 => power *= 10,
            _ => unreachable!(),
        }
        code /= 3;
    }
    value
}

fn print(code: u32) {
    let mut s = String::with_capacity(19);
    let mut a = 19683;
    let mut b = 6561;
    let mut code = code;
    for k in 1..=9 {
        match (code % a) / b {
            0 => {
                if k > 1 {
                    s.push('+');
                }
            }
            1 => s.push('-'),
            2 => {}
            _ => unreachable!(),
        }
        a = b;
        b /= 3;
        s.push((b'0' + k as u8) as char);
    }
    println!("{:9} = {}", evaluate(code), s);
}

fn comment(string: &str) {
    println!("\n\n{}\n\n", string);
}

fn init() -> (Vec<Expression>, Vec<CountSum>) {
    let mut expressions = Vec::with_capacity(NUMBER_OF_EXPRESSIONS);
    for i in 0..NUMBER_OF_EXPRESSIONS {
        expressions.push(Expression {
            sum: evaluate(i as u32),
            code: i as u32,
        });
    }
    expressions.sort_by_key(|e| e.sum);

    let mut count_sums = Vec::new();
    if let Some(first) = expressions.first() {
        count_sums.push(CountSum {
            counts: 1,
            sum: first.sum,
        });
    }
    for expr in expressions.iter().skip(1) {
        if count_sums.last().unwrap().sum != expr.sum {
            count_sums.push(CountSum {
                counts: 1,
                sum: expr.sum,
            });
        } else {
            count_sums.last_mut().unwrap().counts += 1;
        }
    }
    count_sums.sort_by_key(|cs| cs.counts);

    (expressions, count_sums)
}

const NUMBER_OF_EXPRESSIONS: usize = 2 * 3 * 3 * 3 * 3 * 3 * 3 * 3 * 3;

fn main() {
    let (expressions, count_sums) = init();

    comment("Show all solutions that sum to 100");
    let given_sum = 100;
    if let Ok(mut idx) = expressions.binary_search_by_key(&given_sum, |e| e.sum) {
        while idx > 0 && expressions[idx - 1].sum == given_sum {
            idx -= 1;
        }
        while idx < expressions.len() && expressions[idx].sum == given_sum {
            print(expressions[idx].code);
            idx += 1;
        }
