    while max_sum_index < count_sums.len() && count_sums[max_sum_index].sum < 0 {
        max_sum_index = max_sum_index.wrapping_sub(1);
    }
    if max_sum_index < count_sums.len() {
        println!(
            "{} has {} solutions",
            count_sums[max_sum_index].sum, count_sums[max_sum_index].counts
        );
    }

    comment("Show the lowest positive number that can't be expressed");
    for value in 0.. {
        let expr = Expression { sum: value, code: 0 };
        if expressions.binary_search_by_key(&value, |e| e.sum).is_err() {
            println!("{}", value);
            break;
        }
    }

    comment("Show the ten highest numbers that can be expressed");
    for expr in expressions.iter().rev().take(10) {
        print(expr.code);
    }
