            prev: None,
        }))
    }
}

fn new_list() -> LinkedList {
    ListEntry::new(None)
}

fn ll_append(ll: &LinkedList, new_val: &str) -> bool {
    let new_entry = ListEntry::new(Some(new_val));
    let mut tail = ll.borrow_mut();
    if let Some(prev) = tail.prev.clone() {
        prev.borrow_mut().next = Some(new_entry.clone());
    } else {
        tail.next = Some(new_entry.clone());
    }
    tail.prev = Some(new_entry);
    true
}

fn li_insert(iter: &LIterator, new_val: &str) -> bool {
    let new_entry = ListEntry::new(Some(new_val));
    let current = iter.borrow().link.clone();
    let head = iter.borrow().head.clone();

