    let mut i = 9;
    while i > 0 {
        if x & (127_u64 << (i * 7)) != 0 {
            break;
        }
        i -= 1;
    }
    for j in 0..=i {
        out[j as usize] = ((x >> ((i - j) * 7)) & 127) as u8 | 128;
    }
    out[i as usize] ^= 128;
}

