    let mut r = 0;
    let mut bytes = in_.iter();
    loop {
        if let Some(&byte) = bytes.next() {
            r = (r << 7) | (byte & 127) as u64;
            if byte & 128 == 0 {
                break;
            }
        } else {
            break;
        }
    }
    r
}

