        print!("seq from {:x}: [ ", value);

        let mut i = 0;
        while s[i] & 128 != 0 {
            print!("{:02x} ", s[i]);
            i += 1;
        }
        println!("] back: {:x}", from_seq(&s[..=i]));
    }
}

