use std::io::{self, Write};

fn proper_divisors(n: u32, print_flag: bool) -> u32 {
    let mut count = 0;

    for i in 1..n {
        if n % i == 0 {
            count += 1;
            if print_flag {
                print!("{} ", i);
                io::stdout().flush().unwrap();
            }
        }
    }

    if print_flag {
        println!();
    }

    count
}

