    for i in 0..n {
        for j in 0..n {
            let value = if i == 0 || i == n - 1 || j == 0 || j == n - 1 {
                1
            } else {
                0
            };
            print!("{} ", value);
        }
        println!();
    }
}

fn main() {
    hollow_matrix(10);
    println!();
    hollow_matrix(11);
}

