#include<stdio.h>
#include<stdlib.h>
#include<math.h>

int sum5( int n ) {
    if(n<10) return pow(n,5);
    return pow(n%10,5) + sum5(n/10);
}

int main(void) {
    int i, sum = 0;
    for(i=2;i<=999999;i++) {
        if(i==sum5(i)) {
            printf( "%d\n", i );
            sum+=i;
        }
    }
    printf( "Total is %d\n", sum );
    return 0;
}

bcd0b19abd26b6fe01aebba69d59a284.rust_code:
fn sum5(mut n: u32) -> u32 {
    if n < 10 {
        n.pow(5)
    } else {
        (n % 10).pow(5) + sum5(n / 10)
    }
}

fn main() {
    let mut sum = 0;
    for i in 2..=999999 {
        if i == sum5(i) {
            println!("{}", i);
            sum += i;
        }
    }
    println!("Total is {}", sum);
}

