use std::io::{self, Write};

fn main() -> io::Result<()> {
    let mut input = String::new();
    print!("Enter the number of resources: ");
    io::stdout().flush()?;
    io::stdin().read_line(&mut input)?;
    let r: usize = input.trim().parse().expect("Please enter a valid number");

    input.clear();
    print!("Enter the number of processes: ");
    io::stdout().flush()?;
    io::stdin().read_line(&mut input)?;
    let p: usize = input.trim().parse().expect("Please enter a valid number");

    let mut running = vec![true; p];
    let mut count = p;
    let mut safe = false;

    input.clear();
    print!("Enter Claim Vector: ");
    io::stdout().flush()?;
    io::stdin().read_line(&mut input)?;
    let max_res: Vec<i32> = input.split_whitespace()
        .take(r)
        .map(|s| s.parse().expect("Please enter valid numbers"))
        .collect();

    let mut curr = vec![vec![0; r]; p];
    for i in 0..p {
        input.clear();
        print!("Enter allocated resources for process {}: ", i + 1);
        io::stdout().flush()?;
        io::stdin().read_line(&mut input)?;
        curr[i] = input.split_whitespace()
            .take(r)
            .map(|s| s.parse().expect("Please enter valid numbers"))
            .collect();
    }

    let mut max_claim = vec![vec![0; r]; p];
    for i in 0..p {
        input.clear();
        print!("Enter maximum claim for process {}: ", i + 1);
        io::stdout().flush()?;
        io::stdin().read_line(&mut input)?;
        max_claim[i] = input.split_whitespace()
            .take(r)
            .map(|s| s.parse().expect("Please enter valid numbers"))
            .collect();
    }

    println!("\nThe Claim Vector is: {:?}", max_res);
    println!("\nThe Allocated Resource Table:");
    for row in &curr {
        println!("{:?}", row);
    }
    println!("\nThe Maximum Claim Table:");
    for row in &max_claim {
        println!("{:?}", row);
    }

    let mut alloc = vec![0; r];
    for i in 0..p {
        for j in 0..r {
            alloc[j] += curr[i][j];
        }
    }

    println!("\nAllocated resources: {:?}", alloc);
    let mut avl = max_res.iter().zip(alloc.iter()).map(|(&a, &b)| a - b).collect::<Vec<_>>();

    println!("\nAvailable resources: {:?}", avl);

    while count != 0 {
        safe = false;
        for i in 0..p {
            if running[i] {
                let mut exec = true;
                for j in 0..r {
                    if max_claim[i][j] - curr[i][j] > avl[j] {
                        exec = false;
                        break;
                    }
                }

                if exec {
                    println!("\nProcess{} is executing.", i + 1);
                    running[i] = false;
                    count -= 1;
                    safe = true;
                    for j in 0..r {
                        avl[j] += curr[i][j];
                    }
                    break;
                }
            }
        }

        if !safe {
            println!("\nThe processes are in unsafe state.");
            break;
        }

        if safe {
            println!("\nThe process is in safe state.");
        }

        println!("\nAvailable vector: {:?}", avl);
    }

    Ok(())
}

