#include <stdio.h>

void bubble_sort (int *a, int n) {
    int i, t, j = n, s = 1;
    while (s) {
        s = 0;
        for (i = 1; i < j; i++) {
            if (a[i] < a[i - 1]) {
                t = a[i];
                a[i] = a[i - 1];
                a[i - 1] = t;
                s = 1;
            }
        }
        j--;
    }
}

int main () {
    int a[] = {4, 65, 2, -31, 0, 99, 2, 83, 782, 1};
    int n = sizeof a / sizeof a[0];
    int i;
    for (i = 0; i < n; i++)
        printf("%d%s", a[i], i == n - 1 ? "\n" : " ");
    bubble_sort(a, n);
    for (i = 0; i < n; i++)
        printf("%d%s", a[i], i == n - 1 ? "\n" : " ");
    return 0;
}

56bec27e49da917eb1ad9e98dd5bea3f.rust_code:
fn bubble_sort(arr: &mut [i32]) {
    let mut swapped = true;
    let mut j = arr.len();
    while swapped {
        swapped = false;
        for i in 1..j {
            if arr[i] < arr[i - 1] {
                arr.swap(i, i - 1);
                swapped = true;
            }
        }
        j -= 1;
    }
}

fn main() {
    let mut a = vec![4, 65, 2, -31, 0, 99, 2, 83, 782, 1];
    for (i, &value) in a.iter().enumerate() {
        print!("{}{}", value, if i == a.len() - 1 { "\n" } else { " " });
    }
    bubble_sort(&mut a);
    for (i, &value) in a.iter().enumerate() {
        print!("{}{}", value, if i == a.len() - 1 { "\n" } else { " " });
    }
}

