void generateGaps(unsigned long long int start,int count){

    int counter = 0;
    unsigned long long int i = start;
    char str[100];

    printf("\nFirst %d Gapful numbers >= %llu :\n",count,start);

    while(counter<count){
        sprintf(str,"%llu",i);
        if((i%(10*(str[0]-'0') + i%10))==0L){
            printf("\n%3d : %llu",counter+1,i);
            counter++;
        }
        i++;
    }
}

int main()
{
    unsigned long long int i = 100;
    int count = 0;
    char str[21];

    generateGaps(100,30);
    printf("\n");
    generateGaps(1000000,15);
    printf("\n");
    generateGaps(1000000000,15);
    printf("\n");

    return 0;
}

7cc6a208e6b422cad412e3aec79ebacc.rust_code:
use std::fmt::Write;

fn generate_gaps(start: u64, count: usize) {
    let mut counter = 0;
    let mut i = start;

    println!("\nFirst {} Gapful numbers >= {}:", count, start);

    while counter < count {
        let mut str_buf = String::new();
        write!(&mut str_buf, "{}", i).unwrap();
        let first_digit = str_buf.chars().next().unwrap().to_digit(10).unwrap() as u64;
        let last_digit = str_buf.chars().last().unwrap().to_digit(10).unwrap() as u64;
        let divisor = 10 * first_digit + last_digit;

        if i % divisor == 0 {
            println!("{:>3} : {}", counter + 1, i);
            counter += 1;
        }
        i += 1;
    }
}

fn main() {
    generate_gaps(100, 30);
    println!();
    generate_gaps(1_000_000, 15);
    println!();
    generate_gaps(1_000_000_000, 15);
    println!();
}

