#include <stdio.h>
#include <stdlib.h>


const int N = 15;

int main()
{

    register int k, n;


    unsigned long long int num, den;


    int catalan;


    printf("1 ");


    for (n=2; n<=N; ++n) {

        num = den = 1;

        for (k=2; k<=n; ++k) {
            num *= (n+k);
            den *= k;
            catalan = num /den;
        }


        printf("%d ", catalan);
    }


    printf("\n");
    return 0;
}

