    loop {
        let mut s = 0;
        let mut num = x;
        while num > 0 {
            let digit = num % 10;
            s += digit * digit;
            num /= 10;
        }

        if s == 89 {
            return true;
        }
        if s == 1 {
            return false;
        }
        x = s;
    }
}

