    let mut sums = vec![0u64; 32 * 81 + 1];
    sums[1] = 1;

    for n in 1.. {
        for i in (1..=n * 81).rev() {
            for j in 1..10 {
                let s = j * j;
                if s > i {
                    break;
                }
                sums[i] += sums[i - s];
            }
        }

        let mut count89 = 0;
        for i in 1..=n * 81 {
            if !is89(i as u32) {
                continue;
            }

            if count89 > u64::MAX - sums[i] {
                println!("counter overflow for 10^{}", n);
                return;
            }
            count89 += sums[i];
        }

        println!("1->10^{}: {}", n, count89);
    }
}

