use std::fmt::Write;

fn bin2str(value: u32) -> String {
    let mut buffer = String::with_capacity(32);
    let mut mask = 1 << 31;

    while mask != 0 {
        buffer.push(if value & mask != 0 { '1' } else { '0' });
        mask >>= 1;
    }

    buffer.trim_start_matches('0').to_string()
}

fn bin2str_naive(mut value: u32) -> String {
    if value == 0 {
        return "0".to_string();
    }

    let mut buffer = String::new();
    let mut p = 1;

    while p <= value / 2 {
        p *= 2;
    }

    while p != 0 {
        write!(&mut buffer, "{}", if value >= p { '1' } else { '0' }).unwrap();
        if value >= p {
            value -= p;
        }
        p /= 2;
    }

    buffer
}

fn main() {
    let numbers = [5, 50, 9000];

    for &value in &numbers {
        println!("bin2str:       {} decimal = {} binary", value, bin2str(value));
    }

    for &value in &numbers {
        println!("bin2strNaive:  {} decimal = {} binary", value, bin2str_naive(value));
    }
}

