use std::collections::HashMap;

fn is89(mut x: u32) -> bool {
    loop {
        let mut s = 0;
        let mut num = x;
        while num > 0 {
            let digit = num % 10;
            s += digit * digit;
            num /= 10;
        }

        if s == 89 {
            return true;
        }
        if s == 1 {
            return false;
        }
        x = s;
    }
}

fn main() {
    let mut sums = vec![0u64; 32 * 81 + 1];
    sums[1] = 1;

    for n in 1.. {
        for i in (1..=n * 81).rev() {
            for j in 1..10 {
                let s = j * j;
                if s > i {
