    fn new() -> Self {
        GridSolver {
            grid: Vec::new(),
            w: 0,
            h: 0,
            len: 0,
            cnt: 0,
            next: [-1, 0, 1, 0],
            dir: [(0, -1), (-1, 0), (0, 1), (1, 0)],
        }
    }

    fn walk(&mut self, y: isize, x: isize) {
        if y == 0 || y == self.h as isize || x == 0 || x == self.w as isize {
            self.cnt += 2;
            return;
        }

        let t = (y * (self.w + 1) as isize + x) as usize;
        self.grid[t] += 1;
        self.grid[self.len - t] += 1;

        for i in 0..4 {
            let nt = t as isize + self.next[i];
            if self.grid[nt as usize] == 0 {
                self.walk(y + self.dir[i].0, x + self.dir[i].1);
            }
        }

        self.grid[t] -= 1;
        self.grid[self.len - t] -= 1;
    }

    fn solve(&mut self, hh: usize, ww: usize, recur: bool) -> u64 {
        self.h = hh;
        self.w = ww;

        if self.h % 2 != 0 {
            std::mem::swap(&mut self.w, &mut self.h);
        }
        if self.h % 2 != 0 {
            return 0;
        }
        if self.w == 1 {
            return 1;
        }
        if self.w == 2 {
            return self.h as u64;
        }
        if self.h == 2 {
            return self.w as u64;
        }

        let cy = self.h / 2;
        let cx = self.w / 2;

        self.len = (self.h + 1) * (self.w + 1);
        self.grid.resize(self.len, 0);

        self.next[1] = -(self.w as isize + 1);
        self.next[3] = self.w as isize + 1;

        if recur {
            self.cnt = 0;
        }
        for x in cx + 1..self.w {
            let t = cy * (self.w + 1) + x;
            self.grid[t] = 1;
            self.grid[self.len - t] = 1;
            self.walk((cy - 1) as isize, x as isize);
        }
        self.cnt += 1;

        if self.h == self.w {
            self.cnt *= 2;
        } else if self.w % 2 == 0 && recur {
            self.solve(self.w, self.h, false);
        }

        self.cnt
    }
}

fn main() {
    let mut solver = GridSolver::new();
    for y in 1..=10 {
        for x in 1..=y {
            if y % 2 == 0 || x % 2 == 0 {
                println!("{} x {}: {}", y, x, solver.solve(y, x, true));
            }
        }
    }
}

