    static mut PRIMES: VecDeque<u64> = VecDeque::new();

    unsafe {
        if idx >= PRIMES.len() {
            if PRIMES.is_empty() {
                PRIMES.push_back(2);
                PRIMES.push_back(3);
            }

            let mut last = *PRIMES.back().unwrap();
            while idx >= PRIMES.len() {
                last += 2;
                let mut is_prime = true;
                for &p in &PRIMES {
                    if p * p > last {
                        break;
                    }
                    if last % p == 0 {
                        is_prime = false;
                        break;
                    }
                }
                if is_prime {
                    PRIMES.push_back(last);
                }
            }
        }
        *PRIMES.get(idx).unwrap()
    }
}

fn main() {
    let mut x = 1;
    loop {
        print!("{} = ", x);
        let mut n = x;
        let mut first = true;
        for i in 0.. {
            let p = get_prime(i);
            while n % p == 0 {
                n /= p;
                if !first {
                    print!(" x ");
                }
                first = false;
                print!("{}", p);
            }
            if n <= p * p {
                break;
            }
        }
        if first {
            println!("{}", n);
        } else if n > 1 {
            println!(" x {}", n);
        } else {
            println!();
        }
        x += 1;
    }
}

