fn chowla(n: u32) -> u32 {
    let mut sum = 0;
    let mut i = 2;
    while i * i <= n {
        if n % i == 0 {
            let j = n / i;
            sum += i + if i == j { 0 } else { j };
        }
        i += 1;
    }
    sum
}

