    count = 0;
    let limit = 350_000_000;
    let mut k = 2;
    let mut kk = 3;
    loop {
        let p = k * kk;
        if p > limit {
            break;
        }
        if chowla(p) == p - 1 {
            println!("{} is a perfect number", p);
            count += 1;
        }
        k = kk + 1;
        kk += k;
    }
    println!("There are {} perfect numbers < {}", count, limit);
}

