use std::time::{Instant};

fn contains(lst: &[i32], item: i32) -> bool {
    lst.iter().any(|&x| x == item)
}

fn mian_chowla() -> Vec<i32> {
    let n = 100;
    let mut mc = vec![0; n];
    mc[0] = 1;
    let mut sums = vec![0; (n * (n + 1)) / 2];
    sums[0] = 2;
    let mut ss = 1;

    for i in 1..n {
        let le = ss;
        'outer: for j in (mc[i - 1] + 1).. {
            mc[i] = j;
            for &k in &mc[..=i] {
                let sum = k + j;
                if contains(&sums[..ss], sum) {
                    ss = le;
                    continue 'outer;
                }
                sums[ss] = sum;
                ss += 1;
            }
            break;
        }
    }

    mc
}

fn main() {
    let start = Instant::now();
    let mc = mian_chowla();
    let duration = start.elapsed();

    println!("The first 30 terms of the Mian-Chowla sequence are:");
    for &term in &mc[..30] {
        print!("{} ", term);
    }
    println!();

    println!("Terms 91 to 100 of the Mian-Chowla sequence are:");
    for &term in &mc[90..100] {
        print!("{} ", term);
    }
    println!();

    println!("Computation time was {} seconds.", duration.as_secs_f64());
}

