#include <stdio.h>


int rand();
int rseed = 0;

inline void srand(int x)
{
	rseed = x;
}

#ifndef MS_RAND
#define RAND_MAX ((1U << 31) - 1)

inline int rand()
{
	return rseed = (rseed * 1103515245 + 12345) & RAND_MAX;
}

#else 

#define RAND_MAX_32 ((1U << 31) - 1)
#define RAND_MAX ((1U << 15) - 1)

inline int rand()
{
	return (rseed = (rseed * 214013 + 2531011) & RAND_MAX_32) >> 16;
}

#endif

int main()
{
	int i;
	printf("rand max is %d\n", RAND_MAX);

	for (i = 0; i < 100; i++)
		printf("%d\n", rand());

	return 0;
}

99441cc3aaff0b9696ef7e4ddb03b637.rust_code:
use std::fmt;

struct Random {
    seed: u32,
}

impl Random {
    const RAND_MAX: u32 = (1u32 << 31) - 1;
    const RAND_MAX_32: u32 = Self::RAND_MAX;
    const RAND_MAX_16: u32 = (1u32 << 15) - 1;

    fn new(seed: u32) -> Self {
        Random { seed }
    }

    #[cfg(not(feature = "ms_rand"))]
    fn rand(&mut self) -> u32 {
        self.seed = (self.seed.wrapping_mul(1103515245) + 12345) & Self::RAND_MAX;
        self.seed
    }

    #[cfg(feature = "ms_rand")]
    fn rand(&mut self) -> u32 {
        self.seed = (self.seed.wrapping_mul(214013) + 2531011) & Self::RAND_MAX_32;
        self.seed >> 16
    }
}

impl fmt::Display for Random {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", Self::RAND_MAX_16)
    }
}

fn main() {
    let mut rng = Random::new(0);
    println!("rand max is {}", rng);

    for _ in 0..100 {
        println!("{}", rng.rand());
    }
}

