#include <stdio.h>

#define N_COND 3
#define COND_LEN (1 << N_COND)

struct { const char *str, *truth;}
cond[N_COND] = {
	{"Printer does not print",		"1111...."},
	{"A red light is flashing",		"11..11.."},
	{"Printer is unrecognised",		"1.1.1.1."},
},
solu[] = {
	{"Check the power cable",		"..1....."},
	{"Check the printer-computer cable",	"1.1....."},
	{"Ensure printer software is installed","1.1.1.1."},
	{"Check/replace ink",			"11..11.."},
	{"Check for paper jam",			".1.1...."},
};

int main()
{
	int q, ans, c;

	for (q = ans = c = 0; q < N_COND; q++) {
		do {
			if (c != '\n') printf("%s? ", cond[q].str);
			c = getchar();
		} while (c != 'y' && c != 'n');
		ans = (ans << 1) | (c != 'y');
	}

	if (ans == COND_LEN - 1)
		printf("\nSo, you don't have a problem then?\n");
	else {
		printf("\nSolutions:\n");
		for (q = 0; q < sizeof(solu)/sizeof(solu[0]); q++)
			if (solu[q].truth[ans] == '1')
				printf("    %s\n", solu[q].str);
	}
	return 0;
}

7478082329cb59347fc2e72c088b5c91.rust_code:
use std::io::{self, Write};

const N_COND: usize = 3;
const COND_LEN: usize = 1 << N_COND;

struct Condition {
    str: &'static str,
    truth: &'static str,
}

struct Solution {
    str: &'static str,
    truth: &'static str,
}

fn main() -> io::Result<()> {
    let conditions = [
        Condition { str: "Printer does not print", truth: "1111...." },
        Condition { str: "A red light is flashing", truth: "11..11.." },
        Condition { str: "Printer is unrecognised", truth: "1.1.1.1." },
    ];

    let solutions = [
        Solution { str: "Check the power cable", truth: "..1....." },
        Solution { str: "Check the printer-computer cable", truth: "1.1....." },
        Solution { str: "Ensure printer software is installed", truth: "1.1.1.1." },
        Solution { str: "Check/replace ink", truth: "11..11.." },
        Solution { str: "Check for paper jam", truth: ".1.1...." },
    ];

    let mut ans = 0;
    let stdin = io::stdin();
    let mut stdout = io::stdout();

    for condition in &conditions {
        loop {
            write!(stdout, "{}? ", condition.str)?;
            stdout.flush()?;
            let mut input = String::new();
            stdin.read_line(&mut input)?;
            if let Some(c) = input.chars().next() {
                if c == 'y' || c == 'n' {
                    ans = (ans << 1) | (if c == 'y' { 0 } else { 1 });
                    break;
                }
            }
        }
    }

    if ans == COND_LEN - 1 {
        println!("\nSo, you don't have a problem then?");
    } else {
        println!("\nSolutions:");
        for solution in &solutions {
            if solution.truth.as_bytes()[ans] == b'1' {
                println!("    {}", solution.str);
            }
        }
    }

    Ok(())
}

