    let mut tot = n;
    let mut i = 2;

    while i * i <= n {
        if n % i == 0 {
            while n % i == 0 {
                n /= i;
            }
            tot -= tot / i;
        }
        if i == 2 {
            i = 1;
        }
        i += 2;
