    let mut n = 0;
    let mut i = 1;
    while n < MAX {
        let k = count_divisors(i);
        if k <= MAX as u32 && seq[(k - 1) as usize] == 0 {
            seq[(k - 1) as usize] = i;
            n += 1;
        }
        i += 1;
    }
    for &value in &seq {
        print!("{} ", value);
    }
    println!();
}

