fn count_divisors(n: u32) -> u32 {
    let mut count = 0;
    let limit = (n as f64).sqrt() as u32 + 1;
    for i in 1..limit {
        if n % i == 0 {
            if i == n / i {
                count += 1;
            } else {
                count += 2;
            }
        }
    }
    count
}

fn main() {
    const MAX: usize = 15;
    let mut seq = vec![0; MAX];
    println!("The first {} terms of the sequence are:", MAX);
    let mut n = 0;
    let mut i = 1;
    while n < MAX {
        let k = count_divisors(i);
        if k <= MAX as u32 && seq[(k - 1) as usize] == 0 {
            seq[(k - 1) as usize] = i;
            n += 1;
        }
        i += 1;
    }
    for &value in &seq {
        print!("{} ", value);
    }
    println!();
}

