use std::io::{self, Write};

fn fib(x: i64) -> i64 {
    fn fib_i(n: i64) -> i64 {
        if n < 2 {
            n
        } else {
            fib_i(n - 2) + fib_i(n - 1)
        }
    }

    if x < 0 {
        writeln!(io::stderr(), "Bad argument: fib({})", x).unwrap();
        return -1;
    }
    fib_i(x)
