fn eq_idx(a: &[i32]) -> Vec<usize> {
    let mut ret = Vec::new();
    let sum: i32 = a.iter().sum();
    let mut s = 0;

    for (i, &value) in a.iter().enumerate() {
        if s * 2 + value == sum {
            ret.push(i);
        }
        s += value;
    }

    ret
}

