use std::io::{self, Write};

trait Stream {
    fn get(&mut self) -> Option<u8>;
    fn put(&mut self, byte: u8) -> io::Result<()>;
}

struct StringStream<'a> {
    string: &'a [u8],
    pos: usize,
    buffer: &'a mut [u8],
    write_pos: usize,
}

impl<'a> StringStream<'a> {
    fn new(string: &'a [u8], buffer: &'a mut [u8]) -> Self {
        StringStream {
            string,
            pos: 0,
            buffer,
            write_pos: 0,
        }
    }
}

impl<'a> Stream for StringStream<'a> {
    fn get(&mut self) -> Option<u8> {
        if self.pos < self.string.len() {
            let byte = self.string[self.pos];
            self.pos += 1;
            Some(byte)
        } else {
            None
        }
    }

    fn put(&mut self, byte: u8) -> io::Result<()> {
        if self.write_pos < self.buffer.len() {
            self.buffer[self.write_pos] = byte;
            self.write_pos += 1;
            Ok(())
        } else {
            Err(io::Error::new(io::ErrorKind::WriteZero, "Buffer overflow"))
        }
    }
}

struct FileStream<W: Write> {
    writer: W,
}

impl<W: Write> FileStream<W> {
    fn new(writer: W) -> Self {
        FileStream { writer }
    }
}

impl<W: Write> Stream for FileStream<W> {
    fn get(&mut self) -> Option<u8> {
        // This implementation assumes that the input is provided through another means,
        // as the original C code does not show how to read from a file.
        // For demonstration purposes, we return None.
        None
    }

    fn put(&mut self, byte: u8) -> io::Result<()> {
        self.writer.write_all(&[byte])
    }
}

fn output<S: Stream>(out: &mut S, buf: &[u8], len: usize) -> io::Result<()> {
    out.put(128 + len as u8)?;
    for &byte in &buf[..len] {
        out.put(byte)?;
    }
    Ok(())
}

fn encode<I: Stream, O: Stream>(in_stream: &mut I, out_stream: &mut O) -> io::Result<()> {
    let mut buf = [0u8; 256];
    let mut len = 0;
    let mut repeat = false;
    let mut end = false;

    while !end {
        match in_stream.get() {
            Some(c) => {
                buf[len] = c;
                len += 1;
                end = false;
            }
            None => end = true,
        }

        if repeat {
            if buf[len - 1] != buf[len - 2] {
                repeat = false;
            }
            if !repeat || len == 129 || end {
                out_stream.put(end as u8 + (len - 1) as u8)?;
                out_stream.put(buf[0])?;
                buf[0] = buf[len - 1];
                len = 1;
            }
        } else {
            if len > 1 && buf[len - 1] == buf[len - 2] {
                repeat = true;
                if len > 2 {
                    output(out_stream, &buf, len - 2)?;
                    buf[0] = buf[1];
                    buf[1] = buf[len - 1];
                    len = 2;
                }
                continue;
            }
            if len == 128 || end {
                output(out_stream, &buf, len)?;
                len = 0;
                repeat = false;
            }
        }
    }
    out_stream.put(0)?;
    Ok(())
}

fn decode<I: Stream, O: Stream>(in_stream: &mut I, out_stream: &mut O) -> io::Result<()> {
    while let Some(c) = in_stream.get() {
        if c > 128 {
            let cnt = c - 128;
            for _ in 0..cnt {
                if let Some(byte) = in_stream.get() {
                    out_stream.put(byte)?;
                } else {
                    break;
                }
            }
        } else {
            let cnt = c;
            if let Some(byte) = in_stream.get() {
                for _ in 0..cnt {
                    out_stream.put(byte)?;
                }
            } else {
                break;
            }
        }
    }
    Ok(())
}

fn main() -> io::Result<()> {
    let input_str = b"WWWWWWWWWWWWBWWWWWWWWWWWWBBBWWWWWWWWWWWWWWWWWWWWWWWWBWWWWWWWWWWWWWW";
    let mut output_buf = [0u8; 256];

    let mut str_in = StringStream::new(input_str, &mut []);
    let mut str_out = StringStream::new(&[], &mut output_buf);
    let mut file_out = FileStream::new(io::stdout());

    encode(&mut str_in, &mut str_out)?;
    decode(&mut str_out, &mut file_out)?;

    Ok(())
}

