#include <stdio.h>

int Gcd(int v1, int v2)
{

	int a, b, r;
	if (v1 < v2)
	{
		a = v2;
		b = v1;
	}
	else
	{
		a = v1;
		b = v2;
	}
	do
	{
		r = a % b;
		if (r == 0)
		{
			break;
		}
		else
		{
			a = b;
			b = r;
		}
	} while (1 == 1);
	return b;
}

int NotInList(int num, int numtrip, int *tripletslist)
{

	for (int i = 0; i < numtrip; i++)
	{
		if (num == tripletslist[i])
		{
			return 0;
		}
	}
	return 1;
} 	

int main()
{
	int coprime[50];
	int gcd1, gcd2;
	int ntrip = 2;
	int n = 3;


	coprime[0] = 1;
	coprime[1] = 2;

	while ( n < 50)
	{
		gcd1 = Gcd(n, coprime[ntrip-1]);
		gcd2 = Gcd(n, coprime[ntrip-2]);

		if (gcd1 == 1 && gcd2 == 1 && NotInList(n, ntrip, coprime))
		{
			coprime[ntrip++] = n;

			n = 3;
		}
		else
		{

			n++;
		}
	}


	printf("\n");
	for (int i = 0; i < ntrip; i++)
	{
		printf("%2d ", coprime[i]);
		if ((i+1) % 10 == 0)
		{
			printf("\n");
		}
	}

	printf("\n\nNumber of elements in coprime triplets: %d\n\n", ntrip);

	return 0;
}

4a3e2beaf18b4b59c0e7ef5a3a439cd0.rust_code:
fn gcd(mut a: i32, mut b: i32) -> i32 {
    if a < b {
        std::mem::swap(&mut a, &mut b);
    }
    loop {
        let r = a % b;
        if r == 0 {
            break;
        } else {
            a = b;
            b = r;
        }
    }
    b
}

fn not_in_list(num: i32, triplets_list: &[i32]) -> bool {
    !triplets_list.contains(&num)
}

fn main() {
    let mut coprime = vec![1, 2];
    let mut ntrip = 2;
    let mut n = 3;

    while n < 50 {
        let gcd1 = gcd(n, coprime[ntrip - 1]);
        let gcd2 = gcd(n, coprime[ntrip - 2]);

        if gcd1 == 1 && gcd2 == 1 && not_in_list(n, &coprime) {
            coprime.push(n);
            ntrip += 1;
            n = 3;
        } else {
            n += 1;
        }
    }

    for (i, &value) in coprime.iter().enumerate() {
        print!("{:2} ", value);
        if (i + 1) % 10 == 0 {
            println!();
        }
    }

    println!("\n\nNumber of elements in coprime triplets: {}\n\n", ntrip);
}

