const PRIME_COUNT: usize = 100_000;

fn is_prime(n: i64, primes: &[i64]) -> bool {
    if let Some(&p) = primes.iter().find(|&&p| p == n) {
        return true;
    }
    for &p in primes {
        if n % p == 0 {
            return false;
        }
        if p * p > n {
            break;
        }
    }
    true
}

fn initialize() -> Vec<i64> {
    let mut primes = vec![2, 3, 5, 7, 11, 13, 17, 19];
    let mut i = 21;
    while primes.len() < PRIME_COUNT {
        if is_prime(i, &primes) {
            primes.push(i);
        }
        i += 2;
        if primes.len() < PRIME_COUNT && is_prime(i, &primes) {
            primes.push(i);
        }
        i += 2;
    }
    primes
}

