    let mut s = [0; 8];
    for a in 0..2 {
        for b in 0..10 {
            s[0] = a + b;
            for c in 0..10 {
                s[1] = s[0] + c;
                for d in 0..10 {
                    s[2] = s[1] + d;
                    for e in 0..10 {
                        s[3] = s[2] + e;
                        for f in 0..10 {
                            s[4] = s[3] + f;
                            for g in 0..10 {
                                s[5] = s[4] + g;
                                for h in 0..10 {
                                    s[6] = s[5] + h;
                                    for i in 0..10 {
                                        s[7] = s[6] + i;
                                        for j in 0..10 {
                                            sv[s[7] + j + n] = TRUE;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

fn main() {
    let mut count = 0;
    let start = Instant::now();
    let mut sv = vec![FALSE; MAX_COUNT];
    sieve(&mut sv);
    println!("The first 50 self numbers are:");
    for (index, &value) in sv.iter().enumerate() {
        if value == FALSE {
            if count < 50 {
                print!("{} ", index);
            }
            count += 1;
            if count == 100 * MILLION {
                println!("\n\nThe 100 millionth self number is {}", index);
                break;
            }
        }
    }
    println!("\nTook {:.2} seconds.", start.elapsed().as_secs_f64());
}

