use std::collections::HashSet;

fn sieve(limit: u64) -> Vec<bool> {
    let mut c = vec![false; (limit + 1) as usize];
    c[0] = true;
    c[1] = true;
    for i in (4..=limit).step_by(2) {
        c[i as usize] = true;
    }
    let mut p = 3;
    while p * p <= limit {
        let p2 = p * p;
        for i in (p2..=limit).step_by((2 * p) as usize) {
            c[i as usize] = true;
        }
        p += 2;
        while c[p as usize] {
            p += 2;
        }
    }
    c
}

struct Digits {
    digs: [u8; 20],
    count: usize,
}

fn get_digits(n: u64) -> Digits {
    if n == 0 {
        return Digits { digs: [0; 20], count: 1 };
    }
    let mut d = Digits { digs: [0; 20], count: 0 };
    let mut num = n;
    while num > 0 {
        d.digs[d.count] = (num % 10) as u8;
        d.count += 1;
        num /= 10;
    }
    d
}

fn main() {
    const LIMIT: u64 = 10_000_000_000;
    let c = sieve(LIMIT);
    let primes: Vec<u64> = c.iter().enumerate()
        .filter_map(|(i, &is_not_prime)| if !is_not_prime { Some(i as u64) } else { None })
        .collect();
    let mut orm25 = [0; 25];
    let mut counts = [0; 2];
    let mut count = 0;
    let mut count2 = 0;
    let mut j = LIMIT / 10;
    for window in primes.windows(3) {
        let &[p1, p2, p3] = window else { break; };
        if (p2 - p1) % 18 != 0 || (p3 - p2) % 18 != 0 {
            continue;
        }
        let key1 = get_digits(p1).digs[..get_digits(p1).count]
            .iter()
            .map(|&d| primes[d as usize])
            .product::<u64>();
        let key2 = get_digits(p2).digs[..get_digits(p2).count]
            .iter()
            .map(|&d| primes[d as usize])
            .product::<u64>();
        if key1 != key2 {
            continue;
        }
        let key3 = get_digits(p3).digs[..get_digits(p3).count]
            .iter()
            .map(|&d| primes[d as usize])
            .product::<u64>();
        if key2 == key3 {
            if count < 25 {
                orm25[count] = p1;
            }
            if p1 >= j {
                counts[count2] = count;
                count2 += 1;
                j *= 10;
            }
            count += 1;
        }
    }
    counts[count2] = count;
    println!("Smallest members of first 25 Ormiston triples:");
    for (i, &orm) in orm25.iter().enumerate() {
        print!("{:>10}  ", orm);
        if (i + 1) % 5 == 0 {
            println!();
        }
    }
    println!();
    j = LIMIT / 10;
    for i in 0..2 {
        println!("{} Ormiston triples before {}", counts[i], j);
        j *= 10;
        println!();
    }
}

