type Ulong = u64;

fn root(base: Ulong, n: Ulong) -> Ulong {
    if base < 2 {
        return base;
    }
    if n == 0 {
        return 1;
    }

    let n1 = n - 1;
    let n2 = n;
    let mut c = 1;
    let mut d = (n1 + base) / n2;
    let mut e = (n1 * d + base / (d.pow(n1 as u32))) / n2;

    while c != d && c != e {
        c = d;
        d = e;
        e = (n1 * e + base / (e.pow(n1 as u32))) / n2;
    }

    if d < e { d } else { e }
}

