            }
            let f = a[k + i * n];
            for j in k..n {
                a[j + i * n] -= a[j + k * n] * f;
            }
            for j in 0..n {
                b[j + i * n] -= b[j + k * n] * f;
            }
        }
    }

    Ok(())
}

