use std::collections::HashSet;

struct IntArray {
    ptr: Vec<i32>,
}

impl IntArray {
    fn new(size: usize) -> Self {
        IntArray {
            ptr: vec![0; size],
        }
    }

    fn zero_fill(&mut self) {
        for val in &mut self.ptr {
            *val = 0;
        }
    }

    fn index_of(&self, n: i32) -> Option<usize> {
        self.ptr.iter().position(|&x| x == n)
    }
}

fn get_digits(n: i32, le: usize, digits: &mut IntArray) -> bool {
    let mut seen = HashSet::new();
    let mut num = n;
    let mut length = le;

    while num > 0 {
        let r = num % 10;
        if r == 0 || seen.contains(&r) {
            return false;
        }
        length -= 1;
        digits.ptr[length] = r;
        seen.insert(r);
        num /= 10;
    }

    length == 0
}

fn remove_digit(digits: &IntArray, le: usize, idx: usize) -> i32 {
    let powers = [1, 10, 100, 1000, 10000];
    let mut sum = 0;
    let mut power = powers[le - 2];

    for (i, &digit) in digits.ptr.iter().enumerate() {
        if i == idx {
            continue;
        }
        sum += digit * power;
        power /= 10;
    }

    sum
}

fn main() {
    let lims = [(12, 97), (123, 986), (1234, 9875), (12345, 98764)];
    let mut count = [0; 5];
    let mut omitted = [[0; 10]; 5];

    for (i, &(lower, upper)) in lims.iter().enumerate() {
        let mut n_digits = IntArray::new(i + 2);
        let mut d_digits = IntArray::new(i + 2);

        for n in lower..=upper {
            n_digits.zero_fill();
            if !get_digits(n, i + 2, &mut n_digits) {
                continue;
            }
            for d in (n + 1)..=(upper + 1) {
                d_digits.zero_fill();
                if !get_digits(d, i + 2, &mut d_digits) {
                    continue;
                }
                for (nix, &digit) in n_digits.ptr.iter().enumerate() {
                    if let Some(dix) = d_digits.index_of(digit) {
                        let rn = remove_digit(&n_digits, i + 2, nix);
                        let rd = remove_digit(&d_digits, i + 2, dix);
                        if (n as f64 / d as f64) == (rn as f64 / rd as f64) {
                            count[i] += 1;
                            omitted[i][digit as usize] += 1;
                            if count[i] <= 12 {
                                println!("{} / {} = {} / {} by omitting {}'s", n, d, rn, rd, digit);
                            }
                        }
                    }
                }
            }
        }

        println!();

        drop(n_digits);
        drop(d_digits);
    }

    for i in 2..=5 {
        println!("There are {} {}-digit fractions of which:", count[i - 2], i);

        for j in 1..=9 {
            if omitted[i - 2][j] == 0 {
                continue;
            }
            println!("{:6} have {}'s omitted", omitted[i - 2][j], j);
        }

        println!();
    }
}

