const LIMIT: usize = 3000;

fn init_sieve(sieve: &mut [u8], limit: usize) {
    sieve.fill(1);
    sieve[0] = 0;
    sieve[1] = 0;

    for i in 2..limit {
        if sieve[i] == 1 {
            for j in (i + i..limit).step_by(i) {
                sieve[j] = 0;
            }
        }
    }
}

fn strange_unique_prime_triplets(sieve: &[u8], limit: usize, verbose: bool) {
    let mut count = 0;
    let mut primes = Vec::new();

    for (i, &is_prime) in sieve.iter().enumerate() {
        if is_prime == 1 {
            primes.push(i);
        }
    }

    if verbose {
        println!("Strange unique prime triplets < {}: ", limit);
    }

    for i in 0..primes.len().saturating_sub(2) {
        let pi = primes[i];
        for j in (i + 1)..primes.len().saturating_sub(1) {
            let pj = primes[j];
            for k in (j + 1)..primes.len() {
                let pk = primes[k];
                let sum = pi + pj + pk;
                if sum < LIMIT && sieve[sum] == 1 {
                    count += 1;
                    if verbose {
                        println!("{:2} + {:2} + {:2} = {}", pi, pj, pk, sum);
                    }
                }
            }
        }
    }

    println!("Count of strange unique prime triplets < {} is {}.\n", limit, count);
}

fn main() {
    let mut sieve = vec![0; LIMIT];

    init_sieve(&mut sieve, LIMIT);

    strange_unique_prime_triplets(&sieve, 30, true);
    strange_unique_prime_triplets(&sieve, 1000, false);
}

