use std::cmp::{max, min};
use std::f64;

type XInt = u64;

fn ndigits(mut x: XInt) -> usize {
    let mut n = 0;
    while x > 0 {
        n += 1;
        x /= 10;
    }
    n
}

fn dtally(mut x: XInt) -> XInt {
    let mut t = 0;
    while x > 0 {
        t += 1 << ((x % 10) * 6);
        x /= 10;
    }
    t
}

fn fangs(x: XInt, f: &mut [XInt]) -> usize {
    let mut n = 0;
    let nd = ndigits(x);
    if nd % 2 != 0 {
        return 0;
    }
    let nd = nd / 2;

    let tens: [XInt; 20] = {
        let mut tens = [0; 20];
        tens[0] = 1;
        for i in 1..20 {
            tens[i] = tens[i - 1] * 10;
        }
