#include<stdio.h>

int isPrime(unsigned int n)
{
	unsigned int num;

	if ( n < 2||!(n & 1)) 
		return n == 2;

	for (num = 3; num <= n/num; num += 2)
		if (!(n % num)) 
			return 0;
	return 1;
}

int main()
{
	unsigned int l,u,i,sum=0;

	printf("Enter lower and upper bounds: ");
	scanf("%ld%ld",&l,&u);

	for(i=l;i<=u;i++){
		if(isPrime(i)==1)
			{
				printf("\n%ld",i);
				sum++;
			}
	}

	printf("\n\nPrime numbers found in [%ld,%ld] : %ld",l,u,sum);

	return 0;
}

d63fa3d4bf5702ef1a6b109be5559304.rust_code:
use std::io::{self, Write};

fn is_prime(n: u32) -> bool {
    if n < 2 || n % 2 == 0 {
        return n == 2;
    }

    let limit = (n as f64).sqrt() as u32;
    for num in (3..=limit).step_by(2) {
        if n % num == 0 {
            return false;
        }
    }
    true
}

fn main() {
    print!("Enter lower and upper bounds: ");
    io::stdout().flush().unwrap();

    let mut input = String::new();
    io::stdin().read_line(&mut input).expect("Failed to read line");

    let bounds: Vec<u32> = input.split_whitespace()
        .map(|s| s.trim().parse().expect("Please type a number!"))
        .collect();

    let (l, u) = match bounds.as_slice() {
        [l, u] => (*l, *u),
        _ => panic!("Please enter exactly two numbers"),
    };

    let mut sum = 0;
    for i in l..=u {
        if is_prime(i) {
            println!("{}", i);
            sum += 1;
        }
    }

    println!("\nPrime numbers found in [{},{}] : {}", l, u, sum);
}

