use std::cmp;

type U64 = u64;

fn prime_factors(mut n: U64) -> Vec<U64> {
    if n < 2 {
        return Vec::new();
    }
    let mut factors = Vec::new();
    let inc = [4, 2, 4, 2, 4, 6, 2, 6];
    while n % 2 == 0 {
        factors.push(2);
        n /= 2;
    }
    while n % 3 == 0 {
        factors.push(3);
        n /= 3;
    }
    while n % 5 == 0 {
        factors.push(5);
        n /= 5;
    }
    let mut k = 7;
    let mut i = 0;
    while k * k <= n {
        if n % k == 0 {
            factors.push(k);
            n /= k;
        } else {
            k += inc[i];
            i = (i + 1) % 8;
        }
    }
    if n > 1 {
        factors.push(n);
    }
    factors
}

fn d(mut n: f64) -> f64 {
    if n < 0.0 {
        return -d(-n);
    }
    if n < 2.0 {
        return 0.0;
    }
    let mut factors = Vec::new();
    if n < 1e19 {
        factors = prime_factors(n as U64);
    } else {
        let g = (n / 100.0) as U64;
        factors = prime_factors(g);
        factors.extend_from_slice(&[2, 2, 5, 5]);
    }
    let length = factors.len();
    if length == 1 {
        return 1.0;
    }
    if length == 2 {
        return factors[0] as f64 + factors[1] as f64;
    }
    let d = n / factors[0] as f64;
    d * factors[0] as f64 + d
}

fn main() {
    let mut ad = vec![0; 200];
    for n in -99..=100 {
        ad[(n + 99) as usize] = d(n as f64) as U64;
    }
    for (i, &value) in ad.iter().enumerate() {
        print!("{:4} ", value);
        if (i + 1) % 10 == 0 {
            println!();
        }
    }
    println!();
    let mut pow = 1.0;
    for m in 1..=20 {
        pow *= 10.0;
        println!("D(10^{:<2}) / 7 = {:.0}", m, d(pow) / 7.0);
    }
}

