#include <stdio.h>

int F(int n,int x,int y) {
  if (n == 0) {
    return x + y;
  }

  else if (y == 0) {
    return x;
  }

  return F(n - 1, F(n, x, y - 1), F(n, x, y - 1) + y);
}

int main() {
  printf("F1(3,3) = %d",F(1,3,3));
  return 0;
}

849983f3b35496ae5b0bb1affed281d0.rust_code:
fn f(n: i32, x: i32, y: i32) -> i32 {
    match (n, y) {
        (0, _) => x + y,
        (_, 0) => x,
        _ => {
            let recursive_call = f(n, x, y - 1);
            f(n - 1, recursive_call, recursive_call + y)
        }
    }
}

fn main() {
    println!("F1(3,3) = {}", f(1, 3, 3));
}

