    printf("Enter arabic number:\n");
    scanf("%d", &N);
    printf("\nRoman number:\n");

    for (int i = 0; i < 13; i++) {
        while (N >= arabic[i]) {
            printf("%s", roman[i]);
            N -= arabic[i];
        }
    }
    return 0;
}

854d3d8233009e87c8fb7d8239cdbc0f.rust_code:
use std::io::{self, Write};

fn main() -> io::Result<()> {
    let arabic = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
    let roman = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"];

    print!("Enter arabic number:\n");
    io::stdout().flush()?;
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let n: i32 = input.trim().parse().expect("Please enter a valid integer");

    print!("\nRoman number:\n");
    let mut remaining = n;
    for (&value, &symbol) in arabic.iter().zip(roman.iter()) {
        while remaining >= value {
            print!("{}", symbol);
            remaining -= value;
        }
    }
    println!();

    Ok(())
}

