#include <stdio.h>
#include <sys/mman.h>
#include <string.h>

int test (int a, int b)
{

  char code[] = {0x8B, 0x44, 0x24, 0x4, 0x3, 0x44, 0x24, 0x8, 0xC3};
  void *buf;
  int c;

  buf = mmap (0,sizeof(code),PROT_READ|PROT_WRITE|PROT_EXEC,
             MAP_PRIVATE|MAP_ANON,-1,0);

  memcpy (buf, code, sizeof(code));

  c = ((int (*) (int, int))buf)(a, b);

  munmap (buf, sizeof(code));
  return c;
}

int main ()
{
  printf("%d\n", test(7,12));
  return 0;
}

854d3d8233009e87c8fb7d8239cdbc0f.rust_code:
use std::arch::asm;
use std::ptr;

fn test(a: i32, b: i32) -> i32 {
    let code: [u8; 9] = [0x8B, 0x44, 0x24, 0x4, 0x3, 0x44, 0x24, 0x8, 0xC3];
    let mut buf = vec![0u8; code.len()];

    unsafe {
        ptr::copy_nonoverlapping(code.as_ptr(), buf.as_mut_ptr(), code.len());
        let func: fn(i32, i32) -> i32 = std::mem::transmute(buf.as_ptr());
        func(a, b)
    }
}

fn main() {
    println!("{}", test(7, 12));
}

