    let list = [3.0, 1.0, 4.0, 1.0, 5.0, 9.0];

    println!("{}", squaredsum(Some(&list), 6));
    println!("{}", squaredsum(Some(&list), 0));

    println!("{}", squaredsum(None, 0));
}

