#include <stdio.h>

int common_len(const char *const *names, int n, char sep)
{
	int i, pos;
	for (pos = 0; ; pos++) {
		for (i = 0; i < n; i++) {
			if (names[i][pos] != '\0' &&
					names[i][pos] == names[0][pos])
				continue;


			while (pos > 0 && names[0][--pos] != sep);
			return pos;
		}
	}

	return 0;
}

int main()
{
	const char *names[] = {
		"/home/user1/tmp/coverage/test",
		"/home/user1/tmp/covert/operator",
		"/home/user1/tmp/coven/members",
	};
	int len = common_len(names, sizeof(names) / sizeof(const char*), '/');

	if (!len) printf("No common path\n");
	else      printf("Common path: %.*s\n", len, names[0]);

	return 0;
}

e91877bb8ad4fc3ae70e76dc6ae29bfb.rust_code:
fn common_len(names: &[&str], sep: char) -> usize {
    for pos in 0.. {
        for &name in names {
            if let Some(c) = name.chars().nth(pos) {
                if c == names[0].chars().nth(pos).unwrap() {
                    continue;
                }
            }

            let mut rev_pos = pos;
            while rev_pos > 0 && names[0].chars().nth(rev_pos - 1).unwrap() != sep {
                rev_pos -= 1;
            }
            return rev_pos;
        }
    }

    0
}

fn main() {
    let names = [
        "/home/user1/tmp/coverage/test",
        "/home/user1/tmp/covert/operator",
        "/home/user1/tmp/coven/members",
    ];
    let len = common_len(&names, '/');

    if len == 0 {
        println!("No common path");
    } else {
        println!("Common path: {}", &names[0][..len]);
    }
}

