#include <stdio.h>
#include <string.h>
#include <stdlib.h>


char * incr(char *s)
{
	int i, begin, tail, len;
	int neg = (*s == '-');
	char tgt = neg ? '0' : '9';


	if (!strcmp(s, "-1")) {
		s[0] = '0', s[1] = '\0';
		return s;
	}

	len = strlen(s);
	begin = (*s == '-' || *s == '+') ? 1 : 0;


	for (tail = len - 1; tail >= begin && s[tail] == tgt; tail--);

	if (tail < begin && !neg) {

		if (!begin) s = realloc(s, len + 2);
		s[0] = '1';
		for (i = 1; i <= len - begin; i++) s[i] = '0';
		s[len + 1] = '\0';
	} else if (tail == begin && neg && s[1] == '1') {

		for (i = 1; i < len - begin; i++) s[i] = '9';
		s[len - 1] = '\0';
	} else { 
		for (i = len - 1; i > tail; i--)
			s[i] = neg ? '9' : '0';
		s[tail] += neg ? -1 : 1;
	}

	return s;
}

void string_test(const char *s)
{
	char *ret = malloc(strlen(s));
	strcpy(ret, s);

	printf("text: %s\n", ret);
	printf("  ->: %s\n", ret = incr(ret));
	free(ret);
}

int main()
{
	string_test("+0");
	string_test("-1");
	string_test("-41");
	string_test("+41");
	string_test("999");
	string_test("+999");
	string_test("109999999999999999999999999999999999999999");
	string_test("-100000000000000000000000000000000000000000000");

	return 0;
}

58910afd4f48c621035b95c89c6b8ac0.rust_code:
fn incr(mut s: String) -> String {
    let neg = s.starts_with('-');
    let tgt = if neg { '0' } else { '9' };

    if s == "-1" {
        return "0".to_string();
    }

    let mut chars: Vec<char> = s.chars().collect();
    let begin = if neg || s.starts_with('+') { 1 } else { 0 };

    let mut tail = chars.len() - 1;
    while tail >= begin && chars[tail] == tgt {
        tail -= 1;
    }

    if tail < begin && !neg {
        chars.insert(0, '1');
        for i in 1..chars.len() {
            chars[i] = '0';
        }
    } else if tail == begin && neg && chars[1] == '1' {
        for i in 1..chars.len() - 1 {
            chars[i] = '9';
        }
        chars.pop();
    } else {
        for i in (tail + 1..chars.len()).rev() {
            chars[i] = if neg { '9' } else { '0' };
        }
        chars[tail] = if neg { (chars[tail] as u8 - 1) as char } else { (chars[tail] as u8 + 1) as char };
    }

    chars.into_iter().collect()
}

fn string_test(s: &str) {
    let mut ret = s.to_string();

    println!("text: {}", ret);
    ret = incr(ret);
    println!("  ->: {}\n", ret);
}

fn main() {
    string_test("+0");
    string_test("-1");
    string_test("-41");
    string_test("+41");
    string_test("999");
    string_test("+999");
    string_test("109999999999999999999999999999999999999999");
    string_test("-100000000000000000000000000000000000000000000");
}

