fn incr(mut s: String) -> String {
    let neg = s.starts_with('-');
    let tgt = if neg { '0' } else { '9' };

    if s == "-1" {
        return "0".to_string();
    }

    let begin = if s.starts_with(|c| c == '-' || c == '+') { 1 } else { 0 };

    let mut tail = s.len() - 1;
    while tail >= begin && s.chars().nth(tail).unwrap() == tgt {
        tail -= 1;
    }

    if tail < begin && !neg {
        let mut new_s = vec!['1'];
        new_s.extend(std::iter::repeat('0').take(s.len() - begin));
        s = new_s.into_iter().collect();
    } else if tail == begin && neg && s.chars().nth(1).unwrap() == '1' {
        s.replace_range(1.., &std::iter::repeat('9').take(s.len() - begin - 1).collect::<String>());
    } else {
        for i in (tail + 1..s.len()).rev() {
            s.replace_range(i..=i, if neg { "9" } else { "0" });
        }
        let tail_char = s.chars().nth(tail).unwrap();
        s.replace_range(tail..=tail, &(if neg { (tail_char as u8 - 1) as char } else { (tail_char as u8 + 1) as char }).to_string());
    }

    s
}

fn string_test(s: &str) {
    let mut ret = s.to_string();

    println!("text: {}", ret);
    ret = incr(ret);
    println!("  ->: {}", ret);
}

fn main() {
    string_test("+0");
    string_test("-1");
    string_test("-41");
    string_test("+41");
    string_test("999");
    string_test("+999");
    string_test("109999999999999999999999999999999999999999");
    string_test("-100000000000000000000000000000000000000000000");
}

