    let mut fact = vec![0u64; 12];
    fact[0] = 1;
    for n in 1..12 {
        fact[n] = fact[n - 1] * n as u64;
    }

    for &base in &[9, 10, 11, 12] {
        println!("The factorions for base {} are:", base);
        for i in 1..1500000 {
            let mut sum = 0;
            let mut j = i;
            while j > 0 {
                let digit = j % base as u64;
                sum += fact[digit as usize];
                j /= base as u64;
            }
            if sum == i {
                print!("{} ", i);
            }
        }
        println!();
    }
}

