use std::io::{self, BufRead, BufReader};

fn cusip_check(cusip_str: &str) -> u8 {
    let mut sum = 0;

    for (i, c) in cusip_str.chars().take(8).enumerate() {
        let v = match c {
            '0'..='9' => c as u8 - b'0',
            'A'..='Z' => c as u8 - b'A' + 10,
            '*' => 36,
            '@' => 37,
            '#' => 38,
            _ => continue,
        };

        let v = if i % 2 != 0 { v * 2 } else { v };
        sum += v / 10 + v % 10;
    }

    (10 - (sum % 10)) % 10
}

