use std::f64;
use std::str::FromStr;

#[derive(Debug, Clone, Copy)]
struct Point {
    x: f64,
    y: f64,
}

fn line_slope(a: Point, b: Point) -> f64 {
    if (a.x - b.x).abs() < f64::EPSILON {
        f64::NAN
    } else {
        (a.y - b.y) / (a.x - b.x)
    }
}

fn extract_point(s: &str) -> Result<Point, &'static str> {
    let mut parts = s.trim_matches(|c| c == '(' || c == ')').split(',');
    let x = parts.next().and_then(|s| f64::from_str(s).ok()).ok_or("Invalid x value")?;
    let y = parts.next().and_then(|s| f64::from_str(s).ok()).ok_or("Invalid y value")?;
    Ok(Point { x, y })
}

fn intersection_point(a1: Point, a2: Point, b1: Point, b2: Point) -> Point {
    let slope_a = line_slope(a1, a2);
    let slope_b = line_slope(b1, b2);

    if slope_a == slope_b {
        Point { x: f64::NAN, y: f64::NAN }
    } else if slope_a.is_nan() && !slope_b.is_nan() {
        Point { x: a1.x, y: (a1.x - b1.x) * slope_b + b1.y }
    } else if slope_b.is_nan() && !slope_a.is_nan() {
        Point { x: b1.x, y: (b1.x - a1.x) * slope_a + a1.y }
    } else {
        let x = (slope_a * a1.x - slope_b * b1.x + b1.y - a1.y) / (slope_a - slope_b);
        let y = slope_b * (x - b1.x) + b1.y;
        Point { x, y }
    }
}

fn main() {
    use std::env;

    let args: Vec<String> = env::args().collect();
    if args.len() < 5 {
        eprintln!("Usage: {} <four points specified as (x,y) separated by a space>", args[0]);
    } else {
        match (
            extract_point(&args[1]),
            extract_point(&args[2]),
            extract_point(&args[3]),
            extract_point(&args[4]),
        ) {
            (Ok(a1), Ok(a2), Ok(b1), Ok(b2)) => {
                let c = intersection_point(a1, a2, b1, b2);
                if c.x.is_nan() {
                    println!("The lines do not intersect, they are either parallel or co-incident.");
                } else {
                    println!("Point of intersection: ({},{})", c.x, c.y);
                }
            }
            _ => eprintln!("Invalid point format"),
        }
    }
}

