const MAXIMUM: usize = 25000;

fn reverse(mut n: i32, base: i32) -> i32 {
    let mut r = 0;
    while n != 0 {
        r = r * base + n % base;
        n /= base;
    }
    r
}

fn palindrome(n: i32, base: i32) -> bool {
    n == reverse(n, base)
}

fn main() {
    let mut c = 0;
    for i in 0..MAXIMUM {
        if palindrome(i as i32, 2) && palindrome(i as i32, 4) && palindrome(i as i32, 16) {
            print!("{:5}{}", i, if (c + 1) % 12 == 0 { '\n' } else { ' ' });
